add({ name = "tlg_diesel_can_away", timeout = 60, fn = function()
    local inv = player():getInventory()
    local function cans() return inv:getCountTypeRecurse("Base.PetrolCan") end
    local n0, w0 = cans(), inv:getCapacityWeight()
