            mats = { { "Base.Hammer", 1, true }, { "Base.Plank", 6 }, { "Base.Nails", 12 }, { "Base.EmptyJar", 1 } } },
        { recipe = "TLG_MakePotStill", out = "TLG.PotStill", search = "Pot Still", keep = true,
