        { recipe = "TLG_MakeFuelStabilizer", out = "TLG.FuelStabilizer", search = "Stabilizer",
            mats = { { "Base.Charcoal", 2 }, { "Base.EmptyJar", 1 } } },
        -- The biodiesel chain's machines (D-036). The retort's bucket is
