        "TLG.FermenterVessel", "TLG.PotStill", "TLG.RefluxStill", "TLG.DryingColumn", "TLG.FuelSampleKit", "TLG.FuelFilter",
        "TLG.FuelStabilizer", "Base.MetalDrum", "Base.MetalBar", "Base.BucketEmpty", "Base.CheeseCloth", "TLG.WoodRetort",
        "TLG.AshBarrel", "TLG.LyeLeacher", "TLG.BiodieselReactor", "TLG.BiodieselWashTank" },
}

function RT.CR.window() return ISEntityUI.GetWindowInstance(0, "HandcraftWindow") end
function RT.CR.panel() local w = RT.CR.window(); return w and w.handCraftPanel end
function RT.CR.list()
    local p = RT.CR.panel()
    return p and p.recipesPanel and p.recipesPanel.recipeListPanel and p.recipesPanel.recipeListPanel.recipeListPanel
end
function RT.CR.control()
    local p = RT.CR.panel()
    return p and p.recipePanel and p.recipePanel.craftControl
end
-- The recipe objects the window's query holds (run 191:
-- ScriptManager.getCraftRecipe found none of them by their short names).
function RT.CR.recipe(name)
    RT.CR.byName = RT.CR.byName or windowRecipes()
    return RT.CR.byName[name]
end
-- The list's row holding `recipe` (group rows hold none), and its text.
function RT.CR.row(recipe)
    local lb = RT.CR.list()
    for i, it in ipairs(lb and lb.items or {}) do
        if it.item ~= nil and it.item == recipe then return i, it.text end
    end
    return nil, nil
end
-- Typing in the search box: its text, then the handler a keystroke calls.
function RT.CR.search(text)
    local box = RT.CR.panel().recipesPanel.recipeFilterPanel.searchEntryBox
    box:setText(text)
    ISWidgetRecipeFilterPanel.onTextChange(box)
end
function RT.CR.state()
    local p, c = RT.CR.panel(), RT.CR.control()
    local logic = p and p.logic
    local sat = "?"
    pcall(function() sat = tostring(logic:getRecipeData():areAllInputItemsSatisfied()) end)
    return string.format("selected=%s inputsSatisfied=%s craftEnabled=%s inProgress=%s surface=%s",
        tostring(logic and logic:getRecipe() and logic:getRecipe():getName()), sat, tostring(c and c.buttonCraft and c.buttonCraft.enable),
        tostring(logic and logic:isCraftActionInProgress()), tostring(p and p.isoObject ~= nil))
end
-- What the game does when a container's contents change (Events.OnContainerUpdate
-- -> ISInventoryPage.dirtyUI -> refreshBackpacks -> ISHandCraftPanel.drawDirty).
function RT.CR.handOver(list)
    for _, m in ipairs(list) do give(m[1], m[2]) end
    triggerEvent("OnContainerUpdate")
end

RT.CR.setup = { name = "rtcr_setup", timeout = 1200, fn = function(ctx, ticks)
    if not ctx.t0 then
        local p = player()
        p:setGodMod(true)
        p:setInvisible(true)
        pcall(function() p:setUnlimitedCarry(true) end)
        p:setPerkLevelDebug(Perks.Woodwork, 2)
        -- The biodiesel machines ask welding levels and a learned recipe
        -- (0.4.0; request "sp-rthb" checks both): given here.
        p:setPerkLevelDebug(Perks.MetalWelding, 5)
        for _, n in ipairs(TLG.Integration.Manual.HANDBOOK_RECIPES) do p:learnRecipe(n) end
        for _, t in ipairs(RT.CR.cleared) do removeAll(t) end
        RT.CR.surface, RT.CR.stand = findSurface(10625, 10630, 25)
        if RT.CR.stand then p:teleportTo(RT.CR.stand:getX(), RT.CR.stand:getY(), RT.CR.stand:getZ()) end
        ctx.t0 = ticks
        return nil
    end
    if ticks - ctx.t0 < 60 then return nil end
    local spriteName = "?"
    pcall(function() spriteName = RT.CR.surface:getSprite():getName() end)
    R:check("RTCR.workbench_found", function()
        return RT.CR.stand ~= nil, RT.CR.stand and string.format("%s at %d,%d, standing at %d,%d", spriteName,
            RT.CR.surface:getSquare():getX(), RT.CR.surface:getSquare():getY(), RT.CR.stand:getX(), RT.CR.stand:getY())
            or "none within 25 tiles"
    end)
    -- Crafting needs light (phase A's loop_craft, runs 36-37): a torch in hand.
    if player():tooDarkToRead() then
        local here = player():getSquare()
        RT.CR.torch = player():getInventory():AddItem("Base.HandTorch")
        RT.CR.torch:setActivated(true)
        player():setSecondaryHandItem(RT.CR.torch)
        R:line("OBS  RTCR.dark (light %.2f at %.2f o'clock): a torch switched on in hand, dark now=%s",
            here and here:getLightLevel(0) or -1, getGameTime():getTimeOfDay(), tostring(player():tooDarkToRead()))
    end
    return true
end }

RT.CR.open = { name = "rtcr_open", timeout = 600, fn = function(ctx, ticks)
    if ticks == 1 then
        local pd = getPlayerData(0)
        local btn = pd and pd.equipped and pd.equipped.craftingBtn
        R:line("OBS  RTCR.button craftingBtn=%s visible=%s", tostring(btn ~= nil), tostring(btn and btn:getIsVisible()))
        if btn then btn:forceClick() end
        return nil
    end
    if ticks < 40 then return nil end
    local w, p = RT.CR.window(), RT.CR.panel()
    R:check("RTCR.window_opens", function()
        local n = "?"
        pcall(function() n = tostring(CraftRecipeManager.queryRecipes(p.recipeQuery):size()) end)
        return w ~= nil and w:getIsVisible() and p ~= nil, w and string.format(
            "title=%s query=%s recipes=%s surface=%s listMode=%s", tostring(w.windowHeader and w.windowHeader.titleStr),
            tostring(p and p.recipeQuery), n, tostring(p and p.isoObject ~= nil),
            tostring(p and p.recipesPanel and p.recipesPanel.recipeListMode)) or "no window"
    end)
    if not p then RT.abort = "the crafting window did not open"; return true end
    -- The recipes are shown as a list or as a grid of icons; the button
    -- beside the search box switches, as a player would, to the list.
    if not p.recipesPanel.recipeListMode then
        p.recipesPanel.recipeFilterPanel.viewModeButton:forceClick()
        R:line("OBS  RTCR.view switched to the list: listMode=%s", tostring(p.recipesPanel.recipeListMode))
    end
    return true
end }

-- The names the window shows, read with nothing to craft them from.
RT.CR.namesStep = { name = "rtcr_names", timeout = 300, fn = function(ctx, ticks)
    if RT.skip("rtcr_names") then return true end
    if ticks < 20 then return nil end
    local listed = windowRecipes()
    for _, s in ipairs(RT.CR.specs) do
        local r = listed[s.recipe]
        local want = RT.CR.names[s.recipe]
        local shown = r and r:getTranslationName()
        R:check("RTCR.name_" .. s.recipe, function()
            return shown == want, string.format("shows '%s', want '%s'", tostring(shown), want)
        end)
        local row, text = RT.CR.row(r)
        local cat
        pcall(function() cat = r:getCategory() end)
        R:line("OBS  RTCR.row_without_materials %s row=%s text=%s category=%s", s.recipe, tostring(row), tostring(text),
            tostring(cat))
    end
    return true
end }

function RT.CR.craft(s)
    local short = string.match(s.out, "([^%.]+)$")
    return { name = "rtcr_" .. short, timeout = 9000, fn = function(ctx, ticks)
        if RT.skip("rtcr_" .. short) then return true end
        local recipe = RT.CR.recipe(s.recipe)
        local lb, p = RT.CR.list(), RT.CR.panel()
        if not (lb and p) then
            R:check("RTCR.craft_" .. s.out, function() return false, "the crafting window is gone" end)
            return true
        end
        if not ctx.phase then
            ctx.base = {}
            for _, m in ipairs(s.mats) do ctx.base[m[1]] = countType(m[1]) end
            for _, t in ipairs(s.consumes or {}) do ctx.base[t] = countType(t) end
            ctx.base[s.out] = countType(s.out)
            local now = {}
            for _, m in ipairs(s.mats) do if m[1] ~= s.withhold then now[#now + 1] = m end end
            RT.CR.handOver(now)
            if s.emptied then
                local list = player():getInventory():getItemsFromFullType(s.emptied)
                for i = 0, (list and list:size() or 0) - 1 do
                    local fc = list:get(i):getFluidContainer()
                    if fc then fc:Empty() end
                end
                triggerEvent("OnContainerUpdate")
            end
            ctx.phase, ctx.at = "search", ticks
            return nil
        end
        if ctx.phase == "search" then
            if ticks - ctx.at < 10 then return nil end
            if not ctx.typed then
                RT.CR.search(RT.CR.names[s.recipe])
                ctx.typed, ctx.at = true, ticks
                return nil
            end
            local row, text = RT.CR.row(recipe)
            R:check("RTCR.found_by_name_" .. short, function()
                return row ~= nil, string.format("typed '%s': row=%s text=%s rows=%d", RT.CR.names[s.recipe], tostring(row),
                    tostring(text), lb and #lb.items or -1)
            end)
            local row2
            RT.CR.search(s.search)
            row2 = RT.CR.row(recipe)
            R:line("OBS  RTCR.search '%s' row=%s rows=%d", s.search, tostring(row2), lb and #lb.items or -1)
            RT.CR.search("")
            ctx.phase, ctx.at = "select", ticks
            return nil
        end
        if ctx.phase == "select" then
            if ticks - ctx.at < 10 then return nil end
            local row = RT.CR.row(recipe)
            if not row and ticks - ctx.at < 300 then return nil end
            if not row then
                R:check("RTCR.craft_" .. s.out, function()
                    return false, string.format("no row for the recipe with the search cleared (recipe=%s, %d rows)",
                        tostring(recipe ~= nil), #lb.items)
                end)
                return true
            end
            -- The row's click (ISRecipeScrollingListBox.onMouseDown).
            lb.selected = row
            lb.onmousedown(lb.target, lb.items[row].item)
            ctx.phase, ctx.at = s.withhold and "refuse" or "ready", ticks
            return nil
        end
        if ctx.phase == "refuse" then
            if ticks - ctx.at < 60 then return nil end
            if not ctx.pressed then
                ctx.stateBefore = RT.CR.state()
                local c = RT.CR.control()
                if c and c.buttonCraft then c.buttonCraft:forceClick() end
                ctx.pressed, ctx.at = true, ticks
                return nil
            end
            if ticks - ctx.at < 30 then return nil end
            local c = RT.CR.control()
            R:check("RTCR.refused_without_" .. s.withhold, function()
                return c ~= nil and c.buttonCraft.enable == false and TLGH.Steps.actionsIdle(player())
                    and countType(s.out) == ctx.base[s.out],
                    string.format("before the press: %s; after: queued=%s made=%d", ctx.stateBefore,
                        tostring(not TLGH.Steps.actionsIdle(player())), countType(s.out) - ctx.base[s.out])
            end)
            for _, m in ipairs(s.mats) do if m[1] == s.withhold then RT.CR.handOver({ m }) end end
            ctx.phase, ctx.at = "ready", ticks
            return nil
        end
        if ctx.phase == "ready" then
            local c = RT.CR.control()
            local logic = p.logic
            local ok = logic:getRecipe() == recipe and c ~= nil and c.buttonCraft.enable == true
            if not ok and ticks - ctx.at < 600 then return nil end
            R:line("OBS  RTCR.%s ready after %d ticks: %s", short, ticks - ctx.at, RT.CR.state())
            if s.double then
                -- A double-click on the row (ISHandCraftPanel.onDoubleClick).
                local row = RT.CR.row(recipe)
                lb.onmousedblclick(lb.target, lb.items[row].item)
            elseif c then
                c.buttonCraft:forceClick()
            end
            ctx.phase, ctx.at = "wait", ticks
            return nil
        end
        if ctx.phase == "wait" then
            if ticks - ctx.at == 10 then
                ctx.queued = not TLGH.Steps.actionsIdle(player())
            end
            if ticks - ctx.at < 30 then return nil end
            if (not TLGH.Steps.actionsIdle(player()) or p.logic:isCraftActionInProgress()) and ticks - ctx.at < 8000 then
                return nil
            end
            local made = countType(s.out) - ctx.base[s.out]
            local wrong = {}
            for _, m in ipairs(s.mats) do
                local want = ctx.base[m[1]] + (m[3] and m[2] or 0)
                if countType(m[1]) ~= want then
                    wrong[#wrong + 1] = string.format("%s=%d(want %d)", m[1], countType(m[1]), want)
                end
            end
            for _, t in ipairs(s.consumes or {}) do
                if countType(t) ~= ctx.base[t] - 1 then
                    wrong[#wrong + 1] = string.format("%s=%d(want %d)", t, countType(t), ctx.base[t] - 1)
                end
            end
            R:check("RTCR.craft_" .. s.out, function()
                return ctx.queued == true and made == 1 and #wrong == 0,
                    string.format("via %s: queued=%s made=%d inputs wrong=[%s] took %d ticks; %s",
                        s.double and "double-click" or "Craft button", tostring(ctx.queued), made, table.concat(wrong, ","),
                        ticks - ctx.at, RT.CR.state())
            end)
            -- Tools and leftovers go; the pot still stays for the reflux still.
            for _, m in ipairs(s.mats) do removeAll(m[1]) end
            if not s.keep then removeAll(s.out) end
            triggerEvent("OnContainerUpdate")
            return true
        end
        return nil
    end }
end

RT.CR.close = { name = "rtcr_close", timeout = 300, fn = function(ctx, ticks)
    if ticks == 1 then
        local w = RT.CR.window()
        if w then w:close() end
        return nil
    end
    if ticks < 20 then return nil end
    R:check("RTCR.window_closes", function()
        return not ISEntityUI.IsWindowOpen(0, "HandcraftWindow"), "open=" .. tostring(ISEntityUI.IsWindowOpen(0, "HandcraftWindow"))
    end)
    if RT.CR.torch then
        player():setSecondaryHandItem(nil)
        removeAll("Base.HandTorch")
    end
    return true
end }

------------------------------------------------------------------------------
-- Death and a successor (request "sp-rtsu"). Survivor A loads two
-- fermenters at the station, takes a petrol can and looks at it (Look and
-- smell: A's knowledge, player modData tlgKnowledge), and takes the second
-- fermenter into both arms (the loot window's double-click way). A is
-- killed (IsoGameCharacter.Kill) and the game's own screens make survivor B
-- in the same world: the post-death Respawn button, then Next through the
-- spawn region, the occupation and the character (ISPostDeathUI,
-- CoopCharacterCreation), as a player clicks them. B is then brought to
-- the body and checked against what A left:
--   * the world record (seed, epoch, installation) unchanged;
--   * B knows nothing of A's fuel (knowledge belongs to a character);
--   * the placed fermenter worked on through the death;
--   * the can and the carried fermenter are found with A's body (or on the
--     floor), their records as A left them, the carried one not worked;
--   * B takes the can from the body, looks at it, and knows it then;
--   * B takes the fermenter from the body into both arms and puts it down;
--     it works again from then, and both fermenters work an hour later.
-- Items are found again by their record ids after B arrives: the area may
-- have been unloaded while B spawned elsewhere (RT.refind's reason).
RT.SU = { x = START.x, y = START.y }

function RT.SU.side(it)
    return it and sidecar(it:getModData()) or "none"
end

-- Every item of the scene by its record id: on the floor around (x, y)
-- and in any body's container there.
function RT.SU.find()
    local U, found = RT.SU, {}
    local function look(it)
        local p = it:getModData().tlgProc
        if p and p.id then found[p.id] = it end
        local s = it:getModData().tlg
        if s and s.id then found[s.id] = it end
    end
    for dx = -4, 4 do
        for dy = -4, 4 do
            local s = sq(U.x + dx, U.y + dy, 0)
            local objs = s and s:getWorldObjects()
            for i = 0, (objs and objs:size() or 0) - 1 do
                local it = objs:get(i):getItem()
                if it then look(it) end
            end
            local bodies
            pcall(function() bodies = s and s:getDeadBodys() end)
            for i = 0, (bodies and bodies:size() or 0) - 1 do
                local c = bodies:get(i):getContainer()
                local items = c and c:getItems()
                for j = 0, (items and items:size() or 0) - 1 do look(items:get(j)) end
                U.body = U.body or bodies:get(i)
            end
        end
    end
    return found
end

function RT.SU.where(it)
    if not it then return "missing" end
    if it:getWorldItem() then
        local s = it:getWorldItem():getSquare()
        return string.format("on the floor at %d,%d", s:getX(), s:getY())
    end
    local c = it:getContainer()
    local parent = c and c:getParent()
    return string.format("in container %s of %s", tostring(c and c:getType()),
        tostring(parent and (instanceof(parent, "IsoDeadBody") and "a dead body" or tostring(parent))))
end

RT.SU.setup = { name = "rtsu_setup", timeout = 3000, fn = function(ctx, ticks)
    local U = RT.SU
    if not ctx.t0 then
        local p = player()
        U.a = p
        p:setGodMod(false)
        p:setInvisible(true)
        captureDialogs(true)
        p:teleportTo(U.x + 1, U.y + 1, 0)
        ctx.t0 = ticks
        return nil
    end
    if ticks - ctx.t0 < 60 then return nil end
    if not ctx.placed then
        U.items = {}
        for i = 1, 2 do
            local it = instanceItem("TLG.FermenterVessel")
            sq(U.x + i, U.y, 0):AddWorldInventoryItem(it, 0.5, 0.5, 0, false)
            U.items[i] = it
        end
        ctx.placed = ticks
        return nil
    end
    if ticks - ctx.placed < 30 then return nil end
    for i, it in ipairs(U.items) do
        give("Base.Sugar", 6); give("Base.Yeast", 1)
        for _ = 1, 3 do
            local fc = player():getInventory():AddItem("Base.BucketEmpty"):getFluidContainer()
            fc:Empty()
            fc:addFluid(Fluid.Water, 10)
        end
        local r = machineClick("RTSU.load_F" .. i, it, "ContextMenu_TLG_LoadFerment")
        R:check("RTSU.loaded_F" .. i, function()
            return r.ok == true, string.format("sugar=%s water=%s reason=%s", tostring(r.sugarKg), tostring(r.waterL), tostring(r.reason))
        end)
    end
    closeDialogs()
    U.pid = { U.items[1]:getModData().tlgProc.id, U.items[2]:getModData().tlgProc.id }
    -- A's can, recorded and looked at.
    U.can = giveCan("Base.PetrolCan", { { Fluid.Petrol, 6 } })
    local fill = function(c) TLG.UI.FuelMenu.fill(0, c, { U.can }) end
    local n = #H.dialogs.texts
    menuClick("RTSU.a_look", fill, getText("ContextMenu_TLG_Fuel"), getText("ContextMenu_TLG_Look"))
    local look = H.dialogs.texts[n + 1]
    closeDialogs()
    U.canId = U.can:getModData().tlg and U.can:getModData().tlg.id
    local know = player():getModData().tlgKnowledge or {}
    R:check("RTSU.a_knows_the_can", function()
        return U.canId ~= nil and know[tostring(U.canId)] ~= nil, string.format("can %s; look: %s", tostring(U.canId), tostring(look))
    end)
    U.h0 = hours()
    return true
end }

-- An hour and a half on the clock, then A takes F2 into both arms.
RT.SU.carry = { name = "rtsu_carry", timeout = 30000, fn = function(ctx, ticks)
    local U = RT.SU
    if not ctx.waited then
        RT.speed(RT.waitSpeed)
        if hours() - U.h0 < 1.5 then return nil end
        RT.speed(1)
        ctx.waited = ticks
        return nil
    end
    local F2 = U.items[2]
    if not ctx.queued then
        -- Records catch up when read: Status brings both up to now.
        if not ctx.read then
            RT.statusOf(U.items[1])
            RT.statusOf(F2)
            U.carryFrom = RT.doneHours(F2)
            ctx.read = true
        end
        -- The loot window lists the floor items beside the character; the
        -- double-click takes from that list (run 197: F2 two tiles away had
        -- no container and the take failed).
        pcall(function() getPlayerLoot(0):refreshBackpacks() end)
        if F2:getContainer() == nil and ticks - ctx.waited < 120 then return nil end
        ISInventoryPaneContextMenu.equipHeavyItem(player(), F2)
        ctx.queued = ticks
        return nil
    end
    if ticks - ctx.queued < 10 or not TLGH.Steps.actionsIdle(player()) then return nil end
    local p, pl = F2:getModData().tlgProc or {}, player()
    R:check("RTSU.a_carries_F2", function()
        return pl:getPrimaryHandItem() == F2 and pl:getSecondaryHandItem() == F2 and p.state == "Paused",
            string.format("both hands=%s state=%s pause=%s done=%.3f h", tostring(pl:getPrimaryHandItem() == F2
                and pl:getSecondaryHandItem() == F2), tostring(p.state), tostring(p.pause), RT.doneHours(F2))
    end)
    return true
end }

RT.SU.die = { name = "rtsu_die", timeout = 2400, fn = function(ctx, ticks)
    local U = RT.SU
    if not ctx.killed then
        RT.statusOf(U.items[1])
        RT.statusOf(U.items[2])
        local w = TLGH.worldRecord()
        U.world = string.format("seed=%s epoch=%s installedAt=%s policy=%s", tostring(w.seed), tostring(w.epoch),
            tostring(w.installedAt), tostring(w.policy))
        U.before = { F1 = RT.doneHours(U.items[1]), F2 = RT.doneHours(U.items[2]), can = U.side(U.can),
            F2rec = TLG.Tables.deepCopy(U.items[2]:getModData().tlgProc), at = hours() }
        local s = U.a:getSquare()
        U.deathAt = { x = s:getX(), y = s:getY() }
        R:line("OBS  RTSU.before_death %s; F1 done %.4f h, F2 done %.4f h (carried); can %s; A at %d,%d",
            U.world, U.before.F1, U.before.F2, U.before.can, U.deathAt.x, U.deathAt.y)
        U.a:setGodMod(false)
        local ok, err = pcall(function() U.a:Kill(nil) end)
        if not ok then
            R:line("OBS  RTSU.kill Kill(nil) failed (%s); health set to 0 instead", tostring(err))
            U.a:setHealth(0)
        end
        ctx.killed = ticks
        return nil
    end
    if ticks - ctx.killed < 30 then return nil end
    local ui = ISPostDeathUI.instance and ISPostDeathUI.instance[0]
    if not (U.a:isDead() and ui) and ticks - ctx.killed < 600 then return nil end
    -- The body comes some moments after the death (run 197: none after 30 ticks).
    if not U.body then U.find() end
    if not U.body and ticks - ctx.killed < 1800 then return nil end
    R:check("RTSU.a_died", function()
        return U.a:isDead(), string.format("dead=%s post-death screen=%s", tostring(U.a:isDead()), tostring(ui ~= nil))
    end)
    local found = U.find()
    local f2 = found[U.pid[2]]
    local p = f2 and f2:getModData().tlgProc or {}
    R:line("OBS  RTSU.after_death body=%s; can %s; F2 %s, its record %s/%s from %s; F1 %s", tostring(U.body ~= nil),
        U.where(found[U.canId]), U.where(f2), tostring(p.state), tostring(p.pause), tostring(p.t), U.where(found[U.pid[1]]))
    return true
end }

-- The game's own screens, clicked as a player does.
RT.SU.respawn = { name = "rtsu_respawn", timeout = 6000, fn = function(ctx, ticks)
    local U = RT.SU
    ctx.clicks = ctx.clicks or {}
    local b = getPlayer()
    if b and b ~= U.a and not b:isDead() then
        if not ctx.spawned then
            ctx.spawned = ticks
            return nil
        end
        if ticks - ctx.spawned < 60 then return nil end
        U.b = b
        R:check("RTSU.successor_made", function()
            return true, string.format("screens: %s; B at %d,%d", table.concat(ctx.clicks, " > "), b:getSquare():getX(),
                b:getSquare():getY())
        end)
        return true
    end
    if ctx.last and ticks - ctx.last < 30 then return nil end
    local ui = ISPostDeathUI.instance and ISPostDeathUI.instance[0]
    local cc = CoopCharacterCreation.instance
    if cc then
        if cc.mapSpawnSelect:getIsVisible() then
            cc.mapSpawnSelect:clickNext()
            ctx.clicks[#ctx.clicks + 1] = "spawn region Next"
        elseif cc.charCreationProfession:getIsVisible() then
            cc.charCreationProfession.playButton:forceClick()
            ctx.clicks[#ctx.clicks + 1] = "occupation Next"
        elseif cc.charCreationMain:getIsVisible() then
            cc.charCreationMain.playButton:forceClick()
            ctx.clicks[#ctx.clicks + 1] = "character Play"
        end
    elseif ui and ui.buttonRespawn and ui.buttonRespawn:getIsVisible() then
        ui.buttonRespawn:forceClick()
        ctx.clicks[#ctx.clicks + 1] = "Respawn"
    end
    ctx.last = ticks
    return nil
end }

RT.SU.arrive = { name = "rtsu_arrive", timeout = 1200, fn = function(ctx, ticks)
    local U = RT.SU
    if not ctx.t0 then
        captureDialogs(true)
        U.b:setInvisible(true)
        U.b:teleportTo(U.x + 1, U.y + 1, 0)
        ctx.t0 = ticks
        return nil
    end
    if ticks - ctx.t0 < 120 then return nil end
    local found = U.find()
    U.F1, U.F2, U.can = found[U.pid[1]], found[U.pid[2]], found[U.canId]
    local w = TLGH.worldRecord()
    local world = string.format("seed=%s epoch=%s installedAt=%s policy=%s", tostring(w.seed), tostring(w.epoch),
        tostring(w.installedAt), tostring(w.policy))
    R:check("RTSU.world_record_kept", function() return world == U.world, world .. " (before: " .. U.world .. ")" end)
    R:check("RTSU.successor_is_another_character", function()
        return U.b ~= U.a and not U.b:isDead() and U.a:isDead(), string.format("B %s, A dead=%s",
            tostring(U.b:getDescriptor() and U.b:getDescriptor():getForename()), tostring(U.a:isDead()))
    end)
    R:check("RTSU.successor_knows_nothing_yet", function()
        local know = U.b:getModData().tlgKnowledge
        local n = 0
        for _ in pairs(know or {}) do n = n + 1 end
        return n == 0, string.format("%d observations", n)
    end)
    R:check("RTSU.left_items_found", function()
        return U.F1 ~= nil and U.F2 ~= nil and U.can ~= nil, string.format("F1 %s; F2 %s; can %s", U.where(U.F1),
            U.where(U.F2), U.where(U.can))
    end)
    if not (U.F1 and U.F2 and U.can) then RT.abort = "items left by A not found"; return true end
    R:check("RTSU.can_record_as_left", function()
        return U.side(U.can) == U.before.can, U.side(U.can) .. " (before: " .. U.before.can .. ")"
    end)
    -- The game drops a heavy item at the feet when its carrier dies (run 198:
    -- F2 on the floor at A's square, the can in the body), where no Lua sees
    -- it. Runs 198-199: the batch stayed paused until the mod next found it
    -- placed, the time before uncredited. Since the death hook (Machines
    -- onDeath, D-015 amendment) it is put down when it lands: it works from
    -- the death, as F1 does over the same time.
    local p1 = TLG.Tables.deepCopy(U.F2:getModData().tlgProc or {})
    local st2 = RT.statusOf(U.F2)
    local st1 = RT.statusOf(U.F1)
    local p2 = U.F2:getModData().tlgProc or {}
    local w2, w1 = RT.doneHours(U.F2) - U.before.F2, RT.doneHours(U.F1) - U.before.F1
    local dt = hours() - U.before.at
    R:check("RTSU.dropped_F2_works_from_the_death", function()
        return U.F2:getWorldItem() ~= nil and p1.state == "Processing" and p1.pause == nil and st2.ok == true
            and st1.ok == true and p2.state == "Processing" and w2 > 0 and math.abs(w2 - w1) <= 0.002 + 0.05 * dt,
            string.format("%s; before Status %s/%s (put down at %.4f, died at %.4f); over %.4f game h since the death: F2 %.4f h of work, F1 %.4f h",
                U.where(U.F2), tostring(p1.state), tostring(p1.pause), p1.t or -1, U.before.at, dt, w2, w1)
    end)
    local st = RT.statusOf(U.F1)
    R:check("RTSU.placed_F1_answers_the_successor", function()
        return st.ok == true and RT.doneHours(U.F1) >= U.before.F1, string.format("status ok=%s state=%s; done %.4f h (at death %.4f, %.4f game h since)",
            tostring(st.ok), tostring(st.state), RT.doneHours(U.F1), U.before.F1, hours() - U.before.at)
    end)
    return true
end }

-- B takes the can out of the body (the loot window's transfer) and looks.
RT.SU.can = { name = "rtsu_can", timeout = 1200, fn = function(ctx, ticks)
    local U = RT.SU
    if RT.skip("rtsu_can") then return true end
    if not ctx.queued then
        ISTimedActionQueue.add(ISInventoryTransferAction:new(U.b, U.can, U.can:getContainer(), U.b:getInventory()))
        ctx.queued = ticks
        return nil
    end
    if ticks - ctx.queued < 10 or not TLGH.Steps.actionsIdle(U.b) then return nil end
    R:check("RTSU.successor_took_the_can", function()
        return U.can:getContainer() == U.b:getInventory() and U.side(U.can) == U.before.can, U.where(U.can) .. "; " .. U.side(U.can)
    end)
    local fill = function(c) TLG.UI.FuelMenu.fill(0, c, { U.can }) end
    local n = #H.dialogs.texts
    menuClick("RTSU.b_look", fill, getText("ContextMenu_TLG_Fuel"), getText("ContextMenu_TLG_Look"))
    local look = H.dialogs.texts[n + 1]
    closeDialogs()
    n = #H.dialogs.texts
    menuClick("RTSU.b_what_i_know", fill, getText("ContextMenu_TLG_Fuel"), getText("ContextMenu_TLG_ShowKnown"))
    local shown = H.dialogs.texts[n + 1]
    closeDialogs()
    local know = U.b:getModData().tlgKnowledge or {}
    R:check("RTSU.successor_knows_after_a_look", function()
        return has(look, getText("IGUI_TLG_InspectionTitle")) and know[tostring(U.canId)] ~= nil,
            string.format("look: %s | what I know: %s", tostring(look), tostring(shown))
    end)
    return true
end }

-- B takes F2 out of the body into both arms, then puts it down.
RT.SU.vessel = { name = "rtsu_vessel", timeout = 3000, fn = function(ctx, ticks)
    local U = RT.SU
    if RT.skip("rtsu_vessel") then return true end
    if not ctx.queued then
        ctx.t0 = ctx.t0 or ticks
        pcall(function() getPlayerLoot(0):refreshBackpacks() end)
        if U.F2:getContainer() == nil and ticks - ctx.t0 < 120 then return nil end
        R:line("OBS  RTSU.b_takes_F2 from %s", U.where(U.F2))
        ISInventoryPaneContextMenu.equipHeavyItem(U.b, U.F2)
        ctx.queued = ticks
        return nil
    end
    if not ctx.held then
        if ticks - ctx.queued < 10 or not TLGH.Steps.actionsIdle(U.b) then return nil end
        R:check("RTSU.successor_carries_F2", function()
            return U.b:getPrimaryHandItem() == U.F2 and U.b:getSecondaryHandItem() == U.F2, U.where(U.F2)
        end)
        forceDropHeavyItems(U.b)
        ctx.held = ticks
        return nil
    end
    if ticks - ctx.held < 30 then return nil end
    local st = RT.statusOf(U.F2)
    local p = U.F2:getModData().tlgProc or {}
    U.downAt, U.downDone = hours(), RT.doneHours(U.F2)
    R:check("RTSU.F2_put_down_works_again", function()
        return U.F2:getWorldItem() ~= nil and st.ok == true and p.state ~= "Paused",
            string.format("%s; status ok=%s state=%s pause=%s; done %.4f h", U.where(U.F2), tostring(st.ok), tostring(p.state),
                tostring(p.pause), U.downDone)
    end)
    U.h1, U.f1At = hours(), RT.doneHours(U.F1)
    return true
end }

RT.SU.after = { name = "rtsu_after", timeout = 30000, fn = function(ctx, ticks)
    local U = RT.SU
    if RT.skip("rtsu_after") then return true end
    RT.speed(RT.waitSpeed)
    if hours() - U.h1 < 1 then return nil end
    RT.speed(1)
    RT.statusOf(U.F1)
    RT.statusOf(U.F2)
    local dh = hours() - U.h1
    local w1, w2 = RT.doneHours(U.F1) - U.f1At, RT.doneHours(U.F2) - U.downDone
    R:check("RTSU.both_work_on", function()
        return w1 > 0.5 * dh and w2 > 0.5 * dh and math.abs(w1 - w2) < 0.05 * dh + 1e-6,
            string.format("over %.3f game h: F1 %.4f h of work, F2 %.4f h", dh, w1, w2)
    end)
    return true
end }

------------------------------------------------------------------------------
-- What I know about a fuel (request "sp-rtkn"), as the Fuel menu shows it. A
-- petrol can with a little water (0.8 %: a kit finds it, a look does not)
-- is tested with the sampling kit and, two game hours later, looked at.
-- What I know about it is read before any test, after both, after the can
-- is opened from the Fuel menu, after a litre is poured out of it, after a
-- new look, and from an entry in the shape knowledge had before (the last
-- observation alone). Run 200 read it before the fix.
RT.KN = {}

function RT.KN.menu(label, key)
    local can = RT.KN.can
    local fill = function(c) TLG.UI.FuelMenu.fill(0, c, { can }) end
    local n = #H.dialogs.texts
    local r = menuClick(label, fill, getText("ContextMenu_TLG_Fuel"), getText(key))
    local text = H.dialogs.texts[n + 1]
    closeDialogs()
    return text, r
end

function RT.KN.known(label)
    local text = RT.KN.menu("RTKN." .. label, "ContextMenu_TLG_ShowKnown")
    R:line("OBS  RTKN.%s What I know: %s", label, tostring(text))
    return text or ""
end

-- A dialog's lines (rich text " <LINE> " separators).
function RT.KN.lines(text)
    local out, s, i = {}, text or "", 1
    while true do
        local a, b = string.find(s, " <LINE> ", i, true)
        if not a then out[#out + 1] = string.sub(s, i); break end
        out[#out + 1] = string.sub(s, i, a - 1)
        i = b + 1
    end
    return out
end

function RT.KN.count(text, part)
    local n, i = 0, 1
    while true do
        local a, b = string.find(text or "", part, i, true)
        if not a then return n end
        n, i = n + 1, b + 1
    end
end

RT.KN.setup = { name = "rtkn_setup", timeout = 600, fn = function(ctx, ticks)
    if ticks == 1 then
        player():setGodMod(true)
        player():setInvisible(true)
        captureDialogs(true)
        removeAll("TLG.FuelSampleKit")
        give("TLG.FuelSampleKit", 1)
        RT.KN.can = giveCan("Base.PetrolCan", { { Fluid.Petrol, 6 }, { Fluid.Water, 0.05 } })
        RT.KN.empty = giveCan("Base.PetrolCan", {})
        return nil
    end
    if ticks < 30 then return nil end
    local fc = RT.KN.can:getFluidContainer()
    local water = -1
    pcall(function() water = fc:getSpecificFluidAmount(Fluid.Water) end)
    R:line("OBS  RTKN.can %.3f L, water %.3f L", fc:getAmount(), water)
    local text = RT.KN.known("before_any_test")
    R:check("RTKN.unknown_before_any_test", function()
        return has(text, getText("IGUI_TLG_ConditionUnknown")), text
    end)
    return true
end }

RT.KN.kit = { name = "rtkn_kit", timeout = 600, fn = function(ctx, ticks)
    local text = RT.KN.menu("RTKN.kit", "ContextMenu_TLG_SampleKit")
    RT.KN.kitText = text or ""
    R:line("OBS  RTKN.kit result: %s", tostring(text))
    R:check("RTKN.kit_sample_answers", function()
        return has(text, getText("IGUI_TLG_InspectionTitle")), tostring(text)
    end)
    RT.KN.t0 = hours()
    return true
end }

RT.KN.wait = { name = "rtkn_wait", timeout = 30000, fn = function(ctx, ticks)
    RT.speed(RT.waitSpeed)
    if hours() - RT.KN.t0 < 2 then return nil end
    RT.speed(1)
    return true
end }

RT.KN.look = { name = "rtkn_look", timeout = 600, fn = function(ctx, ticks)
    local text = RT.KN.menu("RTKN.look", "ContextMenu_TLG_Look")
    R:line("OBS  RTKN.look result: %s", tostring(text))
    local known = RT.KN.known("after_both")
    -- The kit's own composition line (a look tells no composition).
    local label = string.gsub(getText("IGUI_TLG_Composition", ""), "%s+$", "")
    local kitLine
    for _, l in ipairs(RT.KN.lines(RT.KN.kitText)) do
        if has(l, label) then kitLine = l end
    end
    R:check("RTKN.kit_result_kept_after_a_look", function()
        return kitLine ~= nil and has(known, kitLine), string.format("the kit's line %s", tostring(kitLine))
    end)
    R:check("RTKN.both_tests_named", function()
        return has(known, getText("IGUI_TLG_TestName_kit")) and has(known, getText("IGUI_TLG_TestName_visual")), known
    end)
    local h = tostring(math.floor(hours() - RT.KN.t0))
    R:check("RTKN.when_each_test_was_done", function()
        return has(known, getText("IGUI_TLG_Ago_Hours", h)) and has(known, getText("IGUI_TLG_Ago_Now")),
            string.format("want '%s' (the kit) and '%s' (the look)", getText("IGUI_TLG_Ago_Hours", h),
                getText("IGUI_TLG_Ago_Now"))
    end)
    R:check("RTKN.no_open_note_while_sealed", function() return not has(known, getText("IGUI_TLG_KnownOpen")), known end)
    return true
end }

RT.KN.open = { name = "rtkn_open", timeout = 600, fn = function(ctx, ticks)
    local _, r = RT.KN.menu("RTKN.unseal", "ContextMenu_TLG_Unseal")
    local side = RT.KN.can:getModData().tlg
    local known = RT.KN.known("opened")
    R:check("RTKN.open_note", function()
        return side ~= nil and side.sealed == false and has(known, getText("IGUI_TLG_KnownOpen")),
            string.format("sealed=%s; %s", tostring(side and side.sealed), known)
    end)
    return true
end }

RT.KN.pour = { name = "rtkn_pour", timeout = 600, fn = function(ctx, ticks)
    if ticks == 1 then
        FluidContainer.Transfer(RT.KN.can:getFluidContainer(), RT.KN.empty:getFluidContainer(), 1.0)
        return nil
    end
    if ticks < 20 then return nil end
    local known = RT.KN.known("poured")
    local note = getText("IGUI_TLG_KnownChanged")
    R:check("RTKN.changed_since_both_tests", function()
        return RT.KN.count(known, note) == 2, string.format("%d notes; %s", RT.KN.count(known, note), known)
    end)
    RT.KN.menu("RTKN.look_again", "ContextMenu_TLG_Look")
    local again = RT.KN.known("looked_again")
    R:check("RTKN.a_new_look_is_current", function()
        return RT.KN.count(again, note) == 1, string.format("%d notes (the kit's only); %s", RT.KN.count(again, note), again)
    end)
    return true
end }

-- Knowledge saved before the fix held the last observation alone.
RT.KN.oldEntry = { name = "rtkn_old_entry", timeout = 600, fn = function(ctx, ticks)
    local side = RT.KN.can:getModData().tlg
    local know = player():getModData().tlgKnowledge or {}
    local entry = side and know[tostring(side.id)]
    local kitObs = entry and (entry.kit or (entry.method == "kit" and entry) or nil)
    if side then know[tostring(side.id)] = kitObs end
    local known = RT.KN.known("old_entry")
    R:check("RTKN.reads_knowledge_saved_before", function()
        return kitObs ~= nil and has(known, getText("IGUI_TLG_TestName_kit"))
            and not has(known, getText("IGUI_TLG_TestName_visual")), known
    end)
    closeDialogs()
    return true
end }

------------------------------------------------------------------------------
-- What I know across a save (requests "sp-rtkns", then "sp-rtknb"): the
-- same can tested with the kit and, two game hours later, looked at, then
-- saved and exited to the menu, sealed and untouched since the look. The
-- expectations file holds the can's record id and revision, both tests'
-- times and readings, and the kit's composition line. Phase 2 continues the
-- save: the character's knowledge must come back as saved and the can's
-- record at the same revision, before any read; then What I know about it
-- must list both tests with the kit's composition line, the kit's age gone
-- on from the test, the look's under an hour, no note that the fuel changed
-- (the load must not write the record) and no open note.
local function knownEntry(id)
    local know = player():getModData().tlgKnowledge or {}
    return know[tostring(id)]
end

local function obsText(obs)
    if type(obs) ~= "table" then return "none" end
    return string.format("%s@%s deg=%s err=%s", tostring(obs.method), tostring(obs.sampledAt), tostring(obs.observedDeg),
        tostring(obs.degError))
end

RT.KN.writeExpect = { name = "rtkns_expect", timeout = 300, fn = function(ctx, ticks)
    local side = RT.KN.can:getModData().tlg
    local entry = side and knownEntry(side.id)
    local label = string.gsub(getText("IGUI_TLG_Composition", ""), "%s+$", "")
    local kitLine = ""
    for _, l in ipairs(RT.KN.lines(RT.KN.kitText)) do
        if has(l, label) then kitLine = l end
    end
    local kit, look = obsText(entry and entry.kit), obsText(entry and entry.visual)
    TLGH.writeFile(EXPECT, { "rtkn.id=" .. tostring(side and side.id), "rtkn.rev=" .. tostring(side and side.rev),
        "rtkn.hours=" .. tostring(hours()), "rtkn.t0=" .. tostring(RT.KN.t0), "rtkn.kit=" .. kit, "rtkn.look=" .. look,
        "rtkn.kitLine=" .. kitLine })
    R:line("OBS  RTKNS.saving at world hour %.4f: can %s at revision %s; kit %s; look %s; the kit's line '%s'", hours(),
        tostring(side and side.id), tostring(side and side.rev), kit, look, kitLine)
    R:check("RTKNS.both_tests_known_before_the_save", function()
        return kit ~= "none" and look ~= "none" and kitLine ~= "", string.format("kit %s; look %s", kit, look)
    end)
    return true
end }

RT.KN.reload = { name = "rtknb_reload", timeout = 3000, fn = function(ctx, ticks)
    if not (player() and ticks > 120) then return nil end
    local e = TLGH.readKeyValues(EXPECT)
    if e["rtkn.id"] == nil then
        RT.abort = "no expectations from phase 1"
        R:line("OBS  RTKNB.%s", RT.abort)
        return true
    end
    local p = player()
    p:setGodMod(true)
    p:setInvisible(true)
    captureDialogs(true)
    local list = p:getInventory():getAllEvalRecurse(function(it)
        local s = it:getModData().tlg
        return type(s) == "table" and tostring(s.id) == e["rtkn.id"]
    end)
    RT.KN.can = list:size() > 0 and list:get(0) or nil
    R:line("OBS  RTKNB.continued at world hour %.4f (saved at %s); the can %s found=%s", hours(), tostring(e["rtkn.hours"]),
        e["rtkn.id"], tostring(RT.KN.can ~= nil))
    R:check("RTKNB.can_found", function() return RT.KN.can ~= nil, "by its record id " .. e["rtkn.id"] end)
    if RT.KN.can == nil then
        RT.abort = "the can did not come back"
        return true
    end
    -- Before any read: the character's knowledge and the can's revision.
    local entry = knownEntry(e["rtkn.id"])
    local kit, look = obsText(entry and entry.kit), obsText(entry and entry.visual)
    R:check("RTKNB.knowledge_as_saved", function()
        return kit == e["rtkn.kit"] and look == e["rtkn.look"],
            string.format("kit %s (saved %s); look %s (saved %s)", kit, tostring(e["rtkn.kit"]), look, tostring(e["rtkn.look"]))
    end)
    local rev = tostring(RT.KN.can:getModData().tlg.rev)
    R:check("RTKNB.can_revision_as_saved", function()
        return rev == e["rtkn.rev"], string.format("revision %s (saved %s)", rev, tostring(e["rtkn.rev"]))
    end)
    local known = RT.KN.known("after_reload")
    R:check("RTKNB.both_tests_listed", function()
        return has(known, getText("IGUI_TLG_TestName_kit")) and has(known, getText("IGUI_TLG_TestName_visual")), known
    end)
    R:check("RTKNB.kit_result_kept", function()
        return e["rtkn.kitLine"] ~= "" and has(known, e["rtkn.kitLine"]), "the kit's line " .. tostring(e["rtkn.kitLine"])
    end)
    -- The kit was done two game hours before the look: its age goes on.
    local kitAge = TLG.UI.Format.ago(hours() - tonumber(e["rtkn.t0"]))
    R:check("RTKNB.kit_age_goes_on", function()
        return has(known, getText("IGUI_TLG_KnownTest", getText("IGUI_TLG_TestName_kit"), kitAge)),
            string.format("want '%s' for the kit", kitAge)
    end)
    local fresh = { getText("IGUI_TLG_Ago_Now"), getText("IGUI_TLG_Ago_Minute") }
    for m = 2, 59 do fresh[#fresh + 1] = getText("IGUI_TLG_Ago_Minutes", tostring(m)) end
    local lookFresh = false
    for _, a in ipairs(fresh) do
        if has(known, getText("IGUI_TLG_KnownTest", getText("IGUI_TLG_TestName_visual"), a)) then lookFresh = true end
    end
    R:check("RTKNB.look_under_an_hour_ago", function()
        return lookFresh, string.format("saved %.4f game h after the look's hour", hours() - tonumber(e["rtkn.hours"]))
    end)
    R:check("RTKNB.no_changed_note", function() return not has(known, getText("IGUI_TLG_KnownChanged")), known end)
    R:check("RTKNB.no_open_note", function() return not has(known, getText("IGUI_TLG_KnownOpen")), known end)
    closeDialogs()
    return true
end }

RT.knowledgeSaveSteps = { RT.waitWorld, RT.KN.setup, RT.KN.kit, RT.KN.wait, RT.KN.look, RT.KN.writeExpect,
    RT.saveAndExitAs("rtkns_save_and_exit", "sp-rtknb") }
RT.knowledgeReloadSteps = { RT.KN.reload, RT.finish }

if REQUEST == "sp-rtkn" then
    RT.knowledgeSteps = { RT.waitWorld, RT.KN.setup, RT.KN.kit, RT.KN.wait, RT.KN.look, RT.KN.open, RT.KN.pour,
        RT.KN.oldEntry, RT.finish }
end

------------------------------------------------------------------------------
-- Transfer Liquid (request "sp-rttl"): the game's own window, used as a
-- player uses it. The inventory menu's Fluid > Transfer Liquid on can A
-- (SRC ISFluidContainerMenu.lua:16) opens the window with A as the source;
-- the target is picked from the target box's own menu (what a click on the
-- box opens, SRC ISFluidContainerPanel.lua:61), the slider set and Pour
-- clicked. ISFluidTransferAction then pours a slice per update through
-- FluidContainer.Transfer (SRC ISFluidTransferAction.lua:29,73), which the
-- mod wraps. A holds aged petrol with some of the mod's ethanol, water and
-- sediment, and stabilizer (a fixture on its record).
--   pour1: half of A into empty can B. B must hold A's fuel in A's
--          condition, stabilizer included, and A keep its own.
--   pour2: B taken away, can C with 4 L of fresh petrol given, the rest of
--          A poured into it. C must hold the blend the mod's mixing rules
--          give (deg weighted by each component's litres, stabilizer by fuel
--          litres, microbial growth by all litres), worked out here from
--          both records rather than with the mod's own blend function.
--   pour3: A taken away, empty can D given, all of C poured into it and
--          the pour stopped part-way as a player stops it (the action
--          queue cleared). D must hold the litres that left C, in C's
--          condition, and no record may be written before the stop: the
--          mod follows the action's pour once, when it completes or stops.
-- While the window previews a pour (a Transfer into a copy of the target,
-- SRC ISFluidTransferUI.lua:410), neither can's record may change. After
-- each pour both cans' fluids must hold what their records say. Every
-- FluidContainer.Transfer call is counted on its way in, and the mod's
-- error log is watched for the whole run.
------------------------------------------------------------------------------
RT.TL = { calls = { preview = 0, cans = 0, other = 0 }, errors = {} }

function RT.TL.ui()
    local slot = ISFluidTransferUI.players and ISFluidTransferUI.players[0]
    return slot and slot.instance or nil
end

-- Counts FluidContainer.Transfer calls by what they move between (into a
-- container with no owner: the window's preview copy) and keeps the mod's
-- error lines, until switched off.
function RT.TL.watch(on)
    local TL = RT.TL
    if on and not TL.origTransfer then
        TL.origTransfer = FluidContainer.Transfer
        FluidContainer.Transfer = function(a, b, amount, ...)
            local ok, ao, bo = pcall(function()
                local C = TLG.Integration.Containers
                return (C.ownerOf(a)), (C.ownerOf(b))
            end)
            local k = "other"
            if ok and bo == nil then k = "preview" elseif ok and ao ~= nil then k = "cans" end
            TL.calls[k] = TL.calls[k] + 1
            return TL.origTransfer(a, b, amount, ...)
        end
        TL.origError = TLG.Log.error
        TLG.Log.error = function(fmt, ...)
            local ok, msg = pcall(string.format, fmt, ...)
            TL.errors[#TL.errors + 1] = ok and msg or tostring(fmt)
            return TL.origError(fmt, ...)
        end
    elseif not on and TL.origTransfer then
        FluidContainer.Transfer, TL.origTransfer = TL.origTransfer, nil
        TLG.Log.error, TL.origError = TL.origError, nil
    end
end

function RT.TL.callsText()
    local c = RT.TL.calls
    return string.format("%d preview, %d can to can, %d other", c.preview, c.cans, c.other)
end

-- The inventory menu on a can, as a right-click builds it, and its Fluid >
-- Transfer Liquid entry chosen. Returns whether the entry was there.
function RT.TL.open(label, can)
    local context = ISInventoryPaneContextMenu.createMenu(0, true, { can }, 100, 100)
    local root = context and context:getOptionFromName(getText("ContextMenu_Fluid"))
    local sub = root and root.subOption and context:getSubMenu(root.subOption)
    local opt = sub and sub:getOptionFromName(getText("Fluid_Transfer_Fluids"))
    if context then context:setVisible(false) end
    local usable = opt ~= nil and not opt.notAvailable
    R:line("OBS  %s menu %s=%s > %s=%s", label, getText("ContextMenu_Fluid"), tostring(root ~= nil),
        getText("Fluid_Transfer_Fluids"), tostring(usable))
    if usable then opt.onSelect(opt.target, opt.param1, opt.param2) end
    return usable
end

-- The target box's own menu (the carried containers the window accepts, by
-- name and content) and `can` chosen from it.
function RT.TL.target(label, ui, can)
    local box = ui.panelRight.itemDropBox
    local valid = box:getValidItems()
    local accepted = false
    for _, it in ipairs(valid) do
        if it == can then accepted = true end
    end
    local pick, names = nil, {}
    if #valid > 0 then
        box:onMouseDown(0, 0)
        local menu = getPlayerContextMenu(0)
        for _, o in ipairs(menu and menu.options or {}) do
            names[#names + 1] = tostring(o.name)
            if o.param1 == can then pick = o end
        end
        if menu then menu:setVisible(false) end
    end
    R:line("OBS  %s target box: %d container(s) accepted, its menu [%s]", label, #valid, table.concat(names, " | "))
    if pick then pick.onSelect(pick.target, pick.param1) end
    return accepted and pick ~= nil
end

function RT.TL.shot(name)
    local file = "tlg_rttl_" .. name .. ".png"
    local ok = pcall(function() getCore():TakeFullScreenshot(file) end)
    R:line("OBS  RTTL.screenshot %s ok=%s", file, tostring(ok))
end

-- What the mixing rules give when `litres` of `src` go into `dst`, both
-- advanced to the same hour: the composition, deg, stab and mic.
function RT.TL.blend(src, dst, litres)
    local Defs, Reg = TLG.Domain.FuelDefs, TLG.Registry
    local total = TLG.Domain.Supply.total(src)
    local keys = {}
    for k in pairs(src.q) do keys[k] = true end
    for k in pairs(dst.q) do keys[k] = true end
    local q, deg = {}, {}
    local parcelFuel, parcelAll, dstFuel, dstAll = 0, 0, 0, 0
    for _, k in ipairs(TLG.Tables.sortedKeys(keys)) do
        local p = (src.q[k] or 0) / total * litres
        local d = dst.q[k] or 0
        q[k] = d + p
        parcelAll, dstAll = parcelAll + p, dstAll + d
        if not Defs.isContaminant(k) then parcelFuel, dstFuel = parcelFuel + p, dstFuel + d end
        local def = Reg.get("fuel", k)
        if def and def.aging and q[k] > 0 then
            deg[k] = ((dst.deg[k] or 0) * d + (src.deg[k] or 0) * p) / q[k]
        end
    end
    local stab = ((dst.stab or 0) * dstFuel + (src.stab or 0) * parcelFuel) / (dstFuel + parcelFuel)
    local mic = ((dst.mic or 0) * dstAll + (src.mic or 0) * parcelAll) / (dstAll + parcelAll)
    return q, deg, stab, mic
end

RT.TL.setup = { name = "rttl_setup", timeout = 600, fn = function(ctx, ticks)
    local TL = RT.TL
    if ticks == 1 then
        player():setGodMod(true)
        player():setInvisible(true)
        TL.watch(true)
        removeAll("Base.PetrolCan")
        TL.a = giveCan("Base.PetrolCan", { { Fluid.Petrol, 6 }, { Fluid.Get("TLG_Ethanol"), 1.5 },
            { Fluid.Get("TLG_FuelWater"), 0.06 }, { Fluid.Get("TLG_FuelSediment"), 0.02 } })
        TL.b = giveCan("Base.PetrolCan", {})
        return nil
    end
    if ticks < 30 then return nil end
    -- Fixture: an ageing history and stabilizer on A's record (fuel the mod
    -- finds new has neither).
    local C = TLG.Integration.Containers
    local rec = C.read(TL.a, "item", true)
    if rec then
        for _, k in ipairs(TLG.Tables.sortedKeys(rec.q)) do
            local def = TLG.Registry.get("fuel", k)
            if def and def.aging then rec.deg[k] = (k == "gasoline") and 0.3 or 0.15 end
        end
        rec.stab = 0.6
        C.writeSidecar(TL.a, "item", rec)
    end
    local v = tlgView("item", TL.a)
    R:line("OBS  RTTL.can_a fluids %s; record %s", TLGH.fluidSummary(TL.a:getFluidContainer()), viewText(v, "a"))
    R:line("OBS  RTTL.can_b fluids %s; sidecar %s", TLGH.fluidSummary(TL.b:getFluidContainer()), sidecar(TL.b:getModData()))
    R:check("RTTL.can_a_aged_and_stabilized", function()
        return v ~= nil and (v.deg.gasoline or 0) > 0.2 and (v.stab or 0) > 0.5 and (v.q.ethanol or 0) > 1
            and (v.q.water or 0) > 0 and (v.q.sediment or 0) > 0, viewText(v, "a")
    end)
    return true
end }

-- The largest difference, in litres, between a can's fluids and the
-- composition its record holds, and where.
function RT.TL.recordGap(can)
    local side = can:getModData().tlg
    if side == nil then return math.huge, "no record" end
    local comp = TLG.Integration.Native.readComposition(can:getFluidContainer())
    local worst, where = 0, "-"
    local keys = {}
    for k in pairs(comp) do keys[k] = true end
    for k in pairs(side.q or {}) do keys[k] = true end
    for _, k in ipairs(TLG.Tables.sortedKeys(keys)) do
        local d = math.abs((comp[k] or 0) - ((side.q or {})[k] or 0))
        if d > worst then worst, where = d, k end
    end
    return worst, where
end

-- One pour through the window: `slider` is the share of the most the window
-- allows; `afterPour(ctx, moved, dstView)` adds the pour's own checks.
-- `stopAfter`: ticks after Pour is clicked at which the pour is stopped.
function RT.TL.pourStep(name, getSrc, getDst, slider, emptyDestination, afterPour, stopAfter)
    return { name = "rttl_" .. name, timeout = 6000, fn = function(ctx, ticks)
        local TL = RT.TL
        local label = "RTTL." .. name
        if ticks == 1 then
            ctx.a, ctx.b = getSrc(), getDst()
            if ctx.a == nil or ctx.b == nil then
                R:line("SKIP %s: a can is missing", label)
                return true
            end
            -- Run 214: in pour1, called without it, stopAfter was neither
            -- nil nor a number at the comparison ("__le not defined").
            ctx.stopAt = type(stopAfter) == "number" and stopAfter or nil
            R:line("OBS  %s stopAfter type=%s value=%s", label, type(stopAfter), tostring(stopAfter))
            local fa, fb = ctx.a:getFluidContainer(), ctx.b:getFluidContainer()
            R:line("OBS  %s %s canTransfer=%s", label, loadText(), tostring(FluidContainer.CanTransfer(fa, fb)))
            hopBegin(ctx, label, "item", ctx.a, canAmount(fa), "item", ctx.b, canAmount(fb))
            ctx.side0 = sidecar(ctx.a:getModData()) .. " / " .. sidecar(ctx.b:getModData())
            TL.calls.preview, TL.calls.cans, TL.calls.other = 0, 0, 0
            local opened = TL.open(label, ctx.a)
            R:check(label .. ".menu_offers_transfer_liquid", function() return opened, tostring(opened) end)
            if not opened then return true end
            ctx.phase = "opening"
            return nil
        end
        if ctx.phase == "opening" then
            local ui = TL.ui()
            if ui == nil or not TLGH.Steps.actionsIdle(player()) then return nil end
            ctx.ui = ui
            R:check(label .. ".window_opens_with_the_can_as_source", function()
                return ui.panelLeft:getContainerOwner() == ctx.a and ui.panelRight:getContainerOwner() == nil,
                    string.format("source=%s target=%s", tostring(ui.panelLeft:getContainerOwner()),
                        tostring(ui.panelRight:getContainerOwner()))
            end)
            local picked = TL.target(label, ui, ctx.b)
            R:check(label .. ".target_box_offers_the_can", function() return picked, tostring(picked) end)
            if not picked then return true end
            ui.slider:setCurrentValue(slider)
            ctx.phase, ctx.t0 = "set", ticks
            return nil
        end
        local ui = ctx.ui
        if ctx.phase == "set" then
            if ticks - ctx.t0 == 30 and name == "pour1" then TL.shot(name) end
            if ticks - ctx.t0 < 40 then return nil end
            local side1 = sidecar(ctx.a:getModData()) .. " / " .. sidecar(ctx.b:getModData())
            ctx.planned = ui.info.transferring or 0
            R:line("OBS  %s window open=%s: most %.4f L, pouring %.4f L (slider %.2f); Transfer calls so far: %s",
                label, tostring(TL.ui() == ui), ui.info.maxTransfer or -1, ctx.planned, ui.slider:getCurrentValue(),
                TL.callsText())
            R:check(label .. ".preview_writes_no_record", function()
                return side1 == ctx.side0 and TL.calls.cans == 0,
                    string.format("before: %s; after: %s; can-to-can calls %d", ctx.side0, side1, TL.calls.cans)
            end)
            local enabled = ui.btnTransfer.enable == true and ctx.planned > 0
            R:check(label .. ".pour_enabled", function()
                return enabled, string.format("enable=%s pouring=%.4f message=%s", tostring(ui.btnTransfer.enable),
                    ctx.planned, tostring(ui.errorLabel and ui.errorLabel.name))
            end)
            if not enabled then return true end
            ui.btnTransfer:forceClick()
            local act = ui.action
            R:line("OBS  %s Pour clicked: action=%s amount=%s maxTime=%s instant=%s", label,
                tostring(act and act.Type), tostring(act and act.amount), tostring(act and act.maxTime),
                tostring(player():isTimedActionInstant()))
            ctx.phase, ctx.t0 = "pouring", ticks
            return nil
        end
        if ctx.phase == "pouring" then
            if ctx.stopAt and not ctx.stopped and ticks - ctx.t0 >= ctx.stopAt then
                -- Pouring now: the target has fluids, and the records are
                -- the ones read before the first slice.
                local side = sidecar(ctx.a:getModData()) .. " / " .. sidecar(ctx.b:getModData())
                R:line("OBS  %s stopping at tick %d: dst fluids %s; sidecars %s; Transfer calls: %s", label,
                    ticks - ctx.t0, TLGH.fluidSummary(ctx.b:getFluidContainer()), side, TL.callsText())
                R:check(label .. ".no_record_written_while_pouring", function()
                    return ctx.b:getFluidContainer():getAmount() > 0.5 and side == ctx.side0,
                        string.format("dst %.4f L; before: %s; now: %s", ctx.b:getFluidContainer():getAmount(),
                            ctx.side0, side)
                end)
                ISTimedActionQueue.clear(player())
                ctx.stopped = true
                return nil
            end
            if ticks - ctx.t0 < 10 or not TLGH.Steps.actionsIdle(player()) then return nil end
            R:line("OBS  %s poured in %d ticks; Transfer calls: %s; mod errors so far %d", label, ticks - ctx.t0,
                TL.callsText(), #TL.errors)
            local moved, dv = hopEnd(ctx, emptyDestination)
            R:line("OBS  %s.after fluids src %s dst %s", label, TLGH.fluidSummary(ctx.a:getFluidContainer()),
                TLGH.fluidSummary(ctx.b:getFluidContainer()))
            if ctx.stopAt then
                R:check(label .. ".stopped_part_way", function()
                    return ctx.stopped == true and moved > 0.5 and moved < ctx.planned - 0.5,
                        string.format("moved=%.4f window=%.4f", moved, ctx.planned)
                end)
            else
                R:check(label .. ".moved_what_the_window_showed", function()
                    return math.abs(moved - ctx.planned) <= 1e-3,
                        string.format("moved=%.4f window=%.4f", moved, ctx.planned)
                end)
            end
            R:check(label .. ".fluids_match_records", function()
                local ws, at = TL.recordGap(ctx.a)
                local wd, bt = TL.recordGap(ctx.b)
                return ws <= 1e-4 and wd <= 1e-4,
                    string.format("src worst %.2e at %s; dst worst %.2e at %s", ws, at, wd, bt)
            end)
            R:check(label .. ".poured_through_the_wrapped_call", function()
                return TL.calls.cans > 0, TL.callsText()
            end)
            afterPour(ctx, moved, dv)
            if TL.ui() then TL.ui():close() end
            return true
        end
        return nil
    end }
end

function RT.TL.afterPour1(ctx, moved, dv)
    local now, env = TLG.World.now(), TLG.World.env()
    local s0 = TLG.Domain.Aging.advance(ctx.srcView, now, env)
    local sv = tlgView("item", ctx.a)
    R:check("RTTL.pour1.source_keeps_its_condition", function()
        if sv == nil then return false, "no view of the source" end
        local same, detail = sameFuel(s0, sv, 1e-3)
        return same and math.abs((sv.stab or 0) - (s0.stab or 0)) <= 1e-3,
            string.format("%s; stab %.4f -> %.4f", detail, s0.stab or 0, sv.stab or 0)
    end)
    R:check("RTTL.pour1.stabilizer_carried", function()
        if dv == nil then return false, "no view of the target" end
        return (s0.stab or 0) > 0 and math.abs((dv.stab or 0) - (s0.stab or 0)) <= 1e-3,
            string.format("source %.4f target %.4f", s0.stab or 0, dv.stab or 0)
    end)
end

function RT.TL.afterPour2(ctx, moved, dv)
    local now, env = TLG.World.now(), TLG.World.env()
    local src = TLG.Domain.Aging.advance(ctx.srcView, now, env)
    local dst = TLG.Domain.Aging.advance(ctx.dstView0, now, env)
    local q, deg, stab, mic = RT.TL.blend(src, dst, moved)
    local parts = {}
    for _, k in ipairs(TLG.Tables.sortedKeys(q)) do
        parts[#parts + 1] = string.format("%s=%.4f deg=%s", k, q[k], deg[k] and string.format("%.4f", deg[k]) or "-")
    end
    R:line("OBS  RTTL.pour2 expected by the rules: %s stab=%.4f mic=%.4f", table.concat(parts, ", "), stab, mic)
    R:check("RTTL.pour2.blend_by_the_mixing_rules", function()
        if dv == nil then return false, "no view of the target" end
        local worst, where = math.abs((dv.stab or 0) - stab), "stab"
        if math.abs((dv.mic or 0) - mic) > worst then worst, where = math.abs((dv.mic or 0) - mic), "mic" end
        for _, k in ipairs(TLG.Tables.sortedKeys(q)) do
            local d = math.abs((dv.q[k] or 0) - q[k])
            if d > worst then worst, where = d, "q:" .. k end
            if deg[k] then
                d = math.abs((dv.deg[k] or 0) - deg[k])
                if d > worst then worst, where = d, "deg:" .. k end
            end
        end
        return worst <= 1e-3, string.format("worst=%.2e at %s", worst, where)
    end)
end

function RT.TL.afterPour3(ctx, moved, dv)
    local now, env = TLG.World.now(), TLG.World.env()
    local s0 = TLG.Domain.Aging.advance(ctx.srcView, now, env)
    local sv = tlgView("item", ctx.a)
    R:check("RTTL.pour3.source_keeps_its_condition", function()
        if sv == nil then return false, "no view of the source" end
        local same, detail = sameFuel(s0, sv, 1e-3)
        return same and math.abs((sv.stab or 0) - (s0.stab or 0)) <= 1e-3,
            string.format("%s; stab %.4f -> %.4f", detail, s0.stab or 0, sv.stab or 0)
    end)
    R:check("RTTL.pour3.stabilizer_carried", function()
        if dv == nil then return false, "no view of the target" end
        return (s0.stab or 0) > 0 and math.abs((dv.stab or 0) - (s0.stab or 0)) <= 1e-3,
            string.format("source %.4f target %.4f", s0.stab or 0, dv.stab or 0)
    end)
end

-- A taken away (empty after pour2), empty can D given.
RT.TL.swap2 = { name = "rttl_swap2", timeout = 600, fn = function(ctx, ticks)
    local TL = RT.TL
    if ticks == 1 then
        if TL.a and TL.a:getContainer() then TL.a:getContainer():Remove(TL.a) end
        TL.d = giveCan("Base.PetrolCan", {})
        return nil
    end
    if ticks < 30 then return nil end
    R:line("OBS  RTTL.can_d fluids %s; sidecar %s", TLGH.fluidSummary(TL.d:getFluidContainer()),
        sidecar(TL.d:getModData()))
    return true
end }

-- B taken away (two cans carried per pour), C given with fresh petrol and
-- recorded as a first look records it.
RT.TL.swap = { name = "rttl_swap", timeout = 600, fn = function(ctx, ticks)
    local TL = RT.TL
    if ticks == 1 then
        if TL.b and TL.b:getContainer() then TL.b:getContainer():Remove(TL.b) end
        TL.c = giveCan("Base.PetrolCan", { { Fluid.Petrol, 4 } })
        return nil
    end
    if ticks < 30 then return nil end
    local C = TLG.Integration.Containers
    local rec = C.read(TL.c, "item", true)
    if rec then C.commit(TL.c, "item", rec) end
    R:line("OBS  RTTL.can_c fluids %s; record %s", TLGH.fluidSummary(TL.c:getFluidContainer()),
        viewText(tlgView("item", TL.c), "c"))
    return true
end }

RT.TL.close = { name = "rttl_close", timeout = 300, fn = function(ctx, ticks)
    local TL = RT.TL
    if TL.ui() then TL.ui():close() end
    R:check("RTTL.no_mod_errors", function() return #TL.errors == 0, table.concat(TL.errors, " | ") end)
    TL.watch(false)
    return true
end }

if REQUEST == "sp-rttl" then
    RT.transferSteps = { RT.waitWorld, RT.TL.setup,
        RT.TL.pourStep("pour1", function() return RT.TL.a end, function() return RT.TL.b end, 0.5, true, RT.TL.afterPour1),
        RT.TL.swap,
        RT.TL.pourStep("pour2", function() return RT.TL.a end, function() return RT.TL.c end, 1.0, false, RT.TL.afterPour2),
        RT.TL.swap2,
        RT.TL.pourStep("pour3", function() return RT.TL.c end, function() return RT.TL.d end, 1.0, true, RT.TL.afterPour3,
            80),
        RT.TL.close, RT.finish }
end

if REQUEST == "sp-rtsu" then
    RT.successorSteps = { RT.waitWorld, RT.SU.setup, RT.SU.carry, RT.SU.die, RT.SU.respawn, RT.SU.arrive, RT.SU.can,
        RT.SU.vessel, RT.SU.after, RT.finish }
end

if REQUEST == "sp-rtcr" then
    RT.craftingSteps = { RT.waitWorld, RT.CR.setup, RT.CR.open, RT.CR.namesStep }
    for _, s in ipairs(RT.CR.specs) do RT.craftingSteps[#RT.craftingSteps + 1] = RT.CR.craft(s) end
    RT.craftingSteps[#RT.craftingSteps + 1] = RT.CR.close
    RT.craftingSteps[#RT.craftingSteps + 1] = RT.finish
end

------------------------------------------------------------------------------
-- The player guide's screenshots (request "sp-rtds"). The other modes hide
-- each menu as soon as it is built and close each dialog at once; here each
-- stays on screen until it is photographed. Summer with the grid on. A
-- Fermentation Vessel is placed on a room tile and loaded from its menu.
-- On a tile with no pump or generator within the Fuel menu's two tiles (so
-- it has no pour entries), the character carries a petrol can holding
-- 0.3 % of the mod's water (a kit finds it, a look does not), an empty
-- petrol can, a sampling kit, a stabilizer and a filter cartridge (so no
-- entry is greyed). Photographed in turn:
--   * the Fuel submenu on the full can (sealed: Open) and on the empty one
--     (Clean empty container);
--   * the kit's result; two game hours later the look's result and What I
--     know about it;
--   * the vessel's Machine submenu and its Status;
--   * a generator's Workshop submenu and, once a project is started and its
--     parts handed over, Project status;
--   * at a workbench, the crafting window searched for "Make", the vessel's
--     recipe picked with its materials carried.
-- Menus come from the game's right-click builders, built as a player's game
-- builds them (RT.DS.asPlayer), with the mod's entry held as under the
-- mouse, which opens its submenu. The crafting window is built and drawn
-- with isDebugEnabled answering false (RT.DS.playerView). The debug console
-- covers the lower left, where the centred dialogs reach: it is hidden and
-- moved off screen for each shot, and the collapsed inventory and loot
-- windows, whose title bars run behind the menus, are hidden too. Each shot
-- logs the rectangles of what it shows, for cropping. No save. Run 211's
-- workshop menu still had the game's debug rows (Tile Report, Room Report,
-- Seed) and its crafting window the recipe's id, each row's tags and a
-- Force Action button.
------------------------------------------------------------------------------
RT.DS = { x = 700, y = 40, settle = 45, hold = 30 }

-- Hides the game's debug console (UIManager.getDebugConsole, a
-- UIDebugConsole) or puts it back where it was.
function RT.DS.console(visible)
    local D = RT.DS
    pcall(function()
        local c = UIManager.getDebugConsole()
        if c == nil then return end
        if not visible then
            if D.consoleAt == nil then D.consoleAt = { c:getX(), c:getY() } end
            c:setVisible(false)
            c:setX(-5000)
        elseif D.consoleAt then
            c:setX(D.consoleAt[1])
            c:setY(D.consoleAt[2])
            c:setVisible(true)
            D.consoleAt = nil
        end
    end)
end

-- Hides the player's inventory and loot windows or shows them again. Not
-- used for the crafting window, whose containers come from those windows'
-- lists (ISInventoryPaneContextMenu.getContainers).
function RT.DS.windows(visible)
    for _, get in ipairs({ getPlayerInventory, getPlayerLoot }) do
        pcall(function()
            local w = get(0)
            if w then w:setVisible(visible) end
        end)
    end
end

function RT.DS.consoleText()
    local s = "none"
    pcall(function()
        local c = UIManager.getDebugConsole()
        if c then s = string.format("visible=%s x=%d", tostring(c:isVisible()), math.floor(c:getX())) end
    end)
    return s
end

-- "x,y wxh" of a UI element.
function RT.DS.rect(ui)
    if ui == nil then return "none" end
    local ok, s = pcall(function()
        return string.format("%d,%d %dx%d", math.floor(ui:getX()), math.floor(ui:getY()), math.floor(ui:getWidth()),
            math.floor(ui:getHeight()))
    end)
    return ok and s or "?"
end

-- A menu's entries as "a | b (greyed) | c".
function RT.DS.names(menu)
    local out = {}
    for _, o in ipairs(menu and menu.options or {}) do
        out[#out + 1] = tostring(o.name) .. ((o.notAvailable or o.isDisabled) and " (greyed)" or "")
    end
    return table.concat(out, " | ")
end

-- Entries ISContextMenu:addDebugOption added (it gives them this icon).
function RT.DS.debugRows(menu)
    local bug, n = getTexture("media/textures/Item_Plumpabug_Left.png"), 0
    for _, o in ipairs(menu and menu.options or {}) do
        if bug ~= nil and o.iconTexture == bug then n = n + 1 end
    end
    return n
end

function RT.DS.index(menu, name)
    for i, o in ipairs(menu and menu.options or {}) do
        if o.name == name then return i end
    end
    return nil
end

-- A text's part before its first argument ("Free water detected (about ").
function RT.DS.lead(key)
    local t = getText(key, "\1")
    local i = string.find(t, "\1", 1, true)
    return i and string.sub(t, 1, i - 1) or t
end

function RT.DS.shot(name)
    local file = "tlg_rtds_" .. name .. ".png"
    local ok, err = pcall(function() getCore():TakeFullScreenshot(file) end)
    R:line("OBS  RTDS.screenshot %s ok=%s%s; console %s", file, tostring(ok), ok and "" or (" " .. tostring(err)),
        RT.DS.consoleText())
    return ok
end

-- Runs a right-click builder as a player's game runs it, without the debug
-- entries: the Debug submenu and the debug Delete entries need
-- isDebugEnabled, and ISContextMenu:addDebugOption (the world menu's Tile
-- Report, Room Report, Seed) drops its entry when the debug option
-- UI.HideDebugContextMenuOptions is on.
function RT.DS.asPlayer(fn)
    local orig, opts = isDebugEnabled, getDebugOptions()
    local hide = opts:getBoolean("UI.HideDebugContextMenuOptions")
    isDebugEnabled = function() return false end
    opts:setBoolean("UI.HideDebugContextMenuOptions", true)
    local ok, err = pcall(fn)
    opts:setBoolean("UI.HideDebugContextMenuOptions", hide)
    isDebugEnabled = orig
    return ok, err
end

-- The crafting window's debug details (the recipe's id under its name, each
-- row's tags, the Force Action button) need isDebugEnabled, read while the
-- window is built and while it is drawn: it answers false from before the
-- window opens until after its shot.
function RT.DS.playerView(on)
    return { name = on and "rtds_player_view_on" or "rtds_player_view_off", timeout = 60, fn = function()
        local D = RT.DS
        if on and not D.realDebug then
            D.realDebug = isDebugEnabled
            isDebugEnabled = function() return false end
        elseif not on and D.realDebug then
            isDebugEnabled, D.realDebug = D.realDebug, nil
        end
        R:line("OBS  RTDS.isDebugEnabled answers %s", tostring(isDebugEnabled()))
        return true
    end }
end

-- A right-click menu with the mod's entry `rootKey` held as under the mouse,
-- photographed and closed. build(x, y) runs the game's builder at (spec.x
-- or RT.DS.x, RT.DS.y); fill(context) adds the mod's entries alone, used if
-- the builder fails or leaves the entry out (logged). want() lists submenu
-- entries that must show; noGreyed: none of them may be greyed.
function RT.DS.menuShot(spec)
    local step = "rtds_menu_" .. spec.name
    return { name = step, timeout = 900, fn = function(ctx, ticks)
        local D = RT.DS
        if RT.skip(step) then return true end
        if ticks == 1 then
            D.console(false)
            D.windows(false)
            local x = spec.x or D.x
            ctx.root = getText(spec.rootKey)
            ctx.how = "the game's right-click builder"
            local ok, err = D.asPlayer(function() spec.build(x, D.y) end)
            ctx.menu = getPlayerContextMenu(0)
            ctx.idx = ok and D.index(ctx.menu, ctx.root) or nil
            if ctx.idx == nil then
                R:line("OBS  RTDS.%s the game's builder ok=%s %s; no \"%s\" in: %s", spec.name, tostring(ok), tostring(err or ""),
                    ctx.root, D.names(ctx.menu))
                ctx.how = "the mod's entries alone"
                ctx.menu = ISContextMenu.get(0, x, D.y)
                spec.fill(ctx.menu)
                ctx.idx = D.index(ctx.menu, ctx.root)
            end
            if ctx.idx == nil then
                R:check("RTDS.menu_" .. spec.name, function() return false, "no entry " .. ctx.root end)
                ctx.menu:hideAndChildren()
                D.console(true)
                D.windows(true)
                return true
            end
            return nil
        end
        -- Every tick: prerender takes the real pointer's row while the menu
        -- slides in, or while the pointer is over it.
        ctx.menu.mouseOver = ctx.idx
        if ticks == D.settle then
            local opt = ctx.menu.options[ctx.idx]
            local sub = opt and opt.subOption and ctx.menu:getSubMenu(opt.subOption)
            local shown = sub ~= nil and sub:getIsVisible() == true
            local subNames = D.names(sub)
            R:line("OBS  RTDS.%s menu (%s) at %s: %s", spec.name, ctx.how, D.rect(ctx.menu), D.names(ctx.menu))
            R:line("OBS  RTDS.%s submenu at %s, visible=%s: %s", spec.name, D.rect(sub), tostring(shown), subNames)
            local shot = D.shot(spec.name)
            local missing = {}
            for _, w in ipairs(spec.want()) do
                if not has(subNames, w) then missing[#missing + 1] = w end
            end
            local greyed = spec.noGreyed and has(subNames, "(greyed)")
            local debugRows = D.debugRows(ctx.menu) + D.debugRows(sub)
            R:check("RTDS.menu_" .. spec.name, function()
                return shot and shown and #missing == 0 and not greyed and debugRows == 0,
                    string.format("%s; submenu visible=%s; missing: %s; greyed entries: %s; debug entries: %d", ctx.how,
                        tostring(shown), #missing > 0 and table.concat(missing, ", ") or "none",
                        tostring(has(subNames, "(greyed)")), debugRows)
            end)
            return nil
        end
        if ticks < D.settle + D.hold then return nil end
        ctx.menu:hideAndChildren()
        D.console(true)
        D.windows(true)
        return true
    end }
end

-- A menu entry chosen as menuClick chooses it (choose() returns the reply);
-- the dialog it opens is photographed once ISModalRichText:update has grown
-- it to its text, then closed. want() lists texts the dialog must hold.
function RT.DS.dialogShot(spec)
    local step = "rtds_dialog_" .. spec.name
    return { name = step, timeout = 900, fn = function(ctx, ticks)
        local D = RT.DS
        if RT.skip(step) then return true end
        if ticks == 1 then
            D.console(false)
            ctx.n = #H.dialogs.texts
            ctx.reply = spec.choose() or {}
            ctx.text = H.dialogs.texts[ctx.n + 1]
            ctx.dlg = #H.dialogs.texts > ctx.n and H.dialogs.open[#H.dialogs.open] or nil
            return nil
        end
        if ticks == D.settle then
            R:line("OBS  RTDS.%s dialog at %s: %s", spec.name, D.rect(ctx.dlg), tostring(ctx.text))
            local shot = D.shot(spec.name)
            local missing = {}
            for _, w in ipairs(spec.want()) do
                if not has(ctx.text, w) then missing[#missing + 1] = w end
            end
            R:check("RTDS.dialog_" .. spec.name, function()
                return shot and ctx.dlg ~= nil and #missing == 0,
                    string.format("reply ok=%s reason=%s; missing: %s", tostring(ctx.reply.ok), tostring(ctx.reply.reason),
                        #missing > 0 and table.concat(missing, ", ") or "none")
            end)
            return nil
        end
        if ticks < D.settle + D.hold then return nil end
        closeDialogs()
        D.console(true)
        return true
    end }
end

-- Nothing the Fuel menu pours into within its two tiles: no pump, no
-- generator.
function RT.DS.nothingNear(s)
    for dx = -2, 2 do
        for dy = -2, 2 do
            local n = sq(s:getX() + dx, s:getY() + dy, s:getZ())
            local objs = n and n:getObjects()
            for i = 0, (objs and objs:size() or 0) - 1 do
                local o = objs:get(i)
                if instanceof(o, "IsoGenerator") or TLG.Integration.Stations.isPump(o) then return false end
            end
        end
    end
    return true
end

RT.DS.setup = { name = "rtds_setup", timeout = 1200, fn = function(ctx, ticks)
    local D = RT.DS
    if not ctx.t0 then
        local p = player()
        p:setGodMod(true)
        p:setInvisible(true)
        pcall(function() p:setUnlimitedCarry(true) end)
        p:setPerkLevelDebug(Perks.Mechanics, 4)
        p:setPerkLevelDebug(Perks.Electricity, 2)
        p:setPerkLevelDebug(Perks.Woodwork, 2)
        p:getKnownRecipes():add("Generator")
        captureDialogs(true)
        -- The character's window (Info, Skills, Health...) stood open at the
        -- upper left in the machine-models screenshots of 2026-11-03.
        local info, open = nil, false
        pcall(function() info = getPlayerInfoPanel(0) end)
        pcall(function() open = info ~= nil and info:getIsVisible() == true end)
        if open then pcall(function() info:setVisible(false) end) end
        R:line("OBS  RTDS.screen %dx%d; the character's window open=%s (closed if so)", getCore():getScreenWidth(),
            getCore():getScreenHeight(), tostring(open))
        local here = p:getSquare()
        D.spots = RT.P.findSpots(here:getX(), here:getY())
        if D.spots == nil then
            RT.abort = "no free room tile with free room neighbours nearby"
            R:line("OBS  RTDS.spots none found")
            return true
        end
        D.vessel = instanceItem("TLG.FermenterVessel")
        D.spots[2]:AddWorldInventoryItem(D.vessel, 0.5, 0.5, 0, false)
        p:teleportTo(D.spots[1]:getX() + 0.5, D.spots[1]:getY() + 0.5, 0)
        ctx.t0 = ticks
        return nil
    end
    if ticks - ctx.t0 < 60 then return nil end
    give("Base.Sugar", 6)
    give("Base.Yeast", 1)
    for _ = 1, 3 do
        local fc = player():getInventory():AddItem("Base.BucketEmpty"):getFluidContainer()
        fc:Empty()
        fc:addFluid(Fluid.Water, 10)
    end
    local r = machineClick("RTDS.load_mash", D.vessel, "ContextMenu_TLG_LoadFerment")
    closeDialogs()
    removeAll("Base.BucketEmpty")
    local power
    pcall(function() power = getWorld():isHydroPowerOn() end)
    R:line("OBS  RTDS.spots character %d,%d; vessel %d,%d; grid power=%s; game hour %.2f", D.spots[1]:getX(),
        D.spots[1]:getY(), D.spots[2]:getX(), D.spots[2]:getY(), tostring(power), getGameTime():getTimeOfDay())
    R:check("RTDS.vessel_loaded", function()
        return r.ok == true, string.format("reason=%s sugar=%s kg water=%s L", tostring(r.reason), tostring(r.sugarKg),
            tostring(r.waterL))
    end)
    return true
end }

RT.DS.fuelSpot = { name = "rtds_fuel_spot", timeout = 600, fn = function(ctx, ticks)
    local D = RT.DS
    if RT.skip("rtds_fuel_spot") then return true end
    if ticks == 1 then
        local s = D.spots[1]
        if not D.nothingNear(s) then
            s = nil
            local x0, y0 = D.spots[1]:getX(), D.spots[1]:getY()
            for r = 1, 40 do
                for dx = -r, r do
                    for dy = -r, r do
                        local n = not s and math.max(math.abs(dx), math.abs(dy)) == r and sq(x0 + dx, y0 + dy, 0) or nil
                        if n and RT.W.free(n) and D.nothingNear(n) then s = n end
                    end
                end
            end
            if s then player():teleportTo(s:getX() + 0.5, s:getY() + 0.5, 0) end
        end
        D.fuelAt = s
        for _, t in ipairs({ "TLG.FuelSampleKit", "TLG.FuelStabilizer", "TLG.FuelFilter" }) do
            removeAll(t)
            give(t, 1)
        end
        D.full = giveCan("Base.PetrolCan", { { Fluid.Petrol, 6 }, { Fluid.Get("TLG_FuelWater"), 0.02 } })
        D.empty = giveCan("Base.PetrolCan", {})
        return nil
    end
    if ticks < 40 then return nil end
    local fc = D.full:getFluidContainer()
    local water = -1
    pcall(function() water = fc:getSpecificFluidAmount(Fluid.Get("TLG_FuelWater")) end)
    R:line("OBS  RTDS.fuel shots at %s (the vessel's room tile: %s); full can %.3f L, water %.4f L; empty can %.3f L",
        D.fuelAt and string.format("%d,%d", D.fuelAt:getX(), D.fuelAt:getY()) or "none", tostring(D.fuelAt == D.spots[1]),
        fc:getAmount(), water, D.empty:getFluidContainer():getAmount())
    R:check("RTDS.nothing_to_pour_into", function()
        return D.fuelAt ~= nil, D.fuelAt and "no pump or generator within two tiles" or "no such tile within 40"
    end)
    return true
end }

function RT.DS.fuelMenu(name, which)
    return RT.DS.menuShot({ name = name, rootKey = "ContextMenu_TLG_Fuel", noGreyed = true,
        build = function(x, y)
            if which == "full" then
                local C, Res = TLG.Integration.Containers, TLG.Authority.Resolver
                local root = getText("ContextMenu_TLG_Fuel")
                for _, spec in ipairs({
                    { "Base.PetrolCan", Fluid.Petrol, true },
                    { "Base.PetrolCan", nil, true },
                    { "Base.WaterBottle", Fluid.Petrol, true },
                    { "Base.BucketEmpty", Fluid.Get("TLG_Ethanol"), true },
                    { "Base.WaterBottle", Fluid.Water, false },
                }) do
                    local item = instanceItem(spec[1])
                    local fc = item:getFluidContainer()
                    fc:Empty()
                    if spec[2] then fc:addFluid(spec[2], 0.5) end
                    RT.DS.fuelAt:AddWorldInventoryItem(item, 0.5, 0.5, 0, false)
                    local label = spec[1] .. "_" .. tostring(spec[2])
                    R:line("OBS floor fuel %s itemFluid=%s worldFluid=%s", label,
                        tostring(item:getFluidContainer()), tostring(item:getWorldItem():getFluidContainer()))
                    for _, stacked in ipairs({ false, true }) do
                        R:check("RTDS.fuel_floor_" .. label .. "_" .. tostring(stacked), function()
                            local entry = stacked and { items = { item, item } } or item
                            local c = ISInventoryPaneContextMenu.createMenu(0, false, { entry }, x, y)
                            return (c ~= nil and RT.DS.index(c, root) ~= nil) == spec[3], "native floor inventory menu"
                        end)
                    end
                    R:check("RTDS.fuel_world_" .. label, function()
                        local c = ISWorldObjectContextMenu.createMenu(0, { item:getWorldItem() }, x, y, false)
                        return (c ~= nil and RT.DS.index(c, root) ~= nil) == spec[3], "native world menu"
                    end)
                    if spec[3] then
                        for _, command in ipairs({ "known", "sample", "treat" }) do
                            R:check("RTDS.fuel_floor_action_" .. label .. "_" .. command, function()
                                local reply = TLG.Authority.Handlers.dispatch(player(), command, {
                                    requestId = "floor-" .. tostring(item:getID()) .. "-" .. command,
                                    target = Res.refForItem(item), method = "visual", op = "unseal",
                                })
                                local cannotSeal = command == "treat" and spec[1] == "Base.BucketEmpty"
                                return (cannotSeal and reply.reason == "not_sealable") or reply.ok == true,
                                    tostring(reply.reason)
                            end)
                        end
                    end
                    TLG.Integration.Machines.liftFromGround(item)
                end
            end
            ISInventoryPaneContextMenu.createMenu(0, true, { RT.DS[which] }, x, y)
        end,
        fill = function(c) TLG.UI.FuelMenu.fill(0, c, { RT.DS[which] }) end,
        want = function()
            local w = {}
            for _, k in ipairs({ "ContextMenu_TLG_ShowKnown", "ContextMenu_TLG_Look", "ContextMenu_TLG_SampleKit",
                "ContextMenu_TLG_Stabilize", "ContextMenu_TLG_Filter", "ContextMenu_TLG_DrainWater", "ContextMenu_TLG_Unseal" }) do
                w[#w + 1] = getText(k)
            end
            if which == "empty" then w[#w + 1] = getText("ContextMenu_TLG_Clean") end
            return w
        end })
end

function RT.DS.fuelChoice(label, key)
    return function()
        local can = RT.DS.full
        return menuClick("RTDS." .. label, function(c) TLG.UI.FuelMenu.fill(0, c, { can }) end, getText("ContextMenu_TLG_Fuel"),
            getText(key))
    end
end

