------------------------------------------------------------------------------
-- Italian (request "sp-it", release gate 10): the client in Italian
-- (options.ini language=IT). tools/run-sp-harness.ps1 -Mode italian writes
-- every Italian string the mod ships to TLG_it_expect.txt, its letters past
-- ASCII as \uXXXX. Each must come back exactly as shipped: getText for the
-- menu, interface, fluid and sandbox texts, the display name of an item
-- made from each item id. Placeholders must be filled, and the Fuel menu
-- and the machine menu, with the dialogs they open, must read Italian with
-- no key left unresolved and no letter garbled (UTF-8 read as Latin-1
-- gives "Ã" or "Â", which Italian never uses).
------------------------------------------------------------------------------
RT.I = {}

function RT.I.decode(s)
    return (string.gsub(s, "\\u(%x%x%x%x)", function(h) return string.char(tonumber(h, 16)) end))
end

function RT.I.garbled(s)
    return s ~= nil and (string.find(s, string.char(195), 1, true) ~= nil or string.find(s, string.char(194), 1, true) ~= nil)
end

-- A dialog or name the game shows: Italian as shipped, nothing unresolved.
function RT.I.clean(s)
    return s ~= nil and not string.find(s, "IGUI_TLG_", 1, true) and not string.find(s, "ContextMenu_TLG_", 1, true)
        and not RT.I.garbled(s)
end

RT.itSetup = { name = "rti_setup", timeout = 600, fn = function(ctx, ticks)
    if not ctx.t0 then
        local p = player()
        p:setGodMod(true)
        p:setInvisible(true)
        captureDialogs(true)
        ctx.t0 = ticks
        return nil
    end
    return ticks - ctx.t0 >= 30 or nil
end }

RT.itText = { name = "rti_text", timeout = 600, fn = function(ctx, ticks)
    local I = RT.I
    local lang = "?"
    pcall(function() lang = tostring(Translator.getLanguage():name()) end)
    R:check("RTI.language_is_italian", function() return lang == "IT", "Translator.getLanguage() = " .. lang end)
    local r = getFileReader("TLG_it_expect.txt", false)
    if r == nil then
        RT.abort = "no TLG_it_expect.txt"
        R:line("OBS  RTI %s", RT.abort)
        return true
    end
    I.want = {}
    local n, same, unresolved, garbled, off, cats, order = 0, 0, 0, 0, {}, {}, {}
    local line = r:readLine()
    while line do
        local cat, key, raw = string.match(line, "^([^|]+)|([^=]+)=(.*)$")
        if cat then
            I.want[key] = I.decode(raw)
            -- The game stores a placeholder %N as %N$s (seen in run 43:
            -- getText without arguments returns that form).
            local want = (string.gsub(I.want[key], "%%(%d)", "%%%1$s"))
            local got
            if cat == "ItemName" then
                local ok, it = pcall(instanceItem, key)
                got = ok and it and it:getDisplayName() or "(no item)"
            elseif cat == "Recipes" then
                -- Recipe names live in their own table, read by the crafting
                -- window through CraftRecipe.getTranslationName (run 193).
                local ok, name = pcall(function() return Translator.getRecipeName(key) end)
                got = ok and name or "(no recipe name)"
            else
                got = getText(key)
            end
            n = n + 1
            if not cats[cat] then
                cats[cat] = { n = 0, same = 0 }
                order[#order + 1] = cat
            end
            cats[cat].n = cats[cat].n + 1
            if got == want then
                same, cats[cat].same = same + 1, cats[cat].same + 1
            else
                if got == key then unresolved = unresolved + 1 end
                if #off < 6 then off[#off + 1] = string.format("%s: game \"%s\", shipped \"%s\"", key, tostring(got), want) end
            end
            if I.garbled(got) then garbled = garbled + 1 end
        end
        line = r:readLine()
    end
    r:close()
    local parts = {}
    for _, c in ipairs(order) do parts[#parts + 1] = string.format("%s %d/%d", c, cats[c].same, cats[c].n) end
    R:line("OBS  RTI.strings %s; samples: %s | %s | %s", table.concat(parts, ", "), tostring(getText("ContextMenu_TLG_Fuel")),
        tostring(getText("IGUI_TLG_ConditionUnknown")), tostring(getText("Sandbox_TLG_ExistingSavePolicy")))
    R:check("RTI.every_string_as_shipped", function()
        return n > 0 and same == n and garbled == 0,
            string.format("%d of %d as shipped, %d unresolved, %d garbled; off: %s", same, n, unresolved, garbled,
                #off > 0 and table.concat(off, " || ") or "none")
    end)
    -- Placeholders filled as the game does it.
    local p1 = getText("IGUI_TLG_Primary", "Etanolo")
    local w1 = (string.gsub(I.want.IGUI_TLG_Primary or "?", "%%1", "Etanolo"))
    local p3 = getText("IGUI_TLG_ConditionEstimate", "Buono", "0.1", "0.3")
    local w3 = I.want.IGUI_TLG_ConditionEstimate or "?"
    w3 = (string.gsub((string.gsub((string.gsub(w3, "%%1", "Buono")), "%%2", "0.1")), "%%3", "0.3"))
    R:check("RTI.placeholders_filled", function()
        return p1 == w1 and p3 == w3, string.format("\"%s\" | \"%s\"", tostring(p1), tostring(p3))
    end)
    return true
end }

-- The Fuel menu on a petrol can and the machine menu on a fermenter, with
-- the dialogs their entries open.
RT.itMenus = { name = "rti_menus", timeout = 600, fn = function(ctx, ticks)
    local I = RT.I
    if RT.skip("rti_menus") then return true end
    local can = giveCan("Base.PetrolCan", { { Fluid.Petrol, 5 } })
    local context = ISContextMenu.get(0, 100, 100)
    TLG.UI.FuelMenu.fill(0, context, { can })
    local root = context:getOptionFromName(I.want.ContextMenu_TLG_Fuel or "?")
    local sub = root and root.subOption and context:getSubMenu(root.subOption)
    local names = {}
    for j = 1, (sub and sub.numOptions or 1) - 1 do
        local o = sub.options[j]
        if o then names[#names + 1] = tostring(o.name) end
    end
    context:setVisible(false)
    local n = #H.dialogs.texts
    menuClick("RTI.look", function(c) TLG.UI.FuelMenu.fill(0, c, { can }) end, I.want.ContextMenu_TLG_Fuel or "?",
        I.want.ContextMenu_TLG_Look or "?")
    local look = H.dialogs.texts[n + 1]
    closeDialogs()
    R:line("OBS  RTI.fuel_menu \"%s\" > %s; Look and smell: %s", tostring(root and root.name), table.concat(names, " / "),
        tostring(look))
    R:check("RTI.fuel_menu_italian", function()
        local all = root ~= nil and #names >= 5
        for _, nm in ipairs(names) do all = all and I.clean(nm) end
        return all and look ~= nil and I.clean(look) and has(look, I.want.IGUI_TLG_InspectionTitle or "?"),
            string.format("%d entries; look dialog %s", #names, tostring(look))
    end)
    local s = player():getSquare()
    local item = instanceItem("TLG.FermenterVessel")
    s:AddWorldInventoryItem(item, 0.5, 0.5, 0, false)
    n = #H.dialogs.texts
    local r = menuClick("RTI.status", function(c) TLG.UI.MachineMenu.fill(0, c, { item }) end,
        I.want.ContextMenu_TLG_Machine or "?", I.want.ContextMenu_TLG_MachineStatus or "?")
    local status = H.dialogs.texts[n + 1]
    closeDialogs()
    R:line("OBS  RTI.machine_menu Status: %s", tostring(status))
    R:check("RTI.machine_menu_italian", function()
        return r.ok == true and status ~= nil and I.clean(status) and has(status, I.want.IGUI_TLG_MachineState_Ready or "?"),
            tostring(status)
    end)
    return true
end }

RT.italianSteps = { RT.waitWorld, RT.itSetup, RT.itText, RT.itMenus, RT.finish }

------------------------------------------------------------------------------
-- The biodiesel chain (request "sp-rtbd", D-036). Summer with the grid on:
-- a wood retort, an ash barrel, a lye leacher, a biodiesel reactor and a
-- wash tank on room tiles around the character (RT.P.findSpots), every load
-- through the machine menu. First what the game loaded is read back: the
-- five model scripts, the items' models, icons, names and category, the
-- five craft recipes as the crafting window lists them (none is crafted)
-- and the chain's texts. Before that a second set is photographed outdoors
-- on a row, the fermentation vessel beside it for size (RT.BD.row).
-- Then the chain: 11 logs (99 kg) into the retort, its firebox fed 3 logs,
-- and 11 logs into the ash barrel; while they work, the loads and the
-- collection that need a finished machine are refused. The leacher takes
-- the barrel's ash and 2 L of water per kg; the reactor takes cooking oil
-- from 20 bottles carried, as many as the leacher's lye allows, with the
-- retort's methanol and that lye; the wash tank takes the reactor's crude
-- and wash water. The washed biodiesel is collected into jerry cans and
-- judged with Consumers.evaluate against the diesel profiles. Every hour,
-- kilogram of firebox wood and output is checked against the definitions
-- (Content/Biodiesel: the recipes' stages and the converters, at Cooking 0
-- and the machine's condition before the batch).
------------------------------------------------------------------------------
RT.BD = { names = { "WoodRetort", "AshBarrel", "LyeLeacher", "BiodieselReactor", "BiodieselWashTank" },
    ids = { "wood_retort", "ash_pit", "lye_leacher", "biodiesel_reactor", "biodiesel_wash_tank" },
    recipes = { "methanol_wood_distill", "ash_burn", "lye_leach", "biodiesel_react", "biodiesel_wash" },
    wood = { "Base.Log", "Base.Firewood", "Base.Plank", "Base.Twigs" },
    diesels = { "engine_ci_stock", "engine_ci_bio", "generator_ci_stock", "generator_ci_bio" }, tol = 1e-6, timeTol = 1e-4, phases = {} }

function RT.BD.rec(i) return RT.BD.items[i]:getModData().tlgProc or {} end
function RT.BD.kind(i) return TLG.Registry.need("machine", RT.BD.ids[i]).kind end
function RT.BD.near(a, b, tol) return type(a) == "number" and type(b) == "number" and math.abs(a - b) <= (tol or RT.BD.tol) end

-- Equal amounts under the same names.
function RT.BD.same(a, b, tol)
    a, b = a or {}, b or {}
    for k, v in pairs(a) do if not RT.BD.near(v, b[k] or 0, tol) then return false end end
    for k, v in pairs(b) do if not RT.BD.near(v, a[k] or 0, tol) then return false end end
    return true
end

-- What machine i makes of `inputs`, in how many hours and for how much
-- firebox wood, from the definitions (Process.stageHours, stageRate and
-- completeBatch).
function RT.BD.plan(i, inputs)
    local rec, m = TLG.Registry.need("recipe", RT.BD.recipes[i]), TLG.Registry.need("machine", RT.BD.ids[i])
    local total, h, burn = 0, 0, 0
    for _, v in pairs(inputs) do total = total + v end
    for _, st in ipairs(rec.stages) do
        local sh = st.hours
        if st.hoursFrom then sh = math.max(st.minHours or 0.5, total / (m[st.hoursFrom] or 1)) end
        h = h + sh
        if st.heatKW and st.heatKW > 0 then burn = burn + sh * st.heatKW / (m.firebox.kwhPerKg * m.firebox.efficiency) end
    end
    local eff = 1 - 0.3 * (1 - (RT.BD.rec(i).cond or 1))
    local res = TLG.Domain.Process.converters[rec.converter](TLG.Tables.copy(inputs), rec.params, m, eff, 0)
    return { hours = h, burn = burn, outputs = res.outputs, byproducts = res.byproducts, props = res.props }
end

-- A machine menu entry clicked; the reply and the dialog the player reads.
function RT.BD.click(i, key, label)
    local before = #H.dialogs.texts
    local r = machineClick("RTBD." .. label, RT.BD.items[i], key)
    local text = H.dialogs.texts[before + 1]
    closeDialogs()
    return r, text
end

-- All wood taken away, `logs` logs given, and the firebox fed from the menu.
function RT.BD.feed(i, logs)
    for _, t in ipairs(RT.BD.wood) do removeAll(t) end
    give("Base.Log", logs)
    local r = RT.BD.click(i, "ContextMenu_TLG_AddFirewood", "feed_" .. RT.BD.names[i])
    R:check("RTBD.firebox_fed_" .. RT.BD.names[i], function()
        return r.ok == true and RT.BD.near(r.addedKg, 9 * logs) and countType("Base.Log") == 0,
            string.format("added kg %s, logs left %d, reason=%s", tostring(r.addedKg), countType("Base.Log"), tostring(r.reason))
    end)
    return r
end

-- A load refused: the reason, and its text as the player reads it.
function RT.BD.refused(i, reason)
    local r, text = RT.BD.click(i, "ContextMenu_TLG_Load_" .. RT.BD.kind(i), "refused_" .. RT.BD.names[i])
    R:check("RTBD.refused_" .. reason, function()
        return r.ok == false and r.reason == reason and text == getText("IGUI_TLG_MachineFail_" .. reason)
            and not has(text, "IGUI_TLG"), string.format("reason=%s dialog=%s", tostring(r.reason), tostring(text))
    end)
end

-- Waits on the game clock until every machine in ctx.waiting is finished
-- (or one faults, or `maxHours` pass); pauses are logged as they appear.
function RT.BD.wait(ctx, maxHours)
    RT.speed(RT.waitSpeed)
    if hours() < (ctx.next or 0) then return false end
    ctx.next = hours() + 0.25
    ctx.pauses = ctx.pauses or {}
    local done, stop = true, hours() - ctx.waitFrom >= maxHours
    for _, i in ipairs(ctx.waiting) do
        local s = RT.statusOf(RT.BD.items[i])
        local key = RT.BD.names[i] .. ":" .. tostring(s.pause)
        if s.pause and not ctx.pauses[key] then
            ctx.pauses[key] = true
            R:line("OBS  RTBD.pause %s state=%s pause=%s stage=%s firebox=%s, %.2f h after loading", RT.BD.names[i],
                tostring(s.state), tostring(s.pause), tostring(s.stage), tostring(s.firebox), hours() - ctx.waitFrom)
        end
        if s.state == "Faulted" or s.ok == false then stop = true end
        done = done and s.state == "OutputReady"
    end
    if not (done or stop) then return false end
    RT.speed(1)
    return true
end

-- A finished batch against the plan `e`, loaded at `t0` with `fed` kg in
-- the firebox.
function RT.BD.finished(i, e, t0, fed)
    local BD, rec = RT.BD, RT.BD.rec(i)
    local name = BD.names[i]
    R:check("RTBD.hours_" .. name, function()
        return rec.state == "OutputReady" and BD.near(rec.completedAt, t0 + e.hours, BD.timeTol) and BD.near(rec.pausedFor or 0, 0),
            string.format("state=%s pause=%s; done %.4f h after loading, expected %.4f; paused %.4f h", tostring(rec.state),
                tostring(rec.pause), (rec.completedAt or -1) - t0, e.hours, rec.pausedFor or -1)
    end)
    R:check("RTBD.outputs_" .. name, function()
        return BD.same(rec.outputs, e.outputs), string.format("%s; expected %s; byproducts %s", brief(rec.outputs), brief(e.outputs),
            brief(rec.byproducts))
    end)
    if fed then
        R:check("RTBD.firebox_" .. name, function()
            return BD.near(rec.firebox, fed - e.burn, BD.timeTol), string.format("left %.4f kg, expected %.4f (%.4f kg burned)",
                rec.firebox or -1, fed - e.burn, e.burn)
        end)
    end
    local _, text = BD.click(i, "ContextMenu_TLG_MachineStatus", "status_" .. name)
    R:check("RTBD.status_" .. name, function()
        return has(text, getText("IGUI_TLG_MachineState_OutputReady_" .. BD.kind(i))) and not has(text, "IGUI_TLG"), tostring(text)
    end)
    return rec.state == "OutputReady"
end

RT.BD.setup = { name = "rtbd_sites", timeout = 3000, fn = function(ctx, ticks)
    local BD = RT.BD
    if not ctx.t0 and RT.skip("rtbd_sites") then return true end
    if not ctx.t0 then
        local here = player():getSquare()
        local spots = RT.P.findSpots(here:getX(), here:getY())
        if spots == nil then
            RT.abort = "no free room tile with free room neighbours nearby"
            R:line("OBS  RTBD.spots none found")
            return true
        end
        BD.spots, BD.items = {}, {}
        for i, s in ipairs(spots) do BD.spots[i] = { x = s:getX(), y = s:getY() } end
        for i, name in ipairs(BD.names) do
            local it = instanceItem("TLG." .. name)
            if it == nil then
                RT.abort = "the game has no item TLG." .. name
                R:check("RTBD.item_exists_" .. name, function() return false, "instanceItem gave nil" end)
                return true
            end
            spots[i + 1]:AddWorldInventoryItem(it, 0.5, 0.5, 0, false)
            BD.items[i] = it
        end
        player():setPosition(BD.spots[1].x + 0.5, BD.spots[1].y + 0.5, 0)
        player():setPerkLevelDebug(Perks.Cooking, 0)
        local power
        pcall(function() power = getWorld():isHydroPowerOn() end)
        local parts = {}
        for i, name in ipairs(BD.names) do parts[i] = string.format("%s %d,%d", name, BD.spots[i + 1].x, BD.spots[i + 1].y) end
        R:line("OBS  RTBD.spots character %d,%d; %s; grid power=%s", BD.spots[1].x, BD.spots[1].y, table.concat(parts, " "),
            tostring(power))
        R:check("RTBD.grid_is_on", function() return power == true, "isHydroPowerOn=" .. tostring(power) end)
        ctx.t0 = ticks
        return nil
    end
    if ticks - ctx.t0 < 60 then return nil end
    local seen, placed = {}, {}
    for i = 1, 6 do seen[i] = tostring(TLG.Integration.Machines.siteOf(sq(BD.spots[i].x, BD.spots[i].y, 0)).room) end
    for i = 1, 5 do placed[i] = tostring(TLG.Integration.Machines.isPlaced(BD.items[i])) end
    R:check("RTBD.all_placed_in_a_room", function()
        return table.concat(seen, ",") == "true,true,true,true,true,true" and table.concat(placed, ",") == "true,true,true,true,true",
            "in a room: " .. table.concat(seen, ",") .. "; placed: " .. table.concat(placed, ",")
    end)
    return true
end }

-- What the game loaded of the five machines, before anything is run.
RT.BD.static = { name = "rtbd_static", timeout = 300, fn = function()
    local BD = RT.BD
    if RT.skip("rtbd_static") then return true end
    local sm = getScriptManager()
    local models, items, icons, names, cats = {}, {}, {}, {}, {}
    local okModels, okItems, okIcons, okNames, okCats = true, true, true, true, true
    for i, name in ipairs(BD.names) do
        local ms = sm:getModelScript("TLG." .. name)
        local mesh, tex = ms and ms:getMeshName(), ms and ms:getTextureName()
        okModels = okModels and mesh == "TLG/" .. name and tex == "TLG/" .. name
        models[i] = string.format("TLG.%s mesh=%s texture=%s", name, tostring(mesh), tostring(tex))
        local si = sm:getItem("TLG." .. name)
        local world = si and si:getWorldStaticModel()
        okItems = okItems and world == "TLG." .. name
        local weight = "?"
        pcall(function() weight = BD.items[i]:getActualWeight() end)
        items[i] = string.format("TLG.%s WorldStaticModel=%s weight=%s", name, tostring(world), tostring(weight))
        local it = BD.items[i]
        local t = it:getTex()
        local texName = tostring(t and t:getName())
        okIcons = okIcons and has(texName, "Item_TLG_" .. name) and not has(texName, "Question_On")
        icons[i] = string.format("%s icon=%s", name, texName)
        local shown = tostring(it:getDisplayName())
        okNames = okNames and shown ~= "" and not has(shown, "ItemName") and not has(shown, "TLG.")
        names[i] = string.format("%s=\"%s\"", name, shown)
        local c = tostring(si and si:getDisplayCategory())
        local ct = getText("IGUI_ItemCat_" .. c)
        okCats = okCats and ct ~= "IGUI_ItemCat_" .. c
        cats[i] = string.format("%s=%s (\"%s\")", name, c, tostring(ct))
    end
    R:check("RTBD.model_scripts_loaded", function() return okModels, table.concat(models, "; ") end)
    R:check("RTBD.items_wired", function() return okItems, table.concat(items, "; ") end)
    R:check("RTBD.icons_found", function() return okIcons, table.concat(icons, "; ") end)
    R:check("RTBD.items_named", function() return okNames, table.concat(names, "; ") end)
    R:check("RTBD.categories_named", function() return okCats, table.concat(cats, "; ") end)
    -- The crafting window's own query (ISHandcraftWindow.lua:53). Listed is
    -- not crafted: no recipe is made in this run.
    local listed, got, all = windowRecipes(), {}, true
    for i, name in ipairs(BD.names) do
        local r = listed["TLG_Make" .. name]
        local shown = "nil"
        pcall(function() shown = tostring(r:getTranslationName()) end)
        all = all and r ~= nil and not has(shown, "TLG_Make")
        got[i] = string.format("TLG_Make%s=%s", name, r and ("\"" .. shown .. "\"") or "not listed")
    end
    R:check("RTBD.recipes_listed", function() return all, table.concat(got, "; ") end)
    -- Every text the chain shows must have a translation loaded.
    local keys, raw = { "ContextMenu_TLG_CollectBiodiesel", "ContextMenu_TLG_AddFirewood" }, {}
    for i = 1, 5 do
        keys[#keys + 1] = "ContextMenu_TLG_Load_" .. BD.kind(i)
        keys[#keys + 1] = "IGUI_TLG_MachineState_OutputReady_" .. BD.kind(i)
        for _, st in ipairs(TLG.Registry.need("recipe", BD.recipes[i]).stages) do keys[#keys + 1] = "IGUI_TLG_Stage_" .. st.id end
    end
    for _, reason in ipairs({ "no_ready_retort", "no_ready_leacher", "no_ready_ash", "no_ready_reactor", "not_enough_methanol",
        "not_enough_lye", "not_enough_plant_oil", "not_enough_firewood", "not_enough_wood_ash", "not_enough_water",
        "use_next_machine" }) do
        keys[#keys + 1] = "IGUI_TLG_MachineFail_" .. reason
    end
    for _, k in ipairs(keys) do if getText(k) == k then raw[#raw + 1] = k end end
    R:check("RTBD.texts_loaded", function() return #raw == 0, string.format("%d keys, without a text: %s", #keys, table.concat(raw, ",")) end)
    return true
end }

-- Firebox wood, then the retort's and the ash barrel's loads.
function RT.BD.phases.wood(ctx)
    local BD = RT.BD
    ctx.fed = { BD.feed(1, 3).addedKg or 0 }
    local logs = { 11, 11 }
    for i = 1, 2 do
        for _, t in ipairs(BD.wood) do removeAll(t) end
        give("Base.Log", logs[i])
        ctx.plan = ctx.plan or {}
        ctx.plan[i] = BD.plan(i, { firewood = 9 * logs[i] })
        local r = BD.click(i, "ContextMenu_TLG_Load_" .. BD.kind(i), "load_" .. BD.names[i])
        ctx.t = ctx.t or {}
        ctx.t[i] = hours()
        R:check("RTBD.loaded_" .. BD.names[i], function()
            return r.ok == true and BD.near(r.woodKg, 9 * logs[i]) and r.state == "Processing" and countType("Base.Log") == 0,
                string.format("wood %s kg, state=%s reason=%s, logs left %d", tostring(r.woodKg), tostring(r.state),
                    tostring(r.reason), countType("Base.Log"))
        end)
        if r.ok ~= true then
            RT.abort = "the " .. BD.names[i] .. " did not load"
            return true
        end
    end
    -- The ash barrel has no firebox: its menu must not offer one.
    local none = BD.click(2, "ContextMenu_TLG_AddFirewood", "ash_barrel_firebox")
    R:check("RTBD.ash_barrel_has_no_firebox_entry", function() return none.reason == "no_menu_entry", tostring(none.reason) end)
    -- Nothing is finished yet: the three loads that need a finished machine
    -- beside them are refused, and so is the retort's collection into a can.
    BD.refused(3, "no_ready_ash")
    BD.refused(4, "no_ready_retort")
    BD.refused(5, "no_ready_reactor")
    local can = giveCan("Base.JerryCan")
    local c = ask("RTBD.retort_collect", "machine.collect", { target = TLG.Integration.Machines.refFor(BD.items[1]),
        destination = { kind = "item", id = can:getID() } })
    R:check("RTBD.retort_gives_nothing_to_a_can", function()
        return c.ok == false and c.reason == "use_next_machine" and can:getFluidContainer():isEmpty(), tostring(c.reason)
    end)
    local _, text = BD.click(1, "ContextMenu_TLG_MachineStatus", "status_retort_heating")
    R:check("RTBD.retort_status_while_heating", function()
        return has(text, getText("IGUI_TLG_Stage", getText("IGUI_TLG_Stage_heat_up"))) and not has(text, "IGUI_TLG"), tostring(text)
    end)
    ctx.waiting, ctx.waitFrom, ctx.next, ctx.phase = { 1, 2 }, hours(), 0, "burning"
end

function RT.BD.phases.burning(ctx)
    local BD = RT.BD
    if not BD.wait(ctx, 40) then return end
    local ok1 = BD.finished(1, ctx.plan[1], ctx.t[1], ctx.fed[1])
    local ok2 = BD.finished(2, ctx.plan[2], ctx.t[2], nil)
    if not (ok1 and ok2) then
        RT.abort = "the retort or the ash barrel did not finish"
        return true
    end
    ctx.phase = "leach"
end

function RT.BD.phases.leach(ctx)
    local BD = RT.BD
    ctx.fed[3] = BD.feed(3, 1).addedKg or 0
    local ash = ctx.plan[2].outputs.wood_ash
    local perKg = TLG.Registry.need("recipe", "lye_leach").params.waterPerKgAsh
    ctx.plan[3] = BD.plan(3, { wood_ash = ash, water = ash * perKg })
    local water = waterCarried()
    local r = BD.click(3, "ContextMenu_TLG_Load_leacher", "load_LyeLeacher")
    ctx.t[3] = hours()
    R:check("RTBD.loaded_LyeLeacher", function()
        return r.ok == true and BD.near(r.ashKg, ash) and BD.near(r.waterL, ash * perKg) and BD.near(water - waterCarried(), ash * perKg, 1e-3)
            and BD.rec(2).state == "Ready", string.format("ash %s kg (%.4f), water %s L (%.4f), carried water %.3f -> %.3f; barrel %s, reason=%s",
            tostring(r.ashKg), ash, tostring(r.waterL), ash * perKg, water, waterCarried(), tostring(BD.rec(2).state), tostring(r.reason))
    end)
    if r.ok ~= true then
        RT.abort = "the lye leacher did not load"
        return true
    end
    ctx.waiting, ctx.waitFrom, ctx.next, ctx.phase = { 3 }, hours(), 0, "leaching"
end

function RT.BD.phases.leaching(ctx)
    local BD = RT.BD
    if not BD.wait(ctx, 60) then return end
    if not BD.finished(3, ctx.plan[3], ctx.t[3], ctx.fed[3]) then
        RT.abort = "the lye leacher did not finish"
        return true
    end
    ctx.phase = "react"
end

function RT.BD.phases.react(ctx)
    local BD = RT.BD
    local p = TLG.Registry.need("recipe", "biodiesel_react").params
    local bottle = TLG.Feedstocks.items["Base.OilVegetable"].oil
    removeAll("Base.OilVegetable")
    give("Base.OilVegetable", 20)
    -- Feed.amount reads a food item's share left from these two (NOT RUN
    -- until this run): a new bottle must give its whole 0.9 L.
    local one = player():getInventory():getFirstTypeRecurse("Base.OilVegetable")
    local base, left, amount = "?", "?", -1
    pcall(function() base = one:getBaseHunger() end)
    pcall(function() left = one:getHungChange() end)
    pcall(function() amount = TLG.Feedstocks.amount(one, "oil") end)
    R:check("RTBD.new_oil_bottle_gives_its_litres", function()
        return BD.near(amount, bottle), string.format("Feed.amount=%s (definition %s); getBaseHunger=%s getHungChange=%s",
            tostring(amount), tostring(bottle), tostring(base), tostring(left))
    end)
    ctx.fed[4] = BD.feed(4, 1).addedKg or 0
    local methanol, lye = ctx.plan[1].outputs.methanol, ctx.plan[3].outputs.lye
    local bottles = math.min(20, math.floor(math.min(methanol / p.methanolPerOil, lye / p.lyePerOil) / bottle + 1e-9))
    local oil = bottles * bottle
    ctx.plan[4] = BD.plan(4, { plant_oil = oil, methanol = oil * p.methanolPerOil, lye = oil * p.lyePerOil })
    local r = BD.click(4, "ContextMenu_TLG_Load_reactor", "load_BiodieselReactor")
    ctx.t[4] = hours()
    local retort, leacher = BD.rec(1), BD.rec(3)
    R:check("RTBD.loaded_BiodieselReactor", function()
        return r.ok == true and BD.near(r.oilL, oil) and BD.near(r.methanolL, oil * p.methanolPerOil) and BD.near(r.lyeKg, oil * p.lyePerOil)
            and countType("Base.OilVegetable") == 20 - bottles, string.format(
            "oil %s L (%d bottles, %.4f), methanol %s L, lye %s kg, bottles left %d, reason=%s; retort held %.4f L, leacher %.4f kg",
            tostring(r.oilL), bottles, oil, tostring(r.methanolL), tostring(r.lyeKg), countType("Base.OilVegetable"), tostring(r.reason),
            methanol, lye)
    end)
    R:check("RTBD.retort_and_leacher_keep_the_rest", function()
        return retort.state == "OutputReady" and BD.near((retort.outputs or {}).methanol, methanol - oil * p.methanolPerOil)
            and leacher.state == "OutputReady" and BD.near((leacher.outputs or {}).lye, lye - oil * p.lyePerOil) and r.charcoal == 0,
            string.format("retort %s %s; leacher %s %s; charcoal given %s", tostring(retort.state), brief(retort.outputs),
                tostring(leacher.state), brief(leacher.outputs), tostring(r.charcoal))
    end)
    if r.ok ~= true then
        RT.abort = "the reactor did not load"
        return true
    end
    ctx.waiting, ctx.waitFrom, ctx.next, ctx.phase = { 4 }, hours(), 0, "reacting"
end

function RT.BD.phases.reacting(ctx)
    local BD = RT.BD
    if not BD.wait(ctx, 30) then return end
    if not BD.finished(4, ctx.plan[4], ctx.t[4], ctx.fed[4]) then
        RT.abort = "the reactor did not finish"
        return true
    end
    R:line("OBS  RTBD.crude quality %s; glycerin and other byproducts %s", brief((BD.rec(4).outProps or {}).quality), brief(BD.rec(4).byproducts))
    ctx.phase = "wash"
end

function RT.BD.phases.wash(ctx)
    local BD = RT.BD
    ctx.fed[5] = BD.feed(5, 1).addedKg or 0
    local crude = TLG.Tables.copy(ctx.plan[4].outputs)
    local crudeL = 0
    for _, v in pairs(crude) do crudeL = crudeL + v end
    local wash = (crude.biodiesel or 0) * TLG.Registry.need("recipe", "biodiesel_wash").params.washWaterPerL
    crude.water = (crude.water or 0) + wash
    ctx.plan[5] = BD.plan(5, crude)
    local water = waterCarried()
    local r = BD.click(5, "ContextMenu_TLG_Load_settler", "load_BiodieselWashTank")
    ctx.t[5] = hours()
    R:check("RTBD.loaded_BiodieselWashTank", function()
        return r.ok == true and BD.near(r.crudeL, crudeL) and BD.near(r.washWaterL, wash) and BD.near(water - waterCarried(), wash, 1e-3)
            and BD.rec(4).state == "Ready", string.format(
            "crude %s L (%.4f), wash water %s L (%.4f), carried water %.3f -> %.3f; reactor %s; thrown away %s; reason=%s",
            tostring(r.crudeL), crudeL, tostring(r.washWaterL), wash, water, waterCarried(), tostring(BD.rec(4).state), brief(r.discarded),
            tostring(r.reason))
    end)
    if r.ok ~= true then
        RT.abort = "the wash tank did not load"
        return true
    end
    ctx.waiting, ctx.waitFrom, ctx.next, ctx.phase = { 5 }, hours(), 0, "washing"
end

function RT.BD.phases.washing(ctx)
    local BD = RT.BD
    if not BD.wait(ctx, 60) then return end
    if not BD.finished(5, ctx.plan[5], ctx.t[5], ctx.fed[5]) then
        RT.abort = "the wash tank did not finish"
        return true
    end
    R:line("OBS  RTBD.washed quality %s; wash effluent %s", brief((BD.rec(5).outProps or {}).quality), brief(BD.rec(5).byproducts))
    ctx.phase = "collect"
end

-- Carried containers holding biodiesel, by item id.
function RT.BD.cans()
    local out = {}
    local list = player():getInventory():getAllEvalRecurse(function(it)
        local fc = it:getFluidContainer()
        return fc ~= nil and not fc:isEmpty()
    end)
    for i = 0, list:size() - 1 do
        local it = list:get(i)
        local comp = TLG.Integration.Native.readComposition(it:getFluidContainer())
        if (comp.biodiesel or 0) > 0 then out[#out + 1] = it end
    end
    return out
end

-- The wash tank's biodiesel into jerry cans, one menu click a can, until
-- the tank is empty.
function RT.BD.phases.collect(ctx)
    local BD = RT.BD
    local want = ctx.plan[5].outputs
    local clicks = 0
    for n = 1, 5 do
        if n > 1 then giveCan("Base.JerryCan") end
        local r, text = BD.click(5, "ContextMenu_TLG_CollectBiodiesel", "collect_" .. n)
        clicks = n
        R:line("OBS  RTBD.collect_%d ok=%s reason=%s detail=%s collected=%s; tank %s keeps %s; dialog=%s", n, tostring(r.ok),
            tostring(r.reason), brief(r.detail), brief(r.collected), tostring(BD.rec(5).state), brief(BD.rec(5).outputs), tostring(text))
        if r.ok ~= true or BD.rec(5).state ~= "OutputReady" then break end
    end
    local sum, parts, matches = {}, {}, true
    for _, can in ipairs(BD.cans()) do
        local v, status = tlgView("item", can)
        local fc = can:getFluidContainer()
        local comp, foreign = TLG.Integration.Native.readComposition(fc)
        for k, q in pairs(v and v.q or {}) do sum[k] = (sum[k] or 0) + q end
        matches = matches and v ~= nil and BD.near(fc:getAmount(), TLG.Domain.Supply.total(v), 1e-3)
        parts[#parts + 1] = string.format("%s holds %.4f L of %.1f, fluids %s foreign=%s, record %s", can:getFullType(), fc:getAmount(),
            fc:getCapacity(), brief(comp), tostring(foreign), viewText(v, status))
        ctx.can = ctx.can or can
    end
    R:check("RTBD.biodiesel_in_cans", function()
        return BD.rec(5).state == "Ready" and BD.same(sum, want, 1e-3), string.format("%d clicks, %d cans hold %s; expected %s; tank %s",
            clicks, #parts, brief(sum), brief(want), tostring(BD.rec(5).state))
    end)
    R:check("RTBD.cans_fluids_match_their_records", function() return #parts > 0 and matches, table.concat(parts, " | ") end)
    if ctx.can then
        local v = tlgView("item", ctx.can)
        local verdicts, lines = {}, {}
        for _, id in ipairs(BD.diesels) do
            local e = v and TLG.Domain.Consumers.evaluate(id, v) or { compatible = false, reasons = { "no_record" } }
            verdicts[id] = e
            lines[#lines + 1] = string.format("%s %s (%s)", id, e.compatible and "fit" or "unfit", table.concat(e.reasons or {}, ","))
        end
        R:line("OBS  RTBD.verdicts %s", table.concat(lines, "; "))
        R:check("RTBD.washed_biodiesel_fits_the_biodiesel_engine", function()
            return verdicts.engine_ci_bio.compatible == true, table.concat(lines, "; ")
        end)
    end
    return true
end

RT.BD.run = { name = "rtbd_run", timeout = 120000, fn = function(ctx, ticks)
    if not ctx.phase and RT.skip("rtbd_run") then return true end
    if ticks % 30 == 0 then RT.keepFit() end
    return RT.BD.phases[ctx.phase or "wood"](ctx, ticks) == true
end }

-- A second set of the five machines for the photographs, outdoors in
-- daylight on a row across the screen (RT.MI.spot), two tiles apart, the
-- fermentation vessel first for size. Launch 230 photographed the working
-- set in its room, which was dark: nothing could be seen.
RT.BD.row = { name = "rtbd_row", timeout = 1200, fn = function(ctx, ticks)
    local BD, M = RT.BD, RT.MI
    if RT.skip("rtbd_row") then return true end
    if ticks < 30 then return nil end
    if not ctx.placed then
        local px, py = math.floor(player():getX()), math.floor(player():getY())
        for r = 0, 15 do
            for dx = -r, r do
                for dy = -r, r do
                    if not BD.cx and math.max(math.abs(dx), math.abs(dy)) == r then
                        local cx, cy, ok = px + dx, py + dy, true
                        for k = -5, 5 do
                            local x, y = M.spot(cx, cy, k)
                            local bx, by = M.behind(cx, cy, k)
                            ok = ok and M.clear(x, y) and M.clear(bx, by)
                        end
                        if ok then BD.cx, BD.cy = cx, cy end
                    end
                end
            end
        end
        R:check("RTBD.clear_ground_for_the_row", function()
            return BD.cx ~= nil, string.format("from %d,%d: %s,%s", px, py, tostring(BD.cx), tostring(BD.cy))
        end)
        if BD.cx == nil then return true end
        local at = {}
        for i, t in ipairs({ "TLG.FermenterVessel", "TLG.WoodRetort", "TLG.AshBarrel", "TLG.LyeLeacher", "TLG.BiodieselReactor",
            "TLG.BiodieselWashTank" }) do
            local x, y = M.spot(BD.cx, BD.cy, 2 * i - 7)
            local it = instanceItem(t)
            if it then sq(x, y, 0):AddWorldInventoryItem(it, 0.5, 0.5, 0, false) end
            at[i] = string.format("%s %d,%d", t, x, y)
        end
        R:line("OBS  RTBD.row %s", table.concat(at, "; "))
        ctx.placed = ticks
        return nil
    end
    return ticks - ctx.placed >= 30 or nil
end }

-- The character on the row behind the photographed one, at square k.
function RT.BD.stand(name, k)
    return { name = name, timeout = 600, fn = function(ctx, ticks)
        if RT.BD.cx == nil then return true end
        if ticks == 1 then
            local x, y = RT.MI.behind(RT.BD.cx, RT.BD.cy, k)
            player():teleportTo(x + 0.5, y + 0.5, 0)
        end
        return ticks >= 90 or nil
    end }
end

-- The models alone (request "sp-rtbdm"): the row and nothing else, the
-- character standing on it between two machines for each photograph, so
-- each machine is seen whole beside her (launch 231 stood her behind the
-- row and three machines fell outside the frame).
RT.BD.photoSetup = { name = "rtbdm_setup", timeout = 600, fn = function(ctx, ticks)
    if ticks == 1 then
        player():setGodMod(true)
        player():setInvisible(true)
    end
    return ticks >= 60 or nil
end }

function RT.BD.on(name, k)
    return { name = name, timeout = 600, fn = function(ctx, ticks)
        if RT.BD.cx == nil then return true end
        if ticks == 1 then
            local x, y = RT.MI.spot(RT.BD.cx, RT.BD.cy, k)
            player():teleportTo(x + 0.5, y + 0.5, 0)
        end
        return ticks >= 90 or nil
    end }
end

RT.biodieselModelSteps = { RT.waitWorld, RT.BD.photoSetup, RT.MM.clearSky, RT.BD.row,
    RT.BD.on("rtbdm_on_0", 0), RT.MI.zoomTo("rtbdm_zoom_row", 1.0), RT.MI.shot("rtbdm_row", true),
    RT.MI.zoomTo("rtbdm_zoom", 0.5), RT.MI.shot("rtbdm_barrel_leacher", true),
    RT.BD.on("rtbdm_on_m4", -4), RT.MI.shot("rtbdm_vessel_retort", true),
    RT.BD.on("rtbdm_on_m2", -2), RT.MI.shot("rtbdm_retort_barrel", true),
    RT.BD.on("rtbdm_on_2", 2), RT.MI.shot("rtbdm_leacher_reactor", true),
    RT.BD.on("rtbdm_on_4", 4), RT.MI.shot("rtbdm_reactor_tank", true), RT.finish }

------------------------------------------------------------------------------
-- The diesel generator (request "sp-rtdg", D-036): a probe. Whether an
-- item of the mod tagged base:generator becomes a working IsoGenerator
-- that keeps its type, so the mod can give it the diesel profile. Two are
-- put down beside a vanilla one (IsoGenerator.new, as the game converts a
-- dropped generator). The first takes 5 L of biodiesel through the mod's
-- pour, must start, and runs two game hours; the second takes petrol
-- through vanilla's Add fuel action and must be refused by the start
-- gate; the vanilla one keeps the petrol profile.
------------------------------------------------------------------------------
RT.DG = { gens = {} }

RT.DG.place = { name = "rtdg_place", timeout = 1200, fn = function(ctx, ticks)
    local DG, G = RT.DG, TLG.Integration.Generators
    if ticks < 60 then return nil end
    if not ctx.placed then
        local item = instanceItem("TLG.DieselGenerator")
        R:check("RTDG.item_exists", function()
            return item ~= nil, item and string.format("\"%s\" weight=%s", tostring(item:getDisplayName()), tostring(item:getActualWeight())) or "nil"
        end)
        if item == nil then
            RT.abort = "the game has no item TLG.DieselGenerator"
            return true
        end
        local px, py = math.floor(player():getX()), math.floor(player():getY())
        local spots = {}
        for r = 2, 12 do
            for dx = -r, r do
                for dy = -r, r do
                    if #spots < 3 and math.max(math.abs(dx), math.abs(dy)) == r and (dx % 2 == 0) and (dy % 2 == 0)
                        and RT.MI.clear(px + dx, py + dy) and RT.MI.clear(px + dx + 1, py + dy) then
                        spots[#spots + 1] = sq(px + dx, py + dy, 0)
                    end
                end
            end
        end
        if #spots < 3 then
            RT.abort = "no clear ground for three generators"
            R:line("OBS  RTDG.spots %d found", #spots)
            return true
        end
        for i, t in ipairs({ "TLG.DieselGenerator", "TLG.DieselGenerator", "Base.Generator" }) do
            local ok, g = pcall(function() return IsoGenerator.new(instanceItem(t), getCell(), spots[i]) end)
            if ok and g then
                g:setFuel(0)
                DG.gens[i] = g
            else
                R:line("OBS  RTDG.new %d %s failed: %s", i, t, tostring(g))
            end
        end
        ctx.placed = ticks
        return nil
    end
    if ticks - ctx.placed < 30 then return nil end
    local lines = {}
    for i = 1, 3 do
        local g = DG.gens[i]
        if g then
            local itemType, sprite = "?", "?"
            pcall(function() itemType = g:getGeneratorItemType() end)
            pcall(function() sprite = g:getSprite():getName() end)
            lines[i] = string.format("%d: IsoGenerator=%s index=%s item type=%s modData.generatorFullType=%s sprite=%s maxFuel=%s fuel=%s condition=%s base profile=%s profile=%s reference fuel=%s",
                i, tostring(instanceof(g, "IsoGenerator")), tostring(g:getObjectIndex()), tostring(itemType),
                tostring(g:getModData().generatorFullType), tostring(sprite), tostring(g:getMaxFuel()), tostring(g:getFuel()),
                tostring(g:getCondition()), tostring(G.baseProfile(g)), tostring(G.profile(g)), tostring(G.referenceFuel(g)))
        else
            lines[i] = i .. ": none"
        end
        R:line("OBS  RTDG.generator %s", lines[i])
    end
    R:check("RTDG.item_becomes_a_generator", function()
        local g = DG.gens[1]
        return g ~= nil and instanceof(g, "IsoGenerator") and g:getObjectIndex() ~= -1 and DG.gens[2] ~= nil, lines[1]
    end)
    R:check("RTDG.generator_keeps_its_type", function()
        local g = DG.gens[1]
        return g ~= nil and g:getModData().generatorFullType == "TLG.DieselGenerator", lines[1]
    end)
    -- The game names a generator's item from its sprite: launch 233, with
    -- vanilla's sprite on the mod's item, read TLG.DieselGenerator here
    -- for the vanilla generator too.
    R:check("RTDG.each_sprite_names_its_own_item", function()
        local a, b = "?", "?"
        pcall(function() a = DG.gens[1]:getGeneratorItemType() end)
        pcall(function() b = DG.gens[3]:getGeneratorItemType() end)
        return a == "TLG.DieselGenerator" and b == "Base.Generator", string.format("the mod's: %s; vanilla's: %s", a, b)
    end)
    R:check("RTDG.sprite_has_its_picture", function()
        local g = DG.gens[1]
        local name, tex, w, h = "?", nil, -1, -1
        pcall(function() name = g:getSprite():getName() end)
        pcall(function() tex = g:getSprite():getTextureForCurrentFrame(g:getDir()) end)
        pcall(function() w, h = tex:getWidth(), tex:getHeight() end)
        return name == TLG.Integration.Generators.SPRITES["TLG.DieselGenerator"] and tex ~= nil and w == 128 and h == 256, string.format("sprite %s, texture %s, %sx%s", tostring(name), tostring(tex ~= nil), tostring(w), tostring(h))
    end)
    R:check("RTDG.diesel_profile", function()
        local g = DG.gens[1]
        return g ~= nil and G.profile(g) == "generator_ci_bio" and G.referenceFuel(g) == "diesel", lines[1]
    end)
    R:check("RTDG.vanilla_generator_keeps_the_petrol_profile", function()
        local g = DG.gens[3]
        return g ~= nil and G.profile(g) == "generator_si_stock" and G.referenceFuel(g) == "gasoline", lines[3]
    end)
    if not (DG.gens[1] and DG.gens[2]) then RT.abort = "the item did not become a generator" end
    return true
end }

-- The diesel generator in loot: the lists as the game holds them, and a
-- crate filled from CrateGenerator as the game fills one
-- (ItemPickerJava.doRollItem, as RT.MN.roll does), many times over.
RT.DG.loot = { name = "rtdg_loot", timeout = 1200, fn = function()
    local function weightIn(items, id)
        for i = 1, #(items or {}) - 1, 2 do
            if items[i] == id then return items[i + 1] end
        end
        return nil
    end
    local crate = ProceduralDistributions and ProceduralDistributions.list and ProceduralDistributions.list.CrateGenerator
    local junk = crate and crate.junk and crate.junk.items
    local beds, missing = 0, {}
    for name, list in pairs(VehicleDistributions or {}) do
        if type(name) == "string" and type(list) == "table" and weightIn(list.items, "Generator") then
            local w = weightIn(list.items, "TLG.DieselGenerator")
            if w == weightIn(list.items, "Generator") * 0.5 then beds = beds + 1 else missing[#missing + 1] = name end
        end
    end
    R:check("RTDG.loot_lists", function()
        return junk ~= nil and weightIn(junk, "TLG.DieselGenerator") == weightIn(junk, "Generator") * 0.5 and beds > 0 and #missing == 0,
            string.format("CrateGenerator junk: Generator=%s TLG.DieselGenerator=%s; vehicle lists with both: %d, without: %s",
                tostring(weightIn(junk, "Generator")), tostring(weightIn(junk, "TLG.DieselGenerator")), beds,
                #missing > 0 and table.concat(missing, ",") or "none")
    end)
    local p, fills, diesel, red, any = player(), 500, 0, 0, 0
    -- The list's junk part, where its generators are (the fourth argument;
    -- launch 238 rolled its items part and got no generator of any kind).
    local dist = ItemPickerJava.getItemContainer("electronicstore", "other", "CrateGenerator", true)
    if dist ~= nil then
        local cont = ItemContainer.new("crate", p:getCurrentSquare(), p)
        for _ = 1, fills do
            cont:removeAllItems()
            ItemPickerJava.doRollItem(dist, cont, 1, p, true, nil)
            local d, r = cont:getItemsFromFullType("TLG.DieselGenerator"), cont:getItemsFromFullType("Base.Generator")
            diesel, red = diesel + (d and d:size() or 0), red + (r and r:size() or 0)
            local items = cont:getItems()
            for i = 0, items:size() - 1 do
                if TLG.Integration.Generators.ITEM_TYPES[items:get(i):getFullType()] then any = any + 1 end
            end
        end
        cont:removeAllItems()
    end
    R:check("RTDG.rolled_from_loot", function()
        return dist ~= nil and diesel > 0 and red > 0, string.format(
            "%d fills of an electronics store's crate list: %d diesel generators, %d Base.Generator, %d generators of any kind",
            fills, diesel, red, any)
    end)
    return true
end }

RT.DG.pour = actionStep("rtdg_pour_biodiesel", function(ctx)
    if RT.skip("rtdg_pour_biodiesel") then return nil end
    local g = RT.DG.gens[1]
    local can, fc = giveCan("Base.JerryCan", { { Fluid.Get("TLG_Biodiesel"), 5.0 } })
    player():setPrimaryHandItem(can)
    player():teleportTo(g:getSquare():getX() + 1, g:getSquare():getY(), 0)
    hopBegin(ctx, "RTDG.pour_biodiesel", "item", can, canAmount(fc), "generator", g, function() return g:getFuel() end)
    return ISTLGPourFuel:new(player(), can, TLG.Authority.Resolver.refForObject(g, "generator"), g, false,
        function(reply) ctx.reply = reply end)
end, function(ctx)
    R:check("RTDG.pour_biodiesel.reply_ok", function()
        return ctx.reply ~= nil and ctx.reply.ok == true, brief(ctx.reply)
    end)
    hopEnd(ctx, true)
    player():setPrimaryHandItem(nil)
    -- The gate's roll is held at its highest for the start that follows:
    -- only a start factor of 1 passes (the stock diesel profile gave 0.6 on
    -- pure biodiesel and lost the roll in launch 233).
    RT.DG.roll = TLG.Integration.Generators.startRoll
    TLG.Integration.Generators.startRoll = function() return 0.999 end
end)

-- Vanilla's pickup: the item it gives must be the generator's own type.
function RT.DG.take(i, want)
    return actionStep("rtdg_take_" .. i, function(ctx)
        if RT.skip("rtdg_take_" .. i) then return nil end
        local g = RT.DG.gens[i]
        player():setPrimaryHandItem(nil)
        player():setSecondaryHandItem(nil)
        player():teleportTo(g:getSquare():getX() + 1, g:getSquare():getY(), 0)
        ctx.fuel = g:getFuel()
        return ISTakeGenerator:new(player(), g)
    end, function(ctx)
        local it = player():getPrimaryHandItem()
        local side = it and it:getModData().tlg
        R:check("RTDG.take_gives_" .. string.gsub(want, "%.", "_"), function()
            return it ~= nil and it:getFullType() == want and RT.DG.gens[i]:getObjectIndex() == -1,
                string.format("in hand: %s \"%s\"; fuel it held %.4f; record on the item: %s", tostring(it and it:getFullType()),
                    tostring(it and it:getDisplayName()), ctx.fuel, side and brief(side.q) or "none")
        end)
    end)
end

RT.DG.run = { name = "rtdg_run", timeout = 30000, fn = function(ctx, ticks)
    local g = RT.DG.gens[1]
    if not ctx.h0 and RT.skip("rtdg_run") then return true end
    if not ctx.h0 then
        if RT.DG.roll then TLG.Integration.Generators.startRoll, RT.DG.roll = RT.DG.roll, nil end
        g:setConnected(true)
        g:setActivated(true)
        ctx.h0, ctx.f0 = hours(), g:getFuel()
        RT.speed(40)
        return nil
    end
    if ticks % 30 == 0 then RT.keepFit() end
    if hours() - ctx.h0 < 2 and ticks < 28000 then return nil end
    RT.speed(1)
    local on, f1 = g:isActivated(), g:getFuel()
    local v, status = tlgView("generator", g)
    R:check("RTDG.runs_on_biodiesel", function()
        return on and f1 < ctx.f0 - 0.01 and v ~= nil and math.abs(TLG.Domain.Supply.total(v) - f1) <= 1e-3
            and (v.q.biodiesel or 0) > 0 and (v.q.gasoline or 0) == 0,
            string.format("ran %.2f game h, activated=%s, fuel %.4f -> %.4f; record %s", hours() - ctx.h0, tostring(on), ctx.f0, f1,
                viewText(v, status))
    end)
    g:setActivated(false)
    g:setConnected(false)
    return true
end }

RT.DG.petrol = actionStep("rtdg_add_petrol", function(ctx)
    if RT.skip("rtdg_add_petrol") then return nil end
    local g = RT.DG.gens[2]
    local can = giveCan("Base.PetrolCan", { { Fluid.Petrol, 5.0 } })
    player():setPrimaryHandItem(can)
    player():teleportTo(g:getSquare():getX() + 1, g:getSquare():getY(), 0)
    ctx.f0 = g:getFuel()
    return ISAddFuel:new(player(), g, can)
end, function(ctx)
    local g = RT.DG.gens[2]
    local v, status = tlgView("generator", g)
    R:check("RTDG.petrol_goes_in_as_petrol", function()
        return g:getFuel() > ctx.f0 + 4 and v ~= nil and (v.q.gasoline or 0) > 4 and (v.q.diesel or 0) == 0,
            string.format("fuel %.4f -> %.4f; record %s", ctx.f0, g:getFuel(), viewText(v, status))
    end)
    player():setPrimaryHandItem(nil)
end)

-- Holds both start rolls at `value` (a start then passes only with a start
-- factor above it), or gives them back with nil. Since 0.3.0 petrol in a
-- diesel engine no longer blocks the start: it lowers the start factor to
-- 0.25, so the older modes' refusals need the roll held high.
function RT.rollStep(name, value)
    return { name = name, timeout = 60, fn = function()
        local V, G, WF = TLG.Integration.Vehicles, TLG.Integration.Generators, RT
        if value ~= nil then
            WF.rolls = WF.rolls or { V.startRoll, G.startRoll }
            V.startRoll, G.startRoll = function() return value end, function() return value end
        elseif WF.rolls then
            V.startRoll, G.startRoll = WF.rolls[1], WF.rolls[2]
            WF.rolls = nil
        end
        return true
    end }
end

RT.dieselGeneratorSteps = { RT.waitWorld, RT.BD.photoSetup, RT.DG.loot, RT.DG.place, RT.DG.pour,
    generatorGateStep("RTDG.gate_biodiesel", function() return RT.DG.gens[1] end, false), RT.DG.run, RT.DG.petrol,
    RT.rollStep("rtdg_roll_held", 0.999),
    generatorGateStep("RTDG.gate_petrol", function() return RT.DG.gens[2] end, true),
    RT.rollStep("rtdg_roll_free", nil),
    RT.MI.zoomTo("rtdg_zoom", 0.5), RT.MI.shot("rtdg_generators", true),
    RT.DG.take(3, "Base.Generator"), RT.DG.take(2, "TLG.DieselGenerator"),
    RT.saveAndExitAs("rtdg_save_and_exit", "sp-rtdgb") }

-- After the save is continued (request "sp-rtdgb"): the diesel generator
-- left on the ground must still be one, with its sprite, its fuel and its
-- profile, and the one carried still its own item; then it is taken.
RT.DG.reload = { name = "rtdgb_reload", timeout = 3000, fn = function(ctx, ticks)
    local G = TLG.Integration.Generators
    if not (player() and ticks > 180) then return nil end
    local px, py = math.floor(player():getX()), math.floor(player():getY())
    local seen, diesel = {}, nil
    for dx = -20, 20 do
        for dy = -20, 20 do
            local s = sq(px + dx, py + dy, 0)
            local objs = s and s:getObjects()
            for i = 0, (objs and objs:size() or 0) - 1 do
                local o = objs:get(i)
                if instanceof(o, "IsoGenerator") then
                    local name, itemType = "?", "?"
                    pcall(function() name = o:getSprite():getName() end)
                    pcall(function() itemType = o:getGeneratorItemType() end)
                    seen[#seen + 1] = string.format("%d,%d: generatorFullType=%s item type=%s sprite=%s fuel=%.4f profile=%s",
                        px + dx, py + dy, tostring(o:getModData().generatorFullType), tostring(itemType), tostring(name), o:getFuel(),
                        tostring(G.profile(o)))
                    if o:getModData().generatorFullType == "TLG.DieselGenerator" then diesel = o end
                end
            end
        end
    end
    for _, line in ipairs(seen) do R:line("OBS  RTDGB.generator %s", line) end
    R:check("RTDGB.diesel_generator_survives_the_save", function()
        if diesel == nil then return false, "none found among " .. #seen end
        local name, itemType, tex = "?", "?", nil
        pcall(function() name = diesel:getSprite():getName() end)
        pcall(function() itemType = diesel:getGeneratorItemType() end)
        pcall(function() tex = diesel:getSprite():getTextureForCurrentFrame(diesel:getDir()) end)
        local v, status = tlgView("generator", diesel)
        return name == G.SPRITES["TLG.DieselGenerator"] and itemType == "TLG.DieselGenerator" and tex ~= nil
            and G.profile(diesel) == "generator_ci_bio" and v ~= nil and (v.q.biodiesel or 0) > 4,
            string.format("sprite %s, picture %s, item type %s, profile %s, record %s", tostring(name), tostring(tex ~= nil),
                tostring(itemType), tostring(G.profile(diesel)), viewText(v, status))
    end)
    local carried = {}
    local items = player():getInventory():getItems()
    for i = 0, items:size() - 1 do
        if G.ITEM_TYPES[items:get(i):getFullType()] then carried[#carried + 1] = items:get(i):getFullType() end
    end
    R:check("RTDGB.carried_generator_is_still_diesel", function()
        local diesels = 0
        for _, c in ipairs(carried) do if c == "TLG.DieselGenerator" then diesels = diesels + 1 end end
        return diesels == 1, table.concat(carried, ",")
    end)
    RT.DG.gens[1] = diesel
    if diesel == nil then RT.abort = "no diesel generator after the reload" end
    return true
end }

RT.dieselGeneratorReloadSteps = { RT.DG.reload, RT.MI.zoomTo("rtdgb_zoom", 0.5), RT.MI.shot("rtdg_reloaded", true),
    RT.DG.take(1, "TLG.DieselGenerator"), RT.finish }

------------------------------------------------------------------------------
-- Gas probe (requests "sp-rtgp", then "sp-rtgpb"; D-039): what the game
-- does with a generator kept running on gas from outside its own tank. The
-- mod has no gas generator yet, so the probe stands in for one:
-- - Generator A runs on a buffer. Each game minute the probe reads the
--   litres the game burned since the last minute, sets the fuel back to the
--   buffer and draws the propane those litres are worth, energy for energy
--   (the TLG fuel definitions), from a propane tank lying beside A: whole
--   uses through Gas.nm3ToUses, the remainder carried. Generator B, the
--   control, runs on its own tank. The sandbox's generator fuel use is
--   raised (GeneratorFuelConsumption 10; the default is 0.1) so a minute's
--   burn is measurable; the rate itself is measured from B.
-- - Phase A runs both for 2 game hours at speed 40, writes what it expects
--   and saves. Phase B continues the save, checks both generators and the
--   tank, runs 1 more hour on the buffer, then makes a trip far enough away
--   for their chunk to unload: no Lua runs there, so A gets a buffer of an
--   hour's burn for a 4-hour trip and B keeps its tank. Both are found again
--   on return. Last, A runs dry while loaded, to see whether it stops.
-- - A propane tank's uses are written once between two whole uses and read
--   back, to see whether the game keeps a fraction of a use.
------------------------------------------------------------------------------
RT.GP = { buffer = 1.0, bFuel = 8.0, hoursA = 2, hoursB = 1, tripHours = 4, gens = {}, calls = 0, burned = 0, drawn = 0,
    mismatch = 0, offMinutes = 0, lowest = 0, carry = 0, aDrops = {}, bDrops = {} }

function RT.GP.tankUses()
    local t = RT.GP.tank
    if t == nil then return -1 end
    return t:getCurrentUsesFloat() / t:getUseDelta()
end

function RT.GP.power(g)
    local p = -1
    pcall(function() p = g:getTotalPowerUsing() end)
    return p
end

function RT.GP.log(label)
    local GP = RT.GP
    local a, b = GP.gens.A, GP.gens.B
    R:line("OBS  RTGP.%s at %.3f h: A fuel %s activated=%s power %.4f; B fuel %s activated=%s power %.4f; tank %.3f uses; " ..
        "GeneratorFuelConsumption %s", label, hours(), a and string.format("%.4f", a:getFuel()) or "-",
        tostring(a and a:isActivated()), a and GP.power(a) or -1, b and string.format("%.4f", b:getFuel()) or "-",
        tostring(b and b:isActivated()), b and GP.power(b) or -1, GP.tankUses(), tostring(SandboxVars.GeneratorFuelConsumption))
end

-- Propane (Nm3) worth `litres` of petrol, energy for energy.
function RT.GP.nm3For(litres)
    local Reg = TLG.Registry
    return litres * Reg.need("fuel", "gasoline").energyMJ / Reg.need("fuel", "propane").energyMJ
end

-- The probe's minute: A's burn read, A set back to its buffer, the tank
-- charged in whole uses with the rest carried.
function RT.GP.onMinute()
    local GP = RT.GP
    local a = GP.gens.A
    if a == nil or not GP.feeding then return end
    GP.calls = GP.calls + 1
    local f = a:getFuel()
    if f < GP.lowest then GP.lowest = f end
    if not a:isActivated() then GP.offMinutes = GP.offMinutes + 1 end
    local burned = math.max(0, GP.bufferNow - f)
    GP.burned = GP.burned + burned
    -- Each drop of either generator's fuel since the last minute (launch
    -- 342: the game burns a generator's fuel in one step each game hour).
    if burned > 1e-9 then GP.aDrops[#GP.aDrops + 1] = burned end
    local b = GP.gens.B
    if b then
        local fb = b:getFuel()
        if GP.lastB and fb < GP.lastB - 1e-9 then GP.bDrops[#GP.bDrops + 1] = GP.lastB - fb end
        GP.lastB = fb
    end
    a:setFuel(GP.bufferNow)
    local uses, rem = TLG.Domain.Gas.nm3ToUses(GP.nm3For(burned) + GP.carry)
    GP.carry = rem or 0
    if (uses or 0) > 0 and GP.tank then
        local before = GP.tankUses()
        local want = math.max(0, before - uses)
        GP.tank:setUsedDelta(want * GP.tank:getUseDelta())
        local back = GP.tankUses()
        GP.drawn = GP.drawn + (before - back)
        if math.abs(back - want) > 1e-3 then GP.mismatch = GP.mismatch + 1 end
    end
end

function RT.GP.feed(on)
    local GP = RT.GP
    if on and not GP.hooked then
        Events.EveryOneMinute.Add(GP.onMinute)
        GP.hooked = true
    elseif not on and GP.hooked then
        Events.EveryOneMinute.Remove(GP.onMinute)
        GP.hooked = false
    end
    GP.feeding = on == true
end

-- Generators A and B and the tank found on their squares: A at x,y, the
-- tank one east of it, B six east.
function RT.GP.find(x, y)
    local GP = RT.GP
    local sa, sb, st = sq(x, y, 0), sq(x + 6, y, 0), sq(x + 1, y, 0)
    GP.gens.A = sa and sa:getGenerator() or nil
    GP.gens.B = sb and sb:getGenerator() or nil
    GP.tank = nil
    local objs = st and st:getWorldObjects()
    for i = 0, (objs and objs:size() or 0) - 1 do
        local it = objs:get(i):getItem()
        if it and it:getFullType() == "Base.PropaneTank" then GP.tank = it end
    end
    return GP.gens.A ~= nil and GP.gens.B ~= nil and GP.tank ~= nil
end

RT.GP.setup = { name = "rtgp_setup", timeout = 1200, fn = function(ctx, ticks)
    local GP = RT.GP
    if not ctx.t0 then
        local p = player()
        p:setGodMod(true)
        p:setInvisible(true)
        RT.keepFit()
        ctx.t0 = ticks
        return nil
    end
    if ticks - ctx.t0 < 60 then return nil end
    local spot
    for dy = 4, 16 do
        for dx = -12, 12 do
            local x, y = START.x + dx, START.y + dy
            if spot == nil and RT.MI.clear(x, y) and RT.MI.clear(x + 1, y) and RT.MI.clear(x + 6, y) then spot = { x = x, y = y } end
        end
    end
    if spot == nil then
        RT.abort = "no clear row for the generators"
        R:check("RTGP.placed", function() return false, "no clear row near the start" end)
        return true
    end
    GP.spot = spot
    pcall(function() IsoGenerator.new(instanceItem("Base.Generator"), getCell(), sq(spot.x, spot.y, 0)) end)
    pcall(function() IsoGenerator.new(instanceItem("Base.Generator"), getCell(), sq(spot.x + 6, spot.y, 0)) end)
    sq(spot.x + 1, spot.y, 0):AddWorldInventoryItem(instanceItem("Base.PropaneTank"), 0.5, 0.5, 0, false)
    local found = GP.find(spot.x, spot.y)
    local t = GP.tank
    local full, whole, maxFuel = GP.tankUses(), t and t:getCurrentUses(), GP.gens.A and GP.gens.A:getMaxFuel()
    -- A value between two whole uses, read back, then the tank full again.
    local between, betweenWhole = -1, nil
    if t then
        t:setUsedDelta(4999.5 * t:getUseDelta())
        between, betweenWhole = GP.tankUses(), t:getCurrentUses()
        t:setUsedDelta(1.0)
    end
    R:line("OBS  RTGP.placed A at %d,%d, the tank at %d,%d, B at %d,%d; max fuel %s L; the tank: useDelta %s, %.3f uses " ..
        "(getCurrentUses %s); set to 4999.5 uses it read %.4f (getCurrentUses %s); full again %.3f", spot.x, spot.y, spot.x + 1,
        spot.y, spot.x + 6, spot.y, tostring(maxFuel), tostring(t and t:getUseDelta()), full, tostring(whole), between,
        tostring(betweenWhole), GP.tankUses())
    R:check("RTGP.placed", function()
        return found and math.abs(GP.tankUses() - 5000) < 1e-3, string.format("A %s, B %s, tank %s with %.3f uses",
            tostring(GP.gens.A ~= nil), tostring(GP.gens.B ~= nil), tostring(t ~= nil), GP.tankUses())
    end)
    if not found then RT.abort = "a generator or the tank is missing" end
    return true
end }

RT.GP.start = { name = "rtgp_start", timeout = 300, fn = function(ctx, ticks)
    local GP = RT.GP
    if RT.abort then return true end
    local a, b = GP.gens.A, GP.gens.B
    if not ctx.on then
        GP.bufferNow = GP.buffer
        a:setFuel(GP.buffer)
        b:setFuel(GP.bFuel)
        for _, g in ipairs({ a, b }) do
            g:setConnected(true)
            g:setActivated(true)
        end
        ctx.on = ticks
        return nil
    end
    if ticks - ctx.on < 30 then return nil end
    GP.log("started")
    R:check("RTGP.both_running", function()
        return a:isActivated() and b:isActivated(), string.format("A %s, B %s", tostring(a:isActivated()), tostring(b:isActivated()))
    end)
    return true
end }

-- A on its buffer and B on its tank for `h` game hours at speed 40.
function RT.GP.runStep(name, h, label)
    return { name = name, timeout = 30000, fn = function(ctx, ticks)
        local GP, Gas = RT.GP, TLG.Domain.Gas
        local a, b = GP.gens.A, GP.gens.B
        if RT.abort then return true end
        if not ctx.h0 then
            GP.calls, GP.burned, GP.drawn, GP.mismatch, GP.offMinutes, GP.lowest = 0, 0, 0, 0, 0, math.huge
            GP.aDrops, GP.bDrops, GP.lastB = {}, {}, b:getFuel()
            GP.bufferNow = GP.buffer
            a:setFuel(GP.buffer)
            ctx.h0, ctx.b0, ctx.u0, ctx.carry0 = hours(), b:getFuel(), GP.tankUses(), GP.carry
            GP.log(label .. "_start")
            GP.feed(true)
            RT.speed(40)
            return nil
        end
        if ticks % 30 == 0 then RT.keepFit() end
        if hours() - ctx.h0 < h then return nil end
        RT.speed(1)
        GP.feed(false)
        local gone = hours() - ctx.h0
        local minutes = math.floor(gone * 60 + 0.5)
        local bBurned = ctx.b0 - b:getFuel()
        GP.rate = bBurned / gone
        local inNm3 = GP.nm3For(GP.burned) + ctx.carry0
        local outNm3 = GP.drawn * Gas.NM3_PER_USE + GP.carry
        GP.log(label .. "_end")
        R:line("OBS  RTGP.%s: %.3f game h, %d game minutes, %d minute calls; A burned %.4f L (lowest fuel before a top-up %.4f, " ..
            "%d minutes not running); B burned %.4f L, %.5f L an hour; the tank %.3f -> %.3f uses, %.3f drawn; the propane owed " ..
            "%.6f Nm3, drawn and carried %.6f Nm3 (%.6f carried); %d writes read back otherwise", label, gone, minutes, GP.calls,
            GP.burned, GP.lowest, GP.offMinutes, bBurned, GP.rate, ctx.u0, GP.tankUses(), GP.drawn, inNm3, outNm3, GP.carry, GP.mismatch)
        R:check("RTGP." .. label .. "_a_ran_on_its_buffer", function()
            return GP.offMinutes == 0 and a:isActivated() and math.abs(GP.calls - minutes) <= 2,
                string.format("%d minutes not running, activated at the end %s, %d calls for %d game minutes", GP.offMinutes,
                    tostring(a:isActivated()), GP.calls, minutes)
        end)
        -- Launch 342 compared the litres of a stretch and failed: A and B
        -- draw different power, and a stretch counts the hourly steps that
        -- fall before its last minute. Each step's size per unit of power
        -- is what both must share.
        local function spread(list)
            local lo, hi = math.huge, -math.huge
            for _, x in ipairs(list) do lo, hi = math.min(lo, x), math.max(hi, x) end
            return lo, hi
        end
        local aLo, aHi = spread(GP.aDrops)
        local bLo, bHi = spread(GP.bDrops)
        local pa, pb = GP.power(a), GP.power(b)
        local fa = (#GP.aDrops > 0 and pa > 0) and aHi / pa or -1
        local fb = (#GP.bDrops > 0 and pb > 0) and bHi / pb or -1
        local steps = string.format("A %d steps of %.4f-%.4f L at power %.4f (%.4f L a unit), B %d steps of %.4f-%.4f L at " ..
            "power %.4f (%.4f L a unit), in %.3f game h", #GP.aDrops, aLo, aHi, pa, fa, #GP.bDrops, bLo, bHi, pb, fb, gone)
        R:line("OBS  RTGP.%s steps: %s", label, steps)
        if #GP.aDrops > 0 then GP.aStep = aHi end
        -- Steps read as differences of float fuel values (0.8 L from 8 L
        -- differ by about 5e-7), hence the 1e-4 spread.
        R:check("RTGP." .. label .. "_hourly_steps_by_power", function()
            return #GP.aDrops >= 1 and #GP.bDrops >= 1 and #GP.aDrops <= math.ceil(gone) and #GP.bDrops <= math.ceil(gone)
                and aHi - aLo < 1e-4 and bHi - bLo < 1e-4 and fb > 0 and math.abs(fa - fb) <= 0.01 * fb, steps
        end)
        R:check("RTGP." .. label .. "_tank_paid_exactly", function()
            return GP.mismatch == 0 and GP.drawn > 0 and math.abs(inNm3 - outNm3) < 1e-6,
                string.format("owed %.6f Nm3, drawn %.3f uses and %.6f Nm3 carried, %d writes read back otherwise", inNm3,
                    GP.drawn, GP.carry, GP.mismatch)
        end)
        return true
    end }
end

RT.GP.beforeSave = { name = "rtgp_before_save", fn = function()
    local GP = RT.GP
    GP.feed(false)
    RT.speed(1)
    local a, b = GP.gens.A, GP.gens.B
    if RT.abort or a == nil or b == nil then return true end
    TLGH.writeFile("TLG_harness_expect.txt", { "gp.x=" .. GP.spot.x, "gp.y=" .. GP.spot.y,
        "gp.aFuel=" .. string.format("%.6f", a:getFuel()), "gp.bFuel=" .. string.format("%.6f", b:getFuel()),
        "gp.uses=" .. string.format("%.6f", GP.tankUses()), "gp.rate=" .. string.format("%.6f", GP.rate or 0),
        "gp.carry=" .. string.format("%.9f", GP.carry), "gp.h=" .. string.format("%.6f", hours()) })
    GP.log("saving")
    return true
end }

RT.gasProbeSteps = { RT.waitWorld, RT.GP.setup, RT.GP.start, RT.GP.runStep("rtgp_feed", RT.GP.hoursA, "phase_a"),
    RT.GP.beforeSave, RT.saveAndExitAs("rtgp_save_and_exit", "sp-rtgpb") }

-- After the save is continued (request "sp-rtgpb"): both generators and the
-- tank found by position, as they were saved.
RT.GP.reload = { name = "rtgpb_reload", timeout = 3000, fn = function(ctx, ticks)
    local GP = RT.GP
    if not (player() and ticks > 180) then return nil end
    local e = TLGH.readKeyValues("TLG_harness_expect.txt")
    local x, y = tonumber(e["gp.x"]), tonumber(e["gp.y"])
    if x == nil or y == nil then
        RT.abort = "no expectations from before the save"
        R:check("RTGPB.expectations_read", function() return false, "TLG_harness_expect.txt has no gp.x/gp.y" end)
        return true
    end
    GP.spot, GP.rate, GP.carry = { x = x, y = y }, tonumber(e["gp.rate"]) or 0, tonumber(e["gp.carry"]) or 0
    local found = GP.find(x, y)
    GP.log("after_the_reload")
    if not found then
        RT.abort = "a generator or the tank is missing after the reload"
        R:check("RTGPB.found_after_the_reload", function()
            return false, string.format("A %s, B %s, tank %s", tostring(GP.gens.A ~= nil), tostring(GP.gens.B ~= nil),
                tostring(GP.tank ~= nil))
        end)
        return true
    end
    local a, b = GP.gens.A, GP.gens.B
    local gone = math.max(0, hours() - (tonumber(e["gp.h"]) or hours()))
    local tol = GP.rate * gone + 0.005
    local da, db = math.abs(a:getFuel() - tonumber(e["gp.aFuel"])), math.abs(b:getFuel() - tonumber(e["gp.bFuel"]))
    local du = math.abs(GP.tankUses() - tonumber(e["gp.uses"]))
    R:check("RTGPB.as_saved", function()
        return a:isActivated() and b:isActivated() and da <= tol and db <= tol and du < 1e-3,
            string.format("A activated %s, fuel off by %.5f; B activated %s, fuel off by %.5f (allowed %.5f for %.3f game h); " ..
                "tank off by %.5f uses", tostring(a:isActivated()), da, tostring(b:isActivated()), db, tol, gone, du)
    end)
    return true
end }

-- The trip: the generators' chunk unloads while the player is away, so no
-- Lua tops A up; A gets an hour's burn for a longer trip, B keeps its tank.
RT.GP.trip = { name = "rtgpb_trip", timeout = 30000, fn = function(ctx, ticks)
    local GP = RT.GP
    if RT.abort then return true end
    if not ctx.at then
        GP.feed(false)
        local a, b = GP.gens.A, GP.gens.B
        -- A's own hourly step (launch 342 used B's rate here), B's rate.
        ctx.step, ctx.rate = GP.aStep or math.max(GP.rate or 0, 0.01), math.max(GP.rate or 0, 0.01)
        a:setFuel(ctx.step)
        ctx.a0, ctx.b0, ctx.h0 = a:getFuel(), b:getFuel(), hours()
        GP.log("leaving")
        RT.speed(1)
        player():teleportTo(GP.spot.x, GP.spot.y - RT.away, 0)
        ctx.at = ticks
        return nil
    end
    if not ctx.awayFrom then
        if ticks - ctx.at < 120 then return nil end
        ctx.awayFrom = hours()
        RT.speed(RT.waitSpeed)
        return nil
    end
    if ticks % 30 == 0 then RT.keepFit() end
    if not ctx.back then
        if sq(GP.spot.x, GP.spot.y, 0) == nil then ctx.unloaded = true end
        if hours() - ctx.awayFrom < GP.tripHours then return nil end
        RT.speed(1)
        player():teleportTo(GP.spot.x - 2, GP.spot.y + 2, 0)
        ctx.back, ctx.gone = ticks, hours() - ctx.h0
        return nil
    end
    if ticks - ctx.back < 180 then return nil end
    local found = GP.find(GP.spot.x, GP.spot.y)
    local a, b = GP.gens.A, GP.gens.B
    GP.log("back")
    R:line("OBS  RTGPB.trip: their square unloaded while away %s; gone %.3f game h; A fuel %.4f (one hourly step) -> %s " ..
        "activated=%s; B fuel %.4f -> %s activated=%s; at its rate the trip burns %.4f L of B's", tostring(ctx.unloaded == true),
        ctx.gone, ctx.a0, a and string.format("%.4f", a:getFuel()) or "-", tostring(a and a:isActivated()), ctx.b0,
        b and string.format("%.4f", b:getFuel()) or "-", tostring(b and b:isActivated()), ctx.rate * ctx.gone)
    R:check("RTGPB.trip_unloaded_and_found_again", function()
        return ctx.unloaded == true and found, string.format("unloaded %s, found %s", tostring(ctx.unloaded == true), tostring(found))
    end)
    if not found then RT.abort = "a generator or the tank is missing after the trip" end
    return true
end }

-- A given a few minutes' burn and run dry while loaded: does it stop?
RT.GP.runDry = { name = "rtgpb_run_dry", timeout = 30000, fn = function(ctx, ticks)
    local GP = RT.GP
    if RT.abort then return true end
    local a = GP.gens.A
    if not ctx.h0 then
        ctx.buffer = (GP.aStep or math.max(GP.rate or 0, 0.01)) * 0.1
        a:setFuel(ctx.buffer)
        a:setConnected(true)
        a:setActivated(true)
        ctx.h0 = hours()
        GP.log("run_dry_start")
        RT.speed(40)
        return nil
    end
    if ticks % 30 == 0 then RT.keepFit() end
    if not ctx.ended then
        if a:getFuel() > 0 and a:isActivated() and hours() - ctx.h0 < 1 then return nil end
        RT.speed(1)
        ctx.ended, ctx.gone = ticks, hours() - ctx.h0
        return nil
    end
    if ticks - ctx.ended < 120 then return nil end
    GP.log("run_dry_end")
    R:check("RTGPB.a_stops_when_dry", function()
        return a:getFuel() <= 1e-6 and not a:isActivated(), string.format("fuel %.6f, activated %s, %.3f game h after a %.4f L buffer",
            a:getFuel(), tostring(a:isActivated()), ctx.gone, ctx.buffer)
    end)
    R:check("RTGPB.b_still_running", function()
        local b = GP.gens.B
        return b ~= nil and b:isActivated() and b:getFuel() > 0, string.format("B fuel %s, activated %s",
            b and string.format("%.4f", b:getFuel()) or "-", tostring(b and b:isActivated()))
    end)
    return true
end }

RT.gasProbeReloadSteps = { RT.GP.reload, RT.GP.runStep("rtgpb_feed", RT.GP.hoursB, "phase_b"), RT.GP.trip, RT.GP.runDry,
    RT.finish }

------------------------------------------------------------------------------
-- Gas measures (request "sp-rtgm"; D-040, "to measure before building").
-- The game's code (BC IsoGenerator, 42.22.2): each time the integer world-age
-- hour changes, a running generator loses getTotalPowerUsing() litres, its
-- load as last computed times the fuel setting, and at 0 or less it
-- switches off. Switching an appliance on only flags the generators in
-- range (IsoGenerator.updateGenerator); each recomputes its load in its next
-- update, after that update's burn. Whether a refill covers the next step
-- therefore depends on when the refill runs against the generator's update.
-- One generator, A, with a battery charger beside it as the load the probe
-- switches (0.05 while on, BC IsoCarBatteryCharger). A runs on 1 L or less,
-- so a step reads to about 1e-7 L. The fuel setting is the default, read
-- from the game as getBasePowerConsumption() / 0.02.
--   1. The charger raises A's load by 0.05 x the setting and the load falls
--      back when it is off; otherwise the stages after it are skipped.
--   2. Steps on A's own fuel: each against the load read the tick before,
--      at which world age, and whether the tick watcher and the first
--      minute event of the hour saw the step already.
--   3. The charger on half way through an hour and off half way through the
--      next: each step is the load of its moment.
--   4. The fuel set to exactly one step late in the hour: A off after the
--      boundary. Then one step + 1e-4: A runs on with 1e-4 left.
--   5. Refills to one step + 1e-4, setFuel only below that, while the
--      charger is switched on after the hour's minute-59 event and before
--      the boundary (an attempt counts only if A's load rose in between):
--      on each tick at speed 20, on each minute event at speed 20, on each
--      tick at speed 100.
--   6. A propane tank item in the inventory given a number of uses, read
--      back (independent of the stages before).
------------------------------------------------------------------------------
RT.GM = { eps = 1e-4, tol = 2e-7 }

function RT.GM.power(g)
    local p = -1
    pcall(function() p = g:getTotalPowerUsing() end)
    return p
end

-- The fuel setting the game uses: BC getBasePowerConsumption is 0.02 x it.
function RT.GM.setting(g)
    local s = -1
    pcall(function() s = g:getBasePowerConsumption() / 0.02 end)
    return s
end

function RT.GM.powered(g)
    local s = "?"
    pcall(function() s = tostring(g:getItemsPowered()) end)
    return s
end

function RT.GM.charging(on)
    local GM = RT.GM
    if GM.charger == nil then return end
    -- A drained battery, so the charger has charging to do.
    if on then pcall(function() GM.battery:setUsedDelta(0) end) end
    GM.charger:setActivated(on == true)
end

function RT.GM.clear()
    local GM = RT.GM
    GM.drops, GM.boundaries, GM.marks, GM.attempts = {}, {}, {}, {}
    GM.minutes, GM.refills, GM.offTicks, GM.stops, GM.trims = 0, 0, 0, 0, 0
    GM.attempt, GM.lastAttempt, GM.attemptHour, GM.min59Hour, GM.onStageTick = nil, nil, nil, nil, nil
    GM.boundary, GM.lastFuel, GM.minuteFuel, GM.trimFrom = nil, nil, nil, nil
end

-- The tick watcher. A drop of A's fuel is a step: its size against the load
-- read the tick before, its world age, and how many ticks after this
-- watcher first saw the new hour. Then the stage's own actions, the late
-- switch-ons and the per-tick refill.
function RT.GM.onTick()
    local GM = RT.GM
    local a = GM.a
    if a == nil or not GM.watching then return end
    GM.tick = (GM.tick or 0) + 1
    local age = hours()
    local fl = math.floor(age)
    local f, p, on = a:getFuel(), GM.power(a), a:isActivated()
    if GM.lastFloor ~= nil and fl > GM.lastFloor then
        local b = { age = age, tick = GM.tick, ms = getTimestampMs(),
            dropped = GM.lastFuel ~= nil and f < GM.lastFuel - 1e-9 }
        GM.boundaries[#GM.boundaries + 1] = b
        GM.boundary = b
        if GM.attempt then
            -- A refill between the rise and here: the minute event of the
            -- boundary's frame runs before this watcher (launch 345).
            GM.attempt.boundary = b
            GM.attempt.refilledBetween = GM.attempt.refillsAtRise ~= nil and GM.refills > GM.attempt.refillsAtRise
            GM.lastAttempt, GM.attempt = GM.attempt, nil
        end
    end
    if GM.lastFuel ~= nil and f < GM.lastFuel - 1e-9 then
        local b = GM.boundary
        local d = { age = age, drop = GM.lastFuel - f, before = GM.lastPower, after = f, on = on,
            ticks = b and (GM.tick - b.tick) or -1 }
        GM.drops[#GM.drops + 1] = d
        R:line("OBS  RTGM.%s drop at %.5f h: %.7f L (the load read the tick before %.7f), fuel now %.7f, running %s, " ..
            "%d ticks after the boundary was seen; charger on %s", GM.stage or "?", age, d.drop, d.before or -1, f,
            tostring(on), d.ticks, tostring(GM.charger and GM.charger:isActivated()))
    end
    if GM.lastOn and not on then
        GM.stops = GM.stops + 1
        R:line("OBS  RTGM.%s A stopped at %.5f h, fuel %.7f", GM.stage or "?", age, f)
    end
    if not on then GM.offTicks = GM.offTicks + 1 end
    -- A stop within 5 ticks of the boundary that closed an attempt is that
    -- attempt's.
    local la = GM.lastAttempt
    if la and la.boundary and GM.tick - la.boundary.tick <= 5 and not on then la.stopped = true end
    if GM.onStageTick then GM.onStageTick(age, fl, f, p, on) end
    if GM.late and GM.charger then
        if GM.attempt == nil and GM.attemptHour ~= fl and GM.min59Hour == fl and on then
            -- After this hour's minute-59 event and before its boundary.
            GM.charging(true)
            GM.attempt = { hour = fl, at = age, powerBefore = p, rose = false }
            GM.attempts[#GM.attempts + 1] = GM.attempt
            GM.attemptHour = fl
        elseif GM.attempt and not GM.attempt.rose and p > GM.attempt.powerBefore + GM.chargerStep / 2 then
            -- The test means something only if the buffer is short of the
            -- new step when the rise is seen: a refill must then land
            -- between the rise and the burn.
            GM.attempt.rose, GM.attempt.roseAt = true, age
            GM.attempt.short, GM.attempt.fuelAtRise, GM.attempt.refillsAtRise = f < p, f, GM.refills
        end
        if GM.attemptHour ~= fl and age - fl >= 0.5 and GM.charger:isActivated() then
            GM.charging(false)
            GM.trimFrom = p
        end
        -- Once the load has fallen back, the buffer is set down to it, so
        -- the next switch-on finds it sized for the lower load (launches
        -- 345-347 kept the higher one, and most switch-ons tested nothing).
        if GM.trimFrom and p < GM.trimFrom - GM.chargerStep / 2 then
            if a:getFuel() > p + GM.eps then
                a:setFuel(p + GM.eps)
                GM.trims = GM.trims + 1
            end
            GM.trimFrom = nil
        end
    end
    if GM.refill == "tick" and a:isActivated() then
        local cap = GM.power(a) + GM.eps
        if a:getFuel() < cap - GM.eps / 2 then
            a:setFuel(cap)
            GM.refills = GM.refills + 1
        end
    end
    GM.lastFloor, GM.lastFuel, GM.lastPower, GM.lastOn = fl, a:getFuel(), GM.power(a), a:isActivated()
end

-- The minute watcher: the first minute event of each new hour notes whether
-- the step had been taken already (A's fuel against the last minute event,
-- read only while no refill runs) and the tick count and millisecond it ran
-- at, against the tick watcher's. The per-minute refill.
function RT.GM.onMinute()
    local GM = RT.GM
    local a = GM.a
    if a == nil or not GM.watching then return end
    GM.minutes = GM.minutes + 1
    local age = hours()
    local fl = math.floor(age)
    local f = a:getFuel()
    local minute = math.floor((age - fl) * 60 + 1e-4)
    if GM.minuteFloor ~= nil and fl > GM.minuteFloor then
        GM.marks[#GM.marks + 1] = { age = age, tick = GM.tick or 0, ms = getTimestampMs(), minute = minute,
            clock = getGameTime():getMinutes(), dropped = GM.refill == nil and GM.minuteFuel ~= nil and f < GM.minuteFuel - 1e-9 }
    end
    if minute == 59 then GM.min59Hour = fl end
    if GM.refill == "minute" and a:isActivated() then
        local cap = GM.power(a) + GM.eps
        if f < cap - GM.eps / 2 then
            a:setFuel(cap)
            GM.refills = GM.refills + 1
        end
    end
    GM.minuteFloor, GM.minuteFuel = fl, a:getFuel()
end

function RT.GM.watch(on)
    local GM = RT.GM
    if on and not GM.hooked then
        Events.OnTick.Add(GM.onTick)
        Events.EveryOneMinute.Add(GM.onMinute)
        GM.hooked = true
    elseif not on and GM.hooked then
        Events.OnTick.Remove(GM.onTick)
        Events.EveryOneMinute.Remove(GM.onMinute)
        GM.hooked = false
    end
    GM.watching = on == true
end

function RT.GM.state(label)
    local GM = RT.GM
    local a = GM.a
    R:line("OBS  RTGM.%s at %.5f h (clock %02d:%02d): A fuel %.7f, running %s, load %.7f L an hour, setting %s " ..
        "(SandboxVars %s), powering %s; charger on %s", label, hours(), getGameTime():getHour(), getGameTime():getMinutes(),
        a and a:getFuel() or -1, tostring(a and a:isActivated()), a and GM.power(a) or -1,
        tostring(a and GM.setting(a)), tostring(SandboxVars.GeneratorFuelConsumption), a and GM.powered(a) or "-",
        tostring(GM.charger and GM.charger:isActivated()))
end

RT.GM.setup = { name = "rtgm_setup", timeout = 1200, fn = function(ctx, ticks)
    local GM = RT.GM
    if not ctx.t0 then
        local p = player()
        p:setGodMod(true)
        p:setInvisible(true)
        RT.keepFit()
        ctx.t0 = ticks
        return nil
    end
    if ticks - ctx.t0 < 60 then return nil end
    if not ctx.placed then
        local spot
        for dy = 4, 16 do
            for dx = -12, 12 do
                local x, y = START.x + dx, START.y + dy
                if spot == nil and RT.MI.clear(x, y) and RT.MI.clear(x + 2, y) then spot = { x = x, y = y } end
            end
        end
        if spot == nil then
            RT.abort = "no clear squares for the generator and the charger"
            R:check("RTGM.placed", function() return false, "no clear squares near the start" end)
            return true
        end
        GM.spot = spot
        pcall(function() IsoGenerator.new(instanceItem("Base.Generator"), getCell(), sq(spot.x, spot.y, 0)) end)
        local s = sq(spot.x, spot.y, 0)
        GM.a = s and s:getGenerator() or nil
        pcall(function()
            local cs = sq(spot.x + 2, spot.y, 0)
            GM.charger = IsoCarBatteryCharger.new(instanceItem("Base.CarBatteryCharger"), getCell(), cs)
            cs:AddSpecialObject(GM.charger)
            GM.battery = instanceItem("Base.CarBattery1")
            GM.battery:setUsedDelta(0)
            GM.charger:setBattery(GM.battery)
        end)
        if GM.a then
            GM.a:setConnected(true)
            GM.a:setFuel(1.0)
            GM.a:setActivated(true)
        end
        GM.clear()
        GM.watch(true)
        ctx.placed = ticks
        return nil
    end
    if ticks - ctx.placed < 120 then return nil end
    GM.setting0 = GM.a and GM.setting(GM.a) or -1
    GM.chargerStep = 0.05 * GM.setting0
    GM.state("placed")
    R:line("OBS  RTGM.placed A at %d,%d and the charger at %d,%d; A max fuel %s L; AllowExteriorGenerator %s; the " ..
        "charger's battery %s", GM.spot.x, GM.spot.y, GM.spot.x + 2, GM.spot.y, tostring(GM.a and GM.a:getMaxFuel()),
        tostring(SandboxVars.AllowExteriorGenerator), tostring(GM.battery and GM.battery:getFullType()))
    R:check("RTGM.placed", function()
        return GM.a ~= nil and GM.a:isActivated() and GM.charger ~= nil and GM.setting0 > 0, string.format(
            "A %s running %s, charger %s, setting %s", tostring(GM.a ~= nil), tostring(GM.a and GM.a:isActivated()),
            tostring(GM.charger ~= nil), tostring(GM.setting0))
    end)
    if not (GM.a and GM.charger) then RT.abort = "the generator or the charger is missing" end
    return true
end }

-- 1. The charger's load, on and off.
RT.GM.chargerCheck = { name = "rtgm_charger", timeout = 1200, fn = function(ctx, ticks)
    local GM = RT.GM
    if RT.abort then return true end
    local a = GM.a
    if not ctx.p0 then
        GM.stage = "charger"
        ctx.p0, ctx.t = GM.power(a), ticks
        GM.charging(true)
        return nil
    end
    if not ctx.on then
        if GM.power(a) > ctx.p0 + GM.chargerStep / 2 or ticks - ctx.t > 120 then
            ctx.on, ctx.pOn, ctx.onTicks, ctx.t = true, GM.power(a), ticks - ctx.t, ticks
            ctx.cOn = GM.charger:isActivated()
            GM.charging(false)
        end
        return nil
    end
    if math.abs(GM.power(a) - ctx.p0) > 1e-7 and ticks - ctx.t <= 120 then return nil end
    local pOff, offTicks = GM.power(a), ticks - ctx.t
    local rise = ctx.pOn - ctx.p0
    R:line("OBS  RTGM.charger: load %.7f -> %.7f within %d ticks of switching on (charger on %s), %.7f within %d ticks " ..
        "of switching off; expected rise 0.05 x %s = %.7f", ctx.p0, ctx.pOn, ctx.onTicks, tostring(ctx.cOn), pOff, offTicks,
        tostring(GM.setting0), GM.chargerStep)
    local ok = math.abs(rise - GM.chargerStep) < 1e-6 and math.abs(pOff - ctx.p0) < 1e-7
    R:check("RTGM.charger_switches_the_load", function()
        return ok, string.format("rise %.7f (expected %.7f), back to %.7f from %.7f", rise, GM.chargerStep, pOff, ctx.p0)
    end)
    if not ok then RT.abort = "the charger did not change A's load as expected" end
    return true
end }

-- 2. Steps on A's own fuel.
RT.GM.steps = { name = "rtgm_steps", timeout = 60000, fn = function(ctx, ticks)
    local GM = RT.GM
    if RT.abort then return true end
    local a = GM.a
    if not ctx.started then
        GM.clear()
        GM.stage = "steps"
        a:setFuel(1.0)
        GM.lastFuel = a:getFuel()
        GM.state("steps_start")
        RT.speed(20)
        ctx.started = ticks
        return nil
    end
    if ticks % 30 == 0 then RT.keepFit() end
    -- Three boundaries, and the drop after the last one.
    if #GM.boundaries < 3 or #GM.drops < #GM.boundaries then return nil end
    RT.speed(1)
    GM.state("steps_end")
    local bad, atEdge, hrs = 0, 0, {}
    for _, d in ipairs(GM.drops) do
        if math.abs(d.drop - (d.before or -1)) > GM.tol then bad = bad + 1 end
        if d.age - math.floor(d.age) < 1 / 60 then atEdge = atEdge + 1 end
        hrs[#hrs + 1] = string.format("%.5f", d.age)
    end
    R:check("RTGM.step_is_the_load_read_before", function()
        return #GM.drops >= 3 and bad == 0 and atEdge == #GM.drops, string.format(
            "%d drops at world age %s; %d differ from the load read the tick before by more than %.0e; %d within the " ..
            "hour's first game minute", #GM.drops, table.concat(hrs, ", "), bad, GM.tol, atEdge)
    end)
    -- The order of the tick watcher, the minute event and the step.
    local parts, tickSaw, minuteSaw = {}, 0, 0
    for i, b in ipairs(GM.boundaries) do
        local m = GM.marks[i]
        if b.dropped then tickSaw = tickSaw + 1 end
        if m and m.dropped then minuteSaw = minuteSaw + 1 end
        parts[#parts + 1] = string.format("[boundary %.5f h tick %d: the tick watcher saw the step %s; first minute event " ..
            "of the hour at %s h (minute %s, clock minute %s) tick %s, saw the step %s, %s ms after the tick watcher]", b.age,
            b.tick, tostring(b.dropped), m and string.format("%.5f", m.age) or "-", m and tostring(m.minute) or "-",
            m and tostring(m.clock) or "-", m and tostring(m.tick) or "-", m and tostring(m.dropped) or "-",
            m and tostring(m.ms - b.ms) or "-")
    end
    R:line("OBS  RTGM.order: %s; drops seen %s ticks after the boundary", table.concat(parts, " "),
        table.concat((function()
            local t = {}
            for _, d in ipairs(GM.drops) do t[#t + 1] = tostring(d.ticks) end
            return t
        end)(), ","))
    GM.tickSawStep = tickSaw == #GM.boundaries
    GM.minuteSawStep = minuteSaw == #GM.boundaries
    R:check("RTGM.order_observed", function()
        return #GM.boundaries >= 3 and #GM.marks >= #GM.boundaries and (tickSaw == 0 or tickSaw == #GM.boundaries)
            and (minuteSaw == 0 or minuteSaw == #GM.boundaries), string.format(
            "%d boundaries, %d first minute events; the tick watcher saw the step at %d, the minute event at %d (the " ..
            "same answer at every boundary is required)", #GM.boundaries, #GM.marks, tickSaw, minuteSaw)
    end)
    return true
end }

-- 3. The charger on half way through an hour, off half way through the next.
RT.GM.midHour = { name = "rtgm_midhour", timeout = 60000, fn = function(ctx, ticks)
    local GM = RT.GM
    if RT.abort then return true end
    local a = GM.a
    if not ctx.started then
        GM.clear()
        GM.stage = "midhour"
        a:setFuel(1.0)
        GM.lastFuel = a:getFuel()
        ctx.started, ctx.h0 = ticks, math.floor(hours())
        GM.onStageTick = function(age, fl, f, p, on)
            if fl == ctx.h0 + 1 and not ctx.onAt and age - fl >= 0.5 then
                ctx.onAt, ctx.pBefore = age, p
                GM.charging(true)
            elseif fl == ctx.h0 + 1 and ctx.onAt and not ctx.pOn and p > ctx.pBefore + GM.chargerStep / 2 then
                ctx.pOn = p
            elseif fl == ctx.h0 + 2 and not ctx.offAt and age - fl >= 0.5 then
                ctx.offAt = age
                GM.charging(false)
            end
        end
        RT.speed(20)
        return nil
    end
    if ticks % 30 == 0 then RT.keepFit() end
    -- Ends once the tick watcher has recorded the step after switching off:
    -- this step runs before the watcher in a frame, so the hour alone is not
    -- enough (launch 345 ended in the boundary's frame and missed it).
    local dOn, dOff
    for _, d in ipairs(GM.drops) do
        if math.floor(d.age) == ctx.h0 + 2 then dOn = d end
        if math.floor(d.age) == ctx.h0 + 3 then dOff = d end
    end
    if not (ctx.offAt and dOff) and math.floor(hours()) < ctx.h0 + 5 then return nil end
    RT.speed(1)
    GM.onStageTick = nil
    R:line("OBS  RTGM.midhour: load %.7f before the charger came on at %.5f h, %.7f after; the step at the next " ..
        "boundary %s; the charger off at %.5f h, the step after %s", ctx.pBefore or -1, ctx.onAt or -1, ctx.pOn or -1,
        dOn and string.format("%.7f at %.5f h", dOn.drop, dOn.age) or "none", ctx.offAt or -1,
        dOff and string.format("%.7f at %.5f h", dOff.drop, dOff.age) or "none")
    R:check("RTGM.step_is_the_load_of_its_moment", function()
        return dOn ~= nil and dOff ~= nil and ctx.pOn ~= nil and math.abs(dOn.drop - ctx.pOn) < GM.tol
            and math.abs(ctx.pOn - ctx.pBefore - GM.chargerStep) < 1e-6 and math.abs(dOff.drop - ctx.pBefore) < GM.tol,
            string.format("after switching on: step %s, load %s (before %s); after switching off: step %s",
                dOn and string.format("%.7f", dOn.drop) or "none", tostring(ctx.pOn), tostring(ctx.pBefore),
                dOff and string.format("%.7f", dOff.drop) or "none")
    end)
    return true
end }

-- 4. Exactly one step left late in the hour, then one step + 1e-4.
RT.GM.exact = { name = "rtgm_exact", timeout = 60000, fn = function(ctx, ticks)
    local GM = RT.GM
    if RT.abort then return true end
    local a = GM.a
    if not ctx.started then
        GM.clear()
        GM.stage = "exact"
        GM.charging(false)
        a:setFuel(1.0)
        GM.lastFuel = a:getFuel()
        ctx.started, ctx.h0 = ticks, math.floor(hours())
        -- A's state is read 5 ticks after a boundary: the step may show in
        -- the tick after the one that first sees the new hour.
        GM.onStageTick = function(age, fl, f, p, on)
            local late = age - fl >= 59.5 / 60
            local since = GM.boundary and (GM.tick - GM.boundary.tick) or 0
            if fl == ctx.h0 + 1 and late and not ctx.setA then
                a:setFuel(p)
                ctx.setA, ctx.stepA = a:getFuel(), p
            elseif fl == ctx.h0 + 2 and ctx.setA and not ctx.offA and since >= 5 then
                ctx.offA = { fuel = f, on = on }
                a:setFuel(1.0)
                a:setActivated(true)
            elseif fl == ctx.h0 + 2 and ctx.offA and late and not ctx.setB then
                a:setFuel(p + GM.eps)
                ctx.setB, ctx.stepB = a:getFuel(), p
            elseif fl == ctx.h0 + 3 and ctx.setB and not ctx.afterB and since >= 5 then
                ctx.afterB = { fuel = f, on = on }
            end
        end
        RT.speed(20)
        return nil
    end
    if ticks % 30 == 0 then RT.keepFit() end
    if not ctx.afterB then return nil end
    RT.speed(1)
    GM.onStageTick = nil
    R:line("OBS  RTGM.exact: fuel set to %s against a step of %s late in hour %d; after the boundary fuel %s, running " ..
        "%s. Then %s against a step of %s; after the boundary fuel %.9f, running %s", tostring(ctx.setA), tostring(ctx.stepA),
        ctx.h0 + 1, tostring(ctx.offA and ctx.offA.fuel), tostring(ctx.offA and ctx.offA.on), tostring(ctx.setB),
        tostring(ctx.stepB), ctx.afterB.fuel, tostring(ctx.afterB.on))
    R:check("RTGM.exactly_one_step_switches_off", function()
        return ctx.setA ~= nil and ctx.setA == ctx.stepA and ctx.offA ~= nil and ctx.offA.fuel == 0 and ctx.offA.on == false,
            string.format("set %s for a step of %s; after: fuel %s running %s", tostring(ctx.setA), tostring(ctx.stepA),
                tostring(ctx.offA and ctx.offA.fuel), tostring(ctx.offA and ctx.offA.on))
    end)
    R:check("RTGM.one_step_and_a_margin_runs_on", function()
        return ctx.setB ~= nil and ctx.afterB.on == true and math.abs(ctx.afterB.fuel - GM.eps) < 1e-6, string.format(
            "after the step: fuel %.9f (margin %.0e), running %s", ctx.afterB.fuel, GM.eps, tostring(ctx.afterB.on))
    end)
    return true
end }

-- 5. A refill policy against late switch-ons, over `want` counted attempts
-- and at least 3 boundaries (at most 8). An attempt counts when the load
-- rose before the boundary while the buffer was short of the new step, so
-- that a refill had to land between the rise and the burn. At speed 100 a
-- game minute is about 1.5 ticks, so few switch-ons can count there: it
-- wants none.
function RT.GM.policy(mode, speed, want)
    return { name = "rtgm_policy_" .. mode .. "_x" .. speed, timeout = 120000, fn = function(ctx, ticks)
        local GM = RT.GM
        if RT.abort then return true end
        local a = GM.a
        local label = "policy_" .. mode .. "_x" .. speed
        if not ctx.started then
            GM.clear()
            GM.stage = label
            GM.charging(false)
            if not a:isActivated() then a:setActivated(true) end
            ctx.started = ticks
            return nil
        end
        -- The buffer is sized once the charger's going off has reached the
        -- load (the server's launch 347 sized it from the load before).
        if not ctx.sized then
            if ticks - ctx.started < 10 then return nil end
            a:setFuel(GM.power(a) + GM.eps)
            GM.lastFuel = a:getFuel()
            GM.refill, GM.late = mode, true
            ctx.sized, ctx.h0, ctx.m0 = ticks, hours(), GM.minutes
            RT.speed(speed)
            return nil
        end
        if ticks % 30 == 0 then RT.keepFit() end
        local counted, refilled = 0, 0
        for _, at in ipairs(GM.attempts) do
            if at.rose and at.short and at.boundary then
                counted = counted + 1
                if at.refilledBetween then refilled = refilled + 1 end
            end
        end
        -- A stop needs restarting, or the next attempts measure nothing.
        if not a:isActivated() then
            ctx.off = (ctx.off or 0) + 1
            if ctx.off > 5 then
                a:setActivated(true)
                a:setFuel(GM.power(a) + GM.eps)
                GM.lastFuel = a:getFuel()
                ctx.off = 0
            end
        else
            ctx.off = 0
        end
        if (counted < want or #GM.boundaries < 3) and #GM.boundaries < 8 then return nil end
        if GM.lastAttempt and GM.lastAttempt.boundary and GM.tick - GM.lastAttempt.boundary.tick <= 6 then return nil end
        GM.refill, GM.late = nil, false
        GM.charging(false)
        RT.speed(1)
        local gone = hours() - ctx.h0
        local stoppedCounted, parts = 0, {}
        for _, at in ipairs(GM.attempts) do
            if at.rose and at.short and at.boundary and at.stopped then stoppedCounted = stoppedCounted + 1 end
            parts[#parts + 1] = string.format("[hour %d: on at %.5f h, load rose %s%s, fuel then %s (short of the step %s), " ..
                "boundary %s, a refill between %s, stopped %s]", at.hour, at.at, tostring(at.rose),
                at.roseAt and string.format(" at %.5f h", at.roseAt) or "",
                at.fuelAtRise and string.format("%.7f", at.fuelAtRise) or "-", tostring(at.short == true),
                at.boundary and string.format("%.5f h", at.boundary.age) or "-", tostring(at.refilledBetween == true),
                tostring(at.stopped == true))
        end
        R:line("OBS  RTGM.%s: %.3f game h, %d minute events (%.1f an hour), %d boundaries, %d refills, %d trims, %d stops, " ..
            "%d ticks not running; attempts %s", label, gone, GM.minutes - ctx.m0,
            (GM.minutes - ctx.m0) / math.max(gone, 1e-9), #GM.boundaries, GM.refills, GM.trims, GM.stops, GM.offTicks,
            table.concat(parts, " "))
        if mode == "tick" then
            R:check("RTGM." .. label .. "_runs_through", function()
                return counted >= want and refilled == counted and GM.stops == 0 and #GM.boundaries >= 3, string.format(
                    "%d counted attempts (of %d), a refill between the rise and the burn at %d, %d stops, %d boundaries",
                    counted, #GM.attempts, refilled, GM.stops, #GM.boundaries)
            end)
        else
            -- What the minute refill must do follows from stage 2's order: a
            -- minute event before the step refills for the new load.
            local expectStops = GM.minuteSawStep == true
            R:check("RTGM." .. label .. "_as_the_order_says", function()
                return counted >= want and GM.minuteSawStep ~= nil and ((expectStops and stoppedCounted > 0)
                    or (not expectStops and GM.stops == 0 and refilled == counted)), string.format(
                    "%d counted attempts, a refill between the rise and the burn at %d, %d of them stopped A, %d stops " ..
                    "in all; the first minute event of the hour saw the step already: %s", counted, refilled,
                    stoppedCounted, GM.stops, tostring(GM.minuteSawStep))
            end)
        end
        return true
    end }
end

-- 6. A propane tank item given a number of uses in the inventory.
RT.GM.tankItem = { name = "rtgm_tank_item", timeout = 600, fn = function(ctx, ticks)
    local t = instanceItem("Base.PropaneTank")
    local inv = player():getInventory()
    inv:AddItem(t)
    local function uses() return t:getCurrentUsesFloat() / t:getUseDelta() end
    local reads = {}
    for _, n in ipairs({ 1234, 1234.5, 1 }) do
        t:setUsedDelta(n * t:getUseDelta())
        reads[#reads + 1] = { n = n, uses = uses(), whole = t:getCurrentUses() }
    end
    local parts = {}
    for _, r in ipairs(reads) do
        parts[#parts + 1] = string.format("%s -> %.4f (getCurrentUses %s)", tostring(r.n), r.uses, tostring(r.whole))
    end
    R:line("OBS  RTGM.tank_item: useDelta %s; %s", tostring(t:getUseDelta()), table.concat(parts, "; "))
    R:check("RTGM.tank_item_keeps_whole_uses", function()
        return math.abs(reads[1].uses - 1234) < 1e-3 and reads[1].whole == 1234 and math.abs(reads[3].uses - 1) < 1e-3
            and reads[3].whole == 1, table.concat(parts, "; ")
    end)
    inv:Remove(t)
    return true
end }

RT.GM.done = { name = "rtgm_done", fn = function()
    local GM = RT.GM
    GM.watch(false)
    GM.refill, GM.late = nil, false
    if GM.a then GM.state("end") end
    RT.speed(1)
    return true
end }

RT.gasMeasureSteps = { RT.waitWorld, RT.GM.setup, RT.GM.chargerCheck, RT.GM.steps, RT.GM.midHour, RT.GM.exact,
    RT.GM.policy("tick", 20, 3), RT.GM.policy("minute", 20, 3), RT.GM.policy("tick", 100, 0), RT.GM.tankItem, RT.GM.done,
    RT.finish }

------------------------------------------------------------------------------
-- Gas and sleep (request "sp-rtgs"; D-040: "sleep, the commonest way a
-- player crosses hours beside a generator, to be run before 0.5.0 ships").
-- A wood-gas generator holds one hourly step and a margin, so one boundary
-- whose burn comes before the minute pass's refill stops it; propane's 10 L
-- hide that. RT.GM's generator A (setup and watchers), its charger off. The
-- character is put to sleep as the game's bed menu does it (SRC
-- ISWorldObjectContextMenu.onSleepWalkToComplete), without its save.
--   1. Eight hours asleep on A's own fuel (1 L): at each boundary, whether
--      the hour's first minute event saw the step already; the minute
--      events an hour; the most game minutes and hours one tick crossed.
--   2. Eight hours more, A refilled on each minute event to one step and
--      1e-3 L (GasFeed.MARGIN): A must run through every boundary.
------------------------------------------------------------------------------
RT.GS = { margin = 1e-3, hours = 8 }

function RT.GS.sleep(label, refill)
    return { name = "rtgs_" .. label, timeout = 240000, fn = function(ctx, ticks)
        local GM, GS = RT.GM, RT.GS
        if RT.abort then return true end
        local a, p = GM.a, player()
        if not ctx.started then
            GM.clear()
            GM.stage = "sleep_" .. label
            GM.charging(false)
            if not a:isActivated() then a:setActivated(true) end
            GM.eps = GS.margin
            if refill then a:setFuel(GM.power(a) + GM.eps) else a:setFuel(1.0) end
            GM.lastFuel = a:getFuel()
            GM.refill = refill
            ctx.started, ctx.h0, ctx.m0 = ticks, hours(), GM.minutes
            ctx.maxMin, ctx.maxHours, ctx.lastMin, ctx.lastAge, ctx.asleep = 0, 0, GM.minutes, hours(), 0
            GM.onStageTick = function(age)
                local m = GM.minutes - ctx.lastMin
                if m > ctx.maxMin then ctx.maxMin = m end
                local dh = math.floor(age) - math.floor(ctx.lastAge)
                if dh > ctx.maxHours then ctx.maxHours = dh end
                ctx.lastMin, ctx.lastAge = GM.minutes, age
                if p:isAsleep() then ctx.asleep = ctx.asleep + 1 end
            end
            pcall(function() p:getStats():set(CharacterStat.FATIGUE, 0.9) end)
            local wake = (getGameTime():getTimeOfDay() + GS.hours) % 24
            p:setForceWakeUpTime(wake)
            p:setAsleepTime(0.0)
            p:setAsleep(true)
            getSleepingEvent():setPlayerFallAsleep(p, GS.hours)
            pcall(function()
                UIManager.setFadeBeforeUI(p:getPlayerNum(), true)
                UIManager.FadeOut(p:getPlayerNum(), 1)
            end)
            if IsoPlayer.allPlayersAsleep() then pcall(function() UIManager.getSpeedControls():SetCurrentGameSpeed(3) end) end
            ctx.wake = wake
            R:line("OBS  RTGS.%s asleep at %.5f h (clock %02d:%02d), to wake at %.2f; A fuel %.7f, load %.7f, refill %s",
                label, hours(), getGameTime():getHour(), getGameTime():getMinutes(), wake, a:getFuel(), GM.power(a),
                tostring(refill))
            return nil
        end
        if p:isAsleep() and hours() - ctx.h0 < 24 then return nil end
        -- Awake: a few ticks more, so the tick watcher records the last step.
        if not ctx.awake then
            ctx.awake = ticks
            return nil
        end
        if ticks - ctx.awake < 30 then return nil end
        GM.onStageTick, GM.refill = nil, nil
        pcall(function() UIManager.FadeIn(p:getPlayerNum(), 1) end)
        local gone = hours() - ctx.h0
        local minutes = GM.minutes - ctx.m0
        local saw, parts = 0, {}
        for i, b in ipairs(GM.boundaries) do
            local m = GM.marks[i]
            if m and m.dropped then saw = saw + 1 end
            parts[#parts + 1] = string.format("[%.5f h tick %d, first minute event %s, saw the step %s]", b.age, b.tick,
                m and string.format("%.5f h tick %s", m.age, tostring(m.tick)) or "-", m and tostring(m.dropped) or "-")
        end
        R:line("OBS  RTGS.%s awake at %.5f h after %.3f game h (%d ticks asleep): %d boundaries, %d minute events " ..
            "(%.1f an hour), at most %d minutes and %d hours in one tick, %d steps, %d refills, %d stops, %d ticks not " ..
            "running; A fuel %.7f, running %s; boundaries %s", label, hours(), gone, ctx.asleep, #GM.boundaries, minutes,
            minutes / math.max(gone, 1e-9), ctx.maxMin, ctx.maxHours, #GM.drops, GM.refills, GM.stops, GM.offTicks,
            a:getFuel(), tostring(a:isActivated()), table.concat(parts, " "))
        R:check("RTGS." .. label .. "_slept_through", function()
            return gone >= GS.hours - 0.5 and #GM.boundaries >= GS.hours - 1, string.format(
                "%.3f game h asleep, %d boundaries", gone, #GM.boundaries)
        end)
        if refill then
            R:check("RTGS.minute_refill_runs_through_sleep", function()
                return GM.stops == 0 and a:isActivated() and GM.refills >= #GM.boundaries, string.format(
                    "%d stops, %d refills for %d boundaries, running %s", GM.stops, GM.refills, #GM.boundaries,
                    tostring(a:isActivated()))
            end)
        else
            R:check("RTGS.minute_event_before_the_burn_in_sleep", function()
                return #GM.boundaries > 0 and saw == 0 and ctx.maxHours <= 1, string.format(
                    "the hour's first minute event saw the step at %d of %d boundaries; at most %d hours in one tick",
                    saw, #GM.boundaries, ctx.maxHours)
            end)
        end
        GM.eps = 1e-4
        RT.speed(1)
        return true
    end }
end

RT.gasSleepSteps = { RT.waitWorld, RT.GM.setup, RT.GS.sleep("own_fuel", nil), RT.GS.sleep("refill", "minute"),
    RT.GM.done, RT.finish }

------------------------------------------------------------------------------
-- Gas generator on propane (requests "sp-rtpr", then "sp-rtprb"; D-040). A
-- vanilla generator, A, converted to gas by the conversion service's own
-- steps (begun, every part handed over, worked to Commissioned by an actor
-- that has what the definition asks; the player's part in a conversion is
-- the full run's), then fed from propane tanks through the mod's Gas menu,
-- at the default generator fuel setting:
--   phase A  the Gas menu; a tank connected from the inventory; started with
--            the game's own action through the start gate; hours run, with
--            the propane taken from the tank against the hourly steps seen;
--            the game's Add fuel, the mod's pour and the Fuel menu refused;
--            taken up and put down with the tank in; a trip that unloads its
--            chunk; saved.
--   phase B  the save continued: the record as saved, refills going on; the
--            tank removed (with the propane not burned, less at most a use)
--            and A running dry; a tank of 3 uses burned to empty and given
--            back empty; a tank connected again, then Remove the conversion
--            from the Workshop menu: the tank back, the buffer let out, the
--            record gone, the stock profile, half the parts.
------------------------------------------------------------------------------
RT.PR = { hours = 4, tripHours = 3 }

local function prGen()
    local s = RT.PR.spot and sq(RT.PR.spot.x, RT.PR.spot.y, 0)
    return s and s:getGenerator() or nil
end

local function prRecord(g)
    g = g or prGen()
    return g and g:getModData()[TLG.Integration.Generators.GAS_KEY] or nil
end

local function prTanks()
    local out = {}
    local list = player():getInventory():getAllTypeRecurse("Base.PropaneTank")
    for i = 0, list:size() - 1 do out[#out + 1] = list:get(i) end
    return out
end

local function prUses(it) return math.floor(it:getCurrentUsesFloat() / it:getUseDelta() + 0.5) end

function RT.PR.state(label)
    local g = prGen()
    local rec = prRecord(g)
    local GasFeed = TLG.Domain.GasFeed
    local cur = rec and g and GasFeed.current(rec, g:getFuel()) or {}
    R:line("OBS  RTPR.%s at %.4f h: A %s fuel %.6f running %s load %.6f profile %s; record: tank %s uses, buffer %.6f Nm3 " ..
        "propane, written at %.6f L; tanks carried %s", label, hours(), tostring(g ~= nil), g and g:getFuel() or -1,
        tostring(g and g:isActivated()), g and RT.GM.power(g) or -1, tostring(g and TLG.Integration.Generators.profile(g)),
        tostring(rec and rec.tank and rec.tank.uses), cur.propane or 0, rec and rec.fuel or -1,
        (function()
            local t = {}
            for _, it in ipairs(prTanks()) do t[#t + 1] = tostring(prUses(it)) end
            return "[" .. table.concat(t, ",") .. "]"
        end)())
end

local function prMenu(label, key, g)
    return menuClick(label, function(c) TLG.UI.GasMenu.fill(0, c, { g or prGen() }, false) end,
        getText("ContextMenu_TLG_Gas"), getText(key))
end

-- The propane that left the tanks and is not in the buffer: what burned,
-- as petrol-equivalent litres, since the tank of `uses` went in.
local function prBurnedLitres(uses, g)
    local rec = prRecord(g)
    local Gas, GasFeed = TLG.Domain.Gas, TLG.Domain.GasFeed
    local left = (rec and rec.tank and rec.tank.uses or 0) * Gas.NM3_PER_USE
        + (GasFeed.current(rec or { buf = {} }, (g or prGen()):getFuel()).propane or 0)
    return GasFeed.propaneLitres(uses * Gas.NM3_PER_USE - left)
end

-- The hourly steps seen on A (each a drop of its fuel between two ticks).
function RT.PR.watch(on)
    local PR = RT.PR
    if on and not PR.hooked then
        PR.steps, PR.stepLitres, PR.lastFuel, PR.stops = 0, 0, nil, 0
        PR.tick = function()
            local g = prGen()
            if g == nil then return end
            local f = g:getFuel()
            if PR.lastFuel and f < PR.lastFuel - 1e-7 then
                PR.steps, PR.stepLitres = PR.steps + 1, PR.stepLitres + (PR.lastFuel - f)
            end
            if PR.wasOn and not g:isActivated() then PR.stops = PR.stops + 1 end
            PR.lastFuel, PR.wasOn = f, g:isActivated()
        end
        Events.OnTick.Add(PR.tick)
        PR.hooked = true
    elseif not on and PR.hooked then
        Events.OnTick.Remove(PR.tick)
        PR.hooked = false
    end
end

-- The gas conversion made the way the conversion service makes it.
function RT.PR.commission(g)
    local CS, CD, World = TLG.Domain.ConversionService, TLG.Integration.ConversionDevices, TLG.World
    local def = TLG.Registry.need("conversion", "gas_generator")
    local actor = { id = "harness", skills = { Mechanics = 10, Electricity = 10, MetalWelding = 10 }, recipes = {},
        inventory = {} }
    for _, r in ipairs(def.requiredKnowledge.recipes or {}) do actor.recipes[r] = true end
    for _, list in pairs(def.requiredTools or {}) do
        for _, id in ipairs(list) do actor.inventory[id] = 1 end
    end
    for _, mods in pairs(def.requiredModules or {}) do
        for id, n in pairs(mods) do actor.inventory[id] = (actor.inventory[id] or 0) + n end
    end
    local device = CD.describeGenerator(g, false)
    local now = World.now()
    local steps = {}
    local p = CS.new({ id = World.newId("C"), conversion = "gas_generator", t = now })
    local function go(name, r)
        steps[#steps + 1] = name .. "=" .. tostring(r and r.ok) .. (r and r.reason and ("/" .. r.reason) or "")
        if r and r.ok then p = r.project end
    end
    go("begin", CS.begin(p, actor, device, { now = now }))
    go("deliver", CS.deliver(p, actor, device, { now = now }))
    go("join", CS.join(p, actor, device, { now = now, workerTimeoutHours = 24 }))
    go("work", CS.work(p, actor, device, { now = now + 12, workerTimeoutHours = 24 }))
    -- The work is finished 12 hours ahead (a world this young has no 9 hours
    -- behind it); its commit time is set back to now, or a request before
    -- then is refused as time_regression (MP launch 354; launch 352's
    -- removal came after it).
    if p.t and p.t > now then p.t = now end
    if p.commissionedAt and p.commissionedAt > now then p.commissionedAt = now end
    CD.store(g:getModData(), g, p, TLG.Integration.Generators.keyOf(g))
    return p.state, table.concat(steps, " ")
end

RT.PR.setup = { name = "rtpr_setup", timeout = 1200, fn = function(ctx, ticks)
    local PR = RT.PR
    if not ctx.t0 then
        local p = player()
        p:setGodMod(true)
        p:setInvisible(true)
        captureDialogs(true)
        RT.keepFit()
        ctx.t0 = ticks
        return nil
    end
    if ticks - ctx.t0 < 60 then return nil end
    if not ctx.placed then
        local spot
        for dy = 4, 16 do
            for dx = -12, 12 do
                local x, y = START.x + dx, START.y + dy
                if spot == nil and RT.MI.clear(x, y) and RT.MI.clear(x + 1, y) and RT.MI.clear(x + 1, y + 1) then
                    spot = { x = x, y = y }
                end
            end
        end
        if spot == nil then
            RT.abort = "no clear squares for the generator"
            R:check("RTPR.placed", function() return false, "no clear squares near the start" end)
            return true
        end
        PR.spot = spot
        pcall(function() IsoGenerator.new(instanceItem("Base.Generator"), getCell(), sq(spot.x, spot.y, 0)) end)
        local g = prGen()
        if g then
            g:setConnected(true)
            g:setFuel(0)
            PR.convState, PR.convSteps = PR.commission(g)
        end
        player():teleportTo(spot.x + 1, spot.y + 1, 0)
        ctx.placed = ticks
        return nil
    end
    if ticks - ctx.placed < 60 then return nil end
    local g = prGen()
    local G = TLG.Integration.Generators
    R:line("OBS  RTPR.placed A at %d,%d: conversion %s (%s); setting %s", PR.spot.x, PR.spot.y, tostring(PR.convState),
        tostring(PR.convSteps), tostring(g and RT.GM.setting(g)))
    R:check("RTPR.converted_to_gas", function()
        return g ~= nil and PR.convState == "Commissioned" and G.isGas(g) and G.profile(g) == "generator_gas",
            string.format("A %s, project %s, profile %s", tostring(g ~= nil), tostring(PR.convState),
                tostring(g and G.profile(g)))
    end)
    if not (g and G.isGas(g)) then RT.abort = "A is not a gas generator" end
    return true
end }

-- The Gas menu, then a full tank connected from the inventory through it.
RT.PR.connect = { name = "rtpr_connect", timeout = 600, fn = function(ctx, ticks)
    local PR = RT.PR
    if RT.abort then return true end
    local g = prGen()
    local before = prMenu("RTPR.connect_without_a_tank", "ContextMenu_TLG_GasConnectTank", g)
    local tank = player():getInventory():AddItem("Base.PropaneTank")
    tank:setUsedDelta(1.0)
    PR.uses0 = prUses(tank)
    local r = prMenu("RTPR.connect", "ContextMenu_TLG_GasConnectTank", g)
    PR.state("connected")
    local rec = prRecord(g)
    R:check("RTPR.connect_greyed_without_a_tank", function()
        return before.reason == "entry_disabled", "without a tank: " .. tostring(before.reason)
    end)
    R:check("RTPR.tank_connected_and_buffer_filled", function()
        return r.ok == true and r.uses == 5000 and r.moved == 3840 and #prTanks() == 0 and rec ~= nil and rec.tank ~= nil
            and rec.tank.uses == 1160 and math.abs(g:getFuel() - 3840 * TLG.Domain.Gas.NM3_PER_USE * 93 / 32) < 1e-5,
            string.format("reply ok=%s uses=%s moved=%s from=%s; tanks carried %d; record tank %s; fuel %.6f",
                tostring(r.ok), tostring(r.uses), tostring(r.moved), tostring(r.from), #prTanks(),
                tostring(rec and rec.tank and rec.tank.uses), g:getFuel())
    end)
    return true
end }

-- Started with the game's own action: the start gate reads the gas record.
RT.PR.start = actionStep("rtpr_start", function(ctx)
    if RT.abort then return nil end
    player():teleportTo(RT.PR.spot.x + 1, RT.PR.spot.y, 0)
    return ISActivateGenerator:new(player(), prGen(), true)
end, function(ctx)
    local g = prGen()
    local e = TLG.Integration.Generators.evaluate(g)
    R:check("RTPR.started_on_propane", function()
        return g:isActivated() and e.compatible == true and e.grade == "good", string.format(
            "running %s; evaluation compatible %s grade %s reasons %s", tostring(g:isActivated()), tostring(e.compatible),
            tostring(e.grade), table.concat(e.reasons or {}, ","))
    end)
end)

-- Hours at speed 20: A runs on its buffer, refilled each minute from the tank.
RT.PR.run = { name = "rtpr_run", timeout = 60000, fn = function(ctx, ticks)
    local PR = RT.PR
    if RT.abort then return true end
    if not ctx.h0 then
        -- What burned before the watcher starts is not its to count.
        ctx.h0, ctx.b0 = hours(), prBurnedLitres(PR.uses0, prGen())
        PR.watch(true)
        RT.speed(20)
        return nil
    end
    if ticks % 30 == 0 then RT.keepFit() end
    if hours() - ctx.h0 < PR.hours then return nil end
    RT.speed(1)
    PR.watch(false)
    local g = prGen()
    local burned = prBurnedLitres(PR.uses0, g) - ctx.b0
    PR.state("after_hours")
    R:line("OBS  RTPR.run: %.3f game h, %d steps of %.6f L in all; the propane gone from tank and buffer is worth %.6f L; " ..
        "%d stops", hours() - ctx.h0, PR.steps, PR.stepLitres, burned, PR.stops)
    R:check("RTPR.ran_on_the_tank", function()
        return g:isActivated() and PR.stops == 0 and PR.steps >= PR.hours - 1 and math.abs(burned - PR.stepLitres) < 1e-4,
            string.format("running %s, %d stops, %d steps; burned by the record %.6f L against %.6f L of steps",
                tostring(g:isActivated()), PR.stops, PR.steps, burned, PR.stepLitres)
    end)
    return true
end }

-- The game's Add fuel, the mod's pour and the Fuel menu: no liquid goes in.
RT.PR.refusals = actionStep("rtpr_add_fuel", function(ctx)
    if RT.abort then return nil end
    local g = prGen()
    ctx.can = giveCan("Base.PetrolCan", { { Fluid.Petrol, 4.0 } })
    ctx.fuel, ctx.canL = g:getFuel(), ctx.can:getFluidContainer():getAmount()
    return ISAddFuel:new(player(), g, ctx.can, 100)
end, function(ctx)
    local g = prGen()
    local pour = ask("RTPR.pour", "transfer", { source = TLG.Authority.Resolver.refForItem(ctx.can),
        destination = TLG.Authority.Resolver.refForObject(g, "generator"), amount = 2 })
    local c = ISContextMenu.get(0, 100, 100)
    TLG.UI.FuelMenu.addPourOptions(player(), c, ctx.can)
    local offered = c:getOptionFromName(getText("ContextMenu_TLG_PourGenerator")) ~= nil
    c:setVisible(false)
    R:check("RTPR.no_liquid_goes_in", function()
        return math.abs(g:getFuel() - ctx.fuel) < 1e-6 and math.abs(ctx.can:getFluidContainer():getAmount() - ctx.canL) < 1e-6
            and pour.ok == false and pour.reason == "gas_generator" and not offered, string.format(
            "after Add fuel: A %.6f (was %.6f), can %.3f (was %.3f); the pour: ok=%s reason=%s; Pour into the generator " ..
            "offered %s", g:getFuel(), ctx.fuel, ctx.can:getFluidContainer():getAmount(), ctx.canL, tostring(pour.ok),
            tostring(pour.reason), tostring(offered))
    end)
    player():getInventory():Remove(ctx.can)
end)

-- Taken up with the tank in (switched off and unplugged first, as the game
-- asks: SRC ISTakeGenerator.isValid) and put down again: the record travels
-- in the item and comes back.
RT.PR.take = actionStep("rtpr_take", function(ctx)
    if RT.abort then return nil end
    local g = prGen()
    g:setActivated(false)
    g:setConnected(false)
    ctx.rec = TLG.Tables.deepCopy(prRecord(g))
    ctx.fuel = g:getFuel()
    player():setPrimaryHandItem(nil)
    player():setSecondaryHandItem(nil)
    player():teleportTo(RT.PR.spot.x + 1, RT.PR.spot.y, 0)
    return ISTakeGenerator:new(player(), g)
end, function(ctx)
    local it = player():getPrimaryHandItem()
    RT.PR.item = it
    local side = it and it:getModData().tlg
    local carried = side and side[TLG.Integration.Generators.GAS_KEY]
    local liquid = 0
    for _, q in pairs(side and side.q or {}) do liquid = liquid + q end
    R:check("RTPR.taken_up_with_its_record", function()
        return carried ~= nil and ctx.rec ~= nil and carried.tank and carried.tank.uses == ctx.rec.tank.uses
            and liquid == 0 and math.abs((tonumber(it:getModData().fuel) or -1) - ctx.fuel) < 1e-4, string.format(
            "item %s; carried record tank %s (was %s); liquid record %.4f L; item fuel %s (was %.6f)",
            tostring(it and it:getFullType()), tostring(carried and carried.tank and carried.tank.uses),
            tostring(ctx.rec and ctx.rec.tank and ctx.rec.tank.uses), liquid, tostring(it and it:getModData().fuel), ctx.fuel)
    end)
end)

RT.PR.put = actionStep("rtpr_put", function(ctx)
    if RT.abort or RT.PR.item == nil then return nil end
    return ISDropWorldItemAction:new(player(), RT.PR.item, sq(RT.PR.spot.x, RT.PR.spot.y, 0), 0.5, 0.5, 0, 0, false)
end, function(ctx)
    local g = prGen()
    local G = TLG.Integration.Generators
    local rec = prRecord(g)
    local key = RT.PR.spot.x .. "," .. RT.PR.spot.y .. ",0"
    R:check("RTPR.put_down_with_its_record", function()
        return g ~= nil and rec ~= nil and rec.tank ~= nil and G.holdsGas(g) and G.gasSquares[key] == true, string.format(
            "A %s; record tank %s; holds gas %s; watched %s", tostring(g ~= nil), tostring(rec and rec.tank and rec.tank.uses),
            tostring(g and G.holdsGas(g)), tostring(G.gasSquares[key]))
    end)
end)

RT.PR.restart = actionStep("rtpr_restart", function(ctx)
    if RT.abort then return nil end
    player():teleportTo(RT.PR.spot.x + 1, RT.PR.spot.y, 0)
    prGen():setConnected(true)
    return ISActivateGenerator:new(player(), prGen(), true)
end, function(ctx)
    R:check("RTPR.started_again", function()
        return prGen():isActivated(), "running " .. tostring(prGen():isActivated())
    end)
end)

-- Away for three hours: the chunk unloads, the game burns the hours on
-- return, and the minute pass takes up again.
RT.PR.trip = { name = "rtpr_trip", timeout = 30000, fn = function(ctx, ticks)
    local PR = RT.PR
    if RT.abort then return true end
    if not ctx.at then
        ctx.rec = TLG.Tables.deepCopy(prRecord())
        PR.state("leaving")
        player():teleportTo(PR.spot.x, PR.spot.y - RT.away, 0)
        ctx.at = ticks
        return nil
    end
    if not ctx.from then
        if ticks - ctx.at < 120 then return nil end
        ctx.from = hours()
        RT.speed(RT.waitSpeed)
        return nil
    end
    if ticks % 30 == 0 then RT.keepFit() end
    if not ctx.back then
        if sq(PR.spot.x, PR.spot.y, 0) == nil then ctx.unloaded = true end
        if hours() - ctx.from < PR.tripHours then return nil end
        RT.speed(1)
        player():teleportTo(PR.spot.x + 1, PR.spot.y + 1, 0)
        ctx.back = ticks
        return nil
    end
    -- An hour's boundary and a refill after it.
    if not ctx.settle then
        if ticks - ctx.back < 180 then return nil end
        ctx.settle, ctx.h = ticks, hours()
        RT.speed(20)
        return nil
    end
    if hours() - ctx.h < 1.05 then return nil end
    RT.speed(1)
    local g, rec = prGen(), prRecord()
    PR.state("back")
    R:check("RTPR.trip_unloaded_and_refilled_after", function()
        return ctx.unloaded == true and g ~= nil and g:isActivated() and rec ~= nil and ctx.rec ~= nil
            and rec.tank.uses < ctx.rec.tank.uses, string.format("unloaded %s; running %s; tank %s uses (was %s)",
            tostring(ctx.unloaded == true), tostring(g and g:isActivated()), tostring(rec and rec.tank.uses),
            tostring(ctx.rec and ctx.rec.tank.uses))
    end)
    return true
end }

RT.PR.beforeSave = { name = "rtpr_before_save", fn = function()
    local g = prGen()
    RT.speed(1)
    if RT.abort or g == nil then return true end
    local rec = prRecord(g)
    TLGH.writeFile("TLG_harness_expect.txt", { "pr.x=" .. RT.PR.spot.x, "pr.y=" .. RT.PR.spot.y,
        "pr.uses=" .. tostring(rec.tank.uses), "pr.fuel=" .. string.format("%.6f", g:getFuel()),
        "pr.recfuel=" .. string.format("%.6f", rec.fuel), "pr.id=" .. tostring(rec.id), "pr.h=" .. string.format("%.6f", hours()) })
    RT.PR.state("saving")
    return true
end }

RT.gasPropaneSteps = { RT.waitWorld, RT.PR.setup, RT.PR.connect, RT.PR.start, RT.PR.run, RT.PR.refusals, RT.PR.take,
    RT.PR.put, RT.PR.restart, RT.PR.trip, RT.PR.beforeSave, RT.saveAndExitAs("rtpr_save_and_exit", "sp-rtprb") }

-- Phase B: the save continued.
RT.PR.reload = { name = "rtprb_reload", timeout = 3000, fn = function(ctx, ticks)
    if not (player() and ticks > 180) then return nil end
    local e = TLGH.readKeyValues("TLG_harness_expect.txt")
    RT.PR.spot = { x = tonumber(e["pr.x"]), y = tonumber(e["pr.y"]) }
    local p = player()
    p:setGodMod(true)
    p:setInvisible(true)
    captureDialogs(true)
    if not ctx.near then
        p:teleportTo(RT.PR.spot.x + 1, RT.PR.spot.y + 1, 0)
        ctx.near = ticks
        return nil
    end
    if ticks - ctx.near < 120 then return nil end
    local g, rec = prGen(), prRecord()
    local G = TLG.Integration.Generators
    RT.PR.state("continued")
    R:check("RTPRB.record_as_saved", function()
        return g ~= nil and rec ~= nil and tostring(rec.id) == e["pr.id"] and rec.tank ~= nil
            and rec.tank.uses <= tonumber(e["pr.uses"]) and G.holdsGas(g) and G.isGas(g)
            and G.gasSquares[RT.PR.spot.x .. "," .. RT.PR.spot.y .. ",0"] == true, string.format(
            "A %s; record %s (saved %s); tank %s (saved %s); holds gas %s; watched %s", tostring(g ~= nil),
            tostring(rec and rec.id), tostring(e["pr.id"]), tostring(rec and rec.tank and rec.tank.uses), tostring(e["pr.uses"]),
            tostring(g and G.holdsGas(g)), tostring(G.gasSquares[RT.PR.spot.x .. "," .. RT.PR.spot.y .. ",0"]))
    end)
    if g == nil or rec == nil then RT.abort = "A or its record is missing after the continue" end
    return true
end }

-- Refills go on after the continue.
RT.PR.after = { name = "rtprb_refills", timeout = 30000, fn = function(ctx, ticks)
    if RT.abort then return true end
    if not ctx.h then
        ctx.h, ctx.uses = hours(), prRecord().tank.uses
        RT.speed(20)
        return nil
    end
    if ticks % 30 == 0 then RT.keepFit() end
    if hours() - ctx.h < 2.05 then return nil end
    RT.speed(1)
    local g, rec = prGen(), prRecord()
    R:check("RTPRB.refills_go_on", function()
        return g:isActivated() and rec.tank.uses < ctx.uses, string.format("running %s; tank %d -> %d uses",
            tostring(g:isActivated()), ctx.uses, rec.tank.uses)
    end)
    return true
end }

-- Removed through the menu: the propane not burned goes back into the tank;
-- A runs on what is left in its buffer, then stops.
RT.PR.remove = { name = "rtprb_remove", timeout = 40000, fn = function(ctx, ticks)
    local PR = RT.PR
    if RT.abort then return true end
    if not ctx.r then
        local g, rec = prGen(), prRecord()
        local GasFeed, Gas = TLG.Domain.GasFeed, TLG.Domain.Gas
        ctx.expect = rec.tank.uses + (Gas.nm3ToUses(GasFeed.current(rec, g:getFuel()).propane or 0) or 0)
        ctx.r = prMenu("RTPRB.remove", "ContextMenu_TLG_GasRemoveTank", g)
        ctx.fuel, ctx.h = g:getFuel(), hours()
        PR.state("removed")
        RT.speed(20)
        return nil
    end
    if ticks % 30 == 0 then RT.keepFit() end
    local g = prGen()
    if g:isActivated() and hours() - ctx.h < 3 then return nil end
    RT.speed(1)
    local tanks = prTanks()
    local back = tanks[1] and prUses(tanks[1])
    R:check("RTPRB.tank_back_less_at_most_a_use", function()
        return ctx.r.ok == true and back ~= nil and back <= ctx.expect and back >= ctx.expect - 1 and ctx.r.uses == back
            and ctx.fuel < TLG.Domain.Gas.NM3_PER_USE * 93 / 32 + 1e-6, string.format(
            "reply ok=%s uses=%s; the tank carried holds %s (expected %s or one less); A left with %.6f L",
            tostring(ctx.r.ok), tostring(ctx.r.uses), tostring(back), tostring(ctx.expect), ctx.fuel)
    end)
    R:check("RTPRB.runs_dry_without_its_tank", function()
        return not g:isActivated() and g:getFuel() <= 1e-6, string.format("running %s, fuel %.6f after %.2f h",
            tostring(g:isActivated()), g:getFuel(), hours() - ctx.h)
    end)
    PR.full = tanks[1]
    return true
end }

-- A tank of 3 uses, burned to empty, comes back empty.
RT.PR.empty = { name = "rtprb_empty_tank", timeout = 40000, fn = function(ctx, ticks)
    local PR = RT.PR
    if RT.abort then return true end
    if not ctx.r then
        -- The full tank put aside, so the small one is the one taken.
        if PR.full then player():getInventory():Remove(PR.full) end
        local small = player():getInventory():AddItem("Base.PropaneTank")
        small:setUsedDelta(3 * small:getUseDelta())
        ctx.r = prMenu("RTPRB.connect_small", "ContextMenu_TLG_GasConnectTank")
        local g = prGen()
        g:setActivated(true)
        ctx.h = hours()
        RT.speed(20)
        return nil
    end
    if ticks % 30 == 0 then RT.keepFit() end
    if prGen():isActivated() and hours() - ctx.h < 4 then return nil end
    RT.speed(1)
    local rec = prRecord()
    local r = prMenu("RTPRB.remove_empty", "ContextMenu_TLG_GasRemoveTank")
    local tanks = prTanks()
    local back = tanks[1]
    R:check("RTPRB.empty_tank_given_back", function()
        return ctx.r.ok == true and ctx.r.uses == 3 and r.ok == true and r.uses == 0 and back ~= nil and prUses(back) == 0,
            string.format("connected ok=%s uses=%s; record tank before removal %s; removed ok=%s uses=%s; tank item %s with %s uses",
                tostring(ctx.r.ok), tostring(ctx.r.uses), tostring(rec and rec.tank and rec.tank.uses), tostring(r.ok),
                tostring(r.uses), tostring(back ~= nil), tostring(back and prUses(back)))
    end)
    if back then player():getInventory():Remove(back) end
    if PR.full then player():getInventory():AddItem(PR.full) end
    return true
end }

-- Remove the conversion with a tank in: the tank back, the buffer let out,
-- the record gone, the stock profile and half the parts.
RT.PR.unconvert = { name = "rtprb_remove_conversion", timeout = 1200, fn = function(ctx, ticks)
    if RT.abort then return true end
    local g = prGen()
    local G = TLG.Integration.Generators
    local inv = player():getInventory()
    local tanksBefore = #prTanks()
    local c = prMenu("RTPRB.connect_again", "ContextMenu_TLG_GasConnectTank", g)
    local rec = prRecord(g)
    local expect = (rec and rec.tank and rec.tank.uses or 0)
        + (TLG.Domain.Gas.nm3ToUses(TLG.Domain.GasFeed.current(rec or { buf = {} }, g:getFuel()).propane or 0) or 0)
    -- What the removal asks: its tools, the skills and the recipe of the
    -- conversion (launch 351 lacked the recipe and was refused,
    -- missing_recipe, with nothing changed).
    for _, id in ipairs({ "Base.PipeWrench", "Base.Screwdriver" }) do inv:AddItem(id) end
    player():setPerkLevelDebug(Perks.Mechanics, 4)
    player():setPerkLevelDebug(Perks.Electricity, 4)
    player():getKnownRecipes():add("Generator")
    local hoses = inv:getCountTypeRecurse("Base.RubberHose")
    local r = menuClick("RTPRB.remove_conversion", function(cm) TLG.UI.WorkshopMenu.fill(0, cm, { g }, false) end,
        getText("ContextMenu_TLG_ConvGenerator"), getText("ContextMenu_TLG_ConvRemove"))
    local tanks = prTanks()
    local back
    for _, it in ipairs(tanks) do if prUses(it) >= expect - 1 then back = it end end
    RT.PR.state("conversion_removed")
    R:check("RTPRB.conversion_removed_with_the_tank_back", function()
        return c.ok == true and r.ok == true and r.state == "Removed" and #tanks == tanksBefore and back ~= nil
            and g:getFuel() == 0 and prRecord(g) == nil and G.profile(g) == "generator_si_stock" and not G.isGas(g)
            and inv:getCountTypeRecurse("Base.RubberHose") == hoses + 1, string.format(
            "connected ok=%s; removal ok=%s state=%s; tanks %d (were %d), one with %s uses (expected %s or one less); A fuel " ..
            "%.6f; record %s; profile %s; rubber hoses %d (were %d)", tostring(c.ok), tostring(r.ok), tostring(r.state),
            #tanks, tanksBefore, tostring(back and prUses(back)), tostring(expect), g:getFuel(), tostring(prRecord(g) ~= nil),
            tostring(G.profile(g)), inv:getCountTypeRecurse("Base.RubberHose"), hoses)
    end)
    return true
end }

RT.gasPropaneBSteps = { RT.PR.reload, RT.PR.after, RT.PR.remove, RT.PR.empty, RT.PR.unconvert, RT.finish }

------------------------------------------------------------------------------
-- Gas generator on wood gas (requests "sp-rtwd", then "sp-rtwdb"; D-040). A
-- vanilla generator, A, converted to gas as RT.PR converts it, and a Wood
-- Gasifier put down two tiles from it, used through its own menu with wood
-- carried, at the default generator fuel setting (RT.PR.spot is A's spot,
-- so RT.PR's watcher and helpers read A):
--   phase A  the item, its recipe and the handbook as the scripts give them;
--            the gasifier's menu: Light greyed while empty, wood loaded, lit;
--            warmed up, its gas fills A to one step and the margin; A
--            started through the start gate; hours run, the gas the
--            gasifier gave equal to A's steps and what A holds, and its wood
--            equal to that gas; Gas status; the game's Add fuel and the mod's
--            pour refused; Put out: A stops within two steps; lit again and
--            A started; taken up while lit and put down a tile away: out at
--            its next read, its wood kept; lit, A started; a trip that
--            unloads both: on return A is off and the gasifier out; saved.
--   phase B  the save continued: both records as saved; lit again, A fed
--            and started, an hour's refills.
------------------------------------------------------------------------------
RT.WD = { hours = 4, tripHours = 6, wood = { ["Base.Log"] = 4, ["Base.Firewood"] = 5, ["Base.Charcoal"] = 2 } }

local function wdItem()
    local WD = RT.WD
    if WD.spot == nil or WD.itemId == nil then return nil end
    for dx = -3, 3 do
        for dy = -3, 3 do
            local s = sq(WD.spot.x + dx, WD.spot.y + dy, 0)
            local objs = s and s:getWorldObjects()
            for i = 0, (objs and objs:size() or 0) - 1 do
                local it = objs:get(i):getItem()
                if it and it:getID() == WD.itemId then return it end
            end
        end
    end
    return player():getInventory():getItemWithIDRecursiv(WD.itemId)
end

-- The gasifier's record brought to now, on a copy (what the menu reads).
local function wdState()
    local it = wdItem()
    local GZ = TLG.Integration.Gasifiers
    local st = it and GZ.read(it, false)
    return st and GZ.advance(it, st, TLG.World.now()) or nil
end

local function wdMenu(label, key)
    return menuClick(label, function(c) TLG.UI.GasifierMenu.fill(0, c, { wdItem() }) end, getText("ContextMenu_TLG_Gasifier"),
        getText(key))
end

function RT.WD.state(label)
    local g, st = prGen(), wdState()
    local rec = prRecord(g)
    local cur = rec and g and TLG.Domain.GasFeed.current(rec, g:getFuel()) or {}
    local s = st and TLG.Domain.Gas.Gasifier.status(st) or {}
    R:line("OBS  RTWD.%s at %.4f h: A fuel %.7f running %s load %.7f; A's buffer %.6f Nm3 wood gas, %.6f propane; gasifier " ..
        "%s/%s/%s hopper %.3f kg buffer %.4f Nm3 filter %.4f; totals fed %.4f kg delivered %.6f flared %.4f vented %.4f " ..
        "Nm3; on its square %s", label, hours(), g and g:getFuel() or -1, tostring(g and g:isActivated()),
        g and RT.GM.power(g) or -1, cur.woodgas or 0, cur.propane or 0, tostring(s.state), tostring(s.mode),
        tostring(s.reason), s.hopperKg or -1, s.buffer or -1, s.filter or -1, st and st.totals.fed or -1,
        st and st.totals.delivered or -1, st and st.totals.flared or -1, st and st.totals.vented or -1,
        tostring(wdItem() ~= nil and wdItem():getWorldItem() ~= nil))
end

-- Waits `h` game hours at speed 20, then runs `check`.
local function wdWait(name, h, check, timeout)
    return { name = name, timeout = timeout or 40000, fn = function(ctx, ticks)
        if RT.abort then return true end
        if not ctx.h then
            ctx.h = hours()
            RT.speed(20)
            return nil
        end
        if ticks % 30 == 0 then RT.keepFit() end
        if hours() - ctx.h < h then return nil end
        RT.speed(1)
        check(ctx)
        return true
    end }
end

RT.WD.setup = { name = "rtwd_setup", timeout = 1200, fn = function(ctx, ticks)
    local WD = RT.WD
    if not ctx.t0 then
        local p = player()
        p:setGodMod(true)
        p:setInvisible(true)
        captureDialogs(true)
        RT.keepFit()
        ctx.t0 = ticks
        return nil
    end
    if ticks - ctx.t0 < 60 then return nil end
    if not ctx.placed then
        local spot
        for dy = 4, 16 do
            for dx = -12, 12 do
                local x, y = START.x + dx, START.y + dy
                if spot == nil and RT.MI.clear(x, y) and RT.MI.clear(x + 1, y) and RT.MI.clear(x + 2, y)
                    and RT.MI.clear(x + 1, y + 1) and RT.MI.clear(x + 2, y + 1) then
                    spot = { x = x, y = y }
                end
            end
        end
        if spot == nil then
            RT.abort = "no clear squares for the generator and the gasifier"
            R:check("RTWD.placed", function() return false, "no clear squares near the start" end)
            return true
        end
        WD.spot, RT.PR.spot = spot, spot
        pcall(function() IsoGenerator.new(instanceItem("Base.Generator"), getCell(), sq(spot.x, spot.y, 0)) end)
        local g = prGen()
        if g then
            g:setConnected(true)
            g:setFuel(0)
            WD.convState, WD.convSteps = RT.PR.commission(g)
        end
        local it = instanceItem("TLG.Gasifier")
        sq(spot.x + 2, spot.y, 0):AddWorldInventoryItem(it, 0.5, 0.5, 0, false)
        WD.itemId = it:getID()
        local inv = player():getInventory()
        for t, n in pairs(WD.wood) do
            for _ = 1, n do inv:AddItem(t) end
        end
        player():teleportTo(spot.x + 1, spot.y + 1, 0)
        ctx.placed = ticks
        return nil
    end
    if ticks - ctx.placed < 60 then return nil end
    local g, it = prGen(), wdItem()
    local G = TLG.Integration.Generators
    R:line("OBS  RTWD.placed A at %d,%d, the gasifier at %d,%d: conversion %s (%s); setting %s; the gasifier %s on the floor %s",
        WD.spot.x, WD.spot.y, WD.spot.x + 2, WD.spot.y, tostring(WD.convState), tostring(WD.convSteps),
        tostring(g and RT.GM.setting(g)), tostring(it and it:getFullType()), tostring(it and it:getWorldItem() ~= nil))
    R:check("RTWD.placed", function()
        return g ~= nil and WD.convState == "Commissioned" and G.isGas(g) and it ~= nil and it:getWorldItem() ~= nil,
            string.format("A %s, project %s, profile %s; gasifier %s on the floor %s", tostring(g ~= nil),
                tostring(WD.convState), tostring(g and G.profile(g)), tostring(it ~= nil),
                tostring(it and it:getWorldItem() ~= nil))
    end)
    -- The scripts: the item and its floor model, the recipe (Welding 5, to
    -- be learned) and the handbook that teaches it.
    local sm = getScriptManager()
    local si, book = sm:FindItem("TLG.Gasifier"), sm:FindItem("TLG.WoodGasHandbook")
    local r = RT.HB.recipe("TLG_MakeGasifier")
    local _, asks = RT.HB.skill("TLG_MakeGasifier")
    local learned = {}
    pcall(function()
        local list = instanceItem("TLG.WoodGasHandbook"):getLearnedRecipes()
        for i = 0, (list and list:size() or 0) - 1 do learned[#learned + 1] = tostring(list:get(i)) end
    end)
    R:check("RTWD.item_recipe_and_handbook", function()
        return si ~= nil and si:getWorldStaticModel() == "TLG.Gasifier" and book ~= nil and r ~= nil
            and r:needToBeLearn() == true and asks == "MetalWelding:5" and learned[1] == "TLG_MakeGasifier", string.format(
            "item %s model %s; handbook %s teaches [%s]; recipe %s asks %s, must be learned %s", tostring(si ~= nil),
            tostring(si and si:getWorldStaticModel()), tostring(book ~= nil), table.concat(learned, ","), tostring(r ~= nil),
            tostring(asks), tostring(r and r:needToBeLearn()))
    end)
    if not (g and G.isGas(g) and it) then RT.abort = "A is not a gas generator or the gasifier is missing" end
    return true
end }

-- The menu: Light greyed while the hopper is empty; the wood loaded; lit.
RT.WD.load = { name = "rtwd_load_and_light", timeout = 600, fn = function(ctx, ticks)
    local WD = RT.WD
    if RT.abort then return true end
    local dark = wdMenu("RTWD.light_empty", "ContextMenu_TLG_GasifierLight")
    local l = wdMenu("RTWD.load", "ContextMenu_TLG_GasifierLoad")
    local left = countType("Base.Log") + countType("Base.Firewood") + countType("Base.Charcoal")
    local lit = wdMenu("RTWD.light", "ContextMenu_TLG_GasifierLight")
    WD.state("lit")
    local key = WD.spot.x .. "," .. WD.spot.y .. ",0"
    R:check("RTWD.light_greyed_while_empty", function()
        return dark.reason == "entry_disabled", "Light with an empty hopper: " .. tostring(dark.reason)
    end)
    R:check("RTWD.wood_loaded", function()
        return l.ok == true and math.abs((l.loadedKg or 0) - 48) < 1e-6 and l.items == 11 and left == 0, string.format(
            "reply ok=%s loaded %s kg in %s pieces; wood and charcoal left carried %d", tostring(l.ok), tostring(l.loadedKg),
            tostring(l.items), left)
    end)
    R:check("RTWD.lit_and_A_watched", function()
        return lit.ok == true and lit.state == "Processing" and lit.mode == "warming"
            and TLG.Integration.Generators.gasSquares[key] == true, string.format("reply ok=%s state %s mode %s; A watched %s",
            tostring(lit.ok), tostring(lit.state), tostring(lit.mode), tostring(TLG.Integration.Generators.gasSquares[key]))
    end)
    return true
end }

-- Warmed up: the gas fills A, still off, to one step and the margin. The
-- warm-up is half an hour; a scan that found no gas waits ten minutes.
RT.WD.warm = wdWait("rtwd_warm", 1.0, function(ctx)
    local g, rec, st = prGen(), prRecord(), wdState()
    local G, GasFeed = TLG.Integration.Generators, TLG.Domain.GasFeed
    RT.WD.state("warmed")
    local cap = G.woodgasCap(g)
    R:check("RTWD.warm_gasifier_fills_A", function()
        return st ~= nil and st.warm >= 0.5 - 1e-9 and rec ~= nil and (rec.buf.woodgas or 0) > 0 and G.holdsGas(g)
            and math.abs(g:getFuel() - cap) < 1e-5 and st.totals.delivered > 0, string.format(
            "warmed %s h; A fuel %.7f against the cap %.7f (step %.7f + %.0e); A's wood gas %s Nm3; delivered %s Nm3",
            tostring(st and st.warm), g:getFuel(), cap, RT.GM.power(g), GasFeed.MARGIN,
            tostring(rec and rec.buf.woodgas), tostring(st and st.totals.delivered))
    end)
end)

RT.WD.start = actionStep("rtwd_start", function(ctx)
    if RT.abort then return nil end
    player():teleportTo(RT.WD.spot.x + 1, RT.WD.spot.y, 0)
    return ISActivateGenerator:new(player(), prGen(), true)
end, function(ctx)
    local g = prGen()
    local e = TLG.Integration.Generators.evaluate(g)
    R:check("RTWD.started_on_wood_gas", function()
        return g:isActivated() and e.compatible == true and e.grade == "good", string.format(
            "running %s; evaluation compatible %s grade %s reasons %s", tostring(g:isActivated()), tostring(e.compatible),
            tostring(e.grade), table.concat(e.reasons or {}, ","))
    end)
end)

-- Hours at speed 20: A runs on its buffer, refilled each hour from the
-- gasifier. The gas it gave is A's steps and what A holds more than at the
-- start; its wood is that gas and what its own buffer took (no warm-up, no
-- venting within the window).
RT.WD.run = { name = "rtwd_run", timeout = 60000, fn = function(ctx, ticks)
    local PR, WD = RT.PR, RT.WD
    if RT.abort then return true end
    if not ctx.h0 then
        local st = wdState()
        ctx.h0, ctx.f0, ctx.d0, ctx.fed0, ctx.b0 = hours(), prGen():getFuel(), st.totals.delivered, st.totals.fed, st.buffer
        PR.watch(true)
        RT.speed(20)
        return nil
    end
    if ticks % 30 == 0 then RT.keepFit() end
    if hours() - ctx.h0 < WD.hours then return nil end
    RT.speed(1)
    PR.watch(false)
    local g, st = prGen(), wdState()
    WD.state("after_hours")
    local nm3 = TLG.Domain.GasFeed.nm3For("woodgas", 1)
    local delivered = st.totals.delivered - ctx.d0
    local burned = (ctx.f0 - g:getFuel()) + delivered / nm3
    -- The hopper's mix (wood and charcoal) burns in proportion: its gas per
    -- kg is its rated output over its feed rate.
    local perKg = TLG.Domain.Gas.Gasifier.ratedOutput(st) / TLG.Registry.need("machine", st.machine).feedKgPerHour
    local fedGas = (st.totals.fed - ctx.fed0) * perKg
    R:line("OBS  RTWD.run: %.3f game h, %d stops; the gasifier gave %.7f Nm3 (%.7f L); A burned %.7f L by its fuel; the " ..
        "wood fed makes %.7f Nm3 against %.7f given and %.7f more in its buffer", hours() - ctx.h0, PR.stops, delivered,
        delivered / nm3, burned, fedGas, delivered, st.buffer - ctx.b0)
    R:check("RTWD.ran_on_wood_gas", function()
        local steps = 0
        for h = math.floor(ctx.h0) + 1, math.floor(hours()) do steps = steps + 1 end
        return g:isActivated() and PR.stops == 0 and delivered > 0 and math.abs(burned - steps * RT.GM.power(g)) < 1e-4
            and math.abs(fedGas - delivered - (st.buffer - ctx.b0)) < 1e-6, string.format(
            "running %s, %d stops; %d boundaries of %.7f L = %.7f L against %.7f L burned; wood %.7f Nm3 against %.7f",
            tostring(g:isActivated()), PR.stops, steps, RT.GM.power(g), steps * RT.GM.power(g), burned, fedGas,
            delivered + st.buffer - ctx.b0)
    end)
    return true
end }

-- Gas status from the Gas menu; the gasifier's Status from its own.
RT.WD.status = { name = "rtwd_status", timeout = 600, fn = function(ctx, ticks)
    if RT.abort then return true end
    local s = prMenu("RTWD.gas_status", "ContextMenu_TLG_GasStatus")
    local z = wdMenu("RTWD.gasifier_status", "ContextMenu_TLG_GasifierStatus")
    local text = H.dialogs.texts[#H.dialogs.texts] or ""
    closeDialogs()
    R:line("OBS  RTWD.status Gas status: wood gas %s Nm3, lit gasifiers %s, tank %s; the gasifier's Status: %s",
        tostring(s.woodgasNm3), tostring(s.gasifiers), tostring(s.tankUses), text)
    R:check("RTWD.status_shows_wood_gas", function()
        return s.ok == true and (s.woodgasNm3 or 0) > 0 and s.gasifiers == 1 and s.tankUses == nil and z.ok == true
            and (z.state == "Paused" or z.state == "Processing") and (z.hopperKg or 0) > 40, string.format(
            "Gas status ok=%s wood gas %s gasifiers %s tank %s; gasifier ok=%s state %s hopper %s", tostring(s.ok),
            tostring(s.woodgasNm3), tostring(s.gasifiers), tostring(s.tankUses), tostring(z.ok), tostring(z.state),
            tostring(z.hopperKg))
    end)
    return true
end }

RT.WD.refusals = actionStep("rtwd_add_fuel", function(ctx)
    if RT.abort then return nil end
    local g = prGen()
    ctx.can = giveCan("Base.PetrolCan", { { Fluid.Petrol, 4.0 } })
    ctx.fuel, ctx.canL = g:getFuel(), ctx.can:getFluidContainer():getAmount()
    return ISAddFuel:new(player(), g, ctx.can, 100)
end, function(ctx)
    local g = prGen()
    local pour = ask("RTWD.pour", "transfer", { source = TLG.Authority.Resolver.refForItem(ctx.can),
        destination = TLG.Authority.Resolver.refForObject(g, "generator"), amount = 2 })
    R:check("RTWD.no_liquid_goes_in", function()
        -- A refill may come between: A's fuel is never more than its cap.
        return g:getFuel() <= TLG.Integration.Generators.woodgasCap(g) + 1e-6
            and math.abs(ctx.can:getFluidContainer():getAmount() - ctx.canL) < 1e-6 and pour.ok == false
            and pour.reason == "gas_generator", string.format(
            "after Add fuel: A %.7f (cap %.7f), can %.3f (was %.3f); the pour: ok=%s reason=%s", g:getFuel(),
            TLG.Integration.Generators.woodgasCap(g), ctx.can:getFluidContainer():getAmount(), ctx.canL, tostring(pour.ok),
            tostring(pour.reason))
    end)
    player():getInventory():Remove(ctx.can)
end)

-- Put out: the gas in it let out; A runs on what it holds and stops within
-- two of its steps.
RT.WD.putOut = { name = "rtwd_put_out", timeout = 40000, fn = function(ctx, ticks)
    local PR = RT.PR
    if RT.abort then return true end
    if not ctx.r then
        ctx.r = wdMenu("RTWD.put_out", "ContextMenu_TLG_GasifierPutOut")
        ctx.h = hours()
        RT.WD.state("put_out")
        PR.watch(true)
        RT.speed(20)
        return nil
    end
    if ticks % 30 == 0 then RT.keepFit() end
    local g = prGen()
    if g:isActivated() and hours() - ctx.h < 3 then return nil end
    RT.speed(1)
    PR.watch(false)
    RT.WD.state("A_stopped")
    R:check("RTWD.put_out_and_A_stops", function()
        return ctx.r.ok == true and ctx.r.state == "Ready" and (ctx.r.vented or 0) > 0 and not g:isActivated()
            and g:getFuel() <= 1e-6 and hours() - ctx.h <= 2.05, string.format(
            "reply ok=%s state %s let out %s Nm3; A running %s fuel %.7f, %.3f h after", tostring(ctx.r.ok),
            tostring(ctx.r.state), tostring(ctx.r.vented), tostring(g:isActivated()), g:getFuel(), hours() - ctx.h)
    end)
    return true
end }

-- Lit again from the menu; warmed, its gas in A; A started again.
function RT.WD.relight(label)
    return wdWait("rtwd_relight_" .. label, 1.0, function(ctx)
        local g = prGen()
        R:check("RTWD.relit_" .. label, function()
            return ctx.r.ok == true and ctx.r.mode == "warming" and TLG.Integration.Generators.holdsGas(g), string.format(
                "Light ok=%s mode %s; A fuel %.7f holds gas %s", tostring(ctx.r.ok), tostring(ctx.r.mode), g:getFuel(),
                tostring(TLG.Integration.Generators.holdsGas(g)))
        end)
    end)
end
local function wdLight(label)
    local step = RT.WD.relight(label)
    local fn = step.fn
    step.fn = function(ctx, ticks)
        if RT.abort then return true end
        if not ctx.r then ctx.r = wdMenu("RTWD.light_" .. label, "ContextMenu_TLG_GasifierLight") end
        return fn(ctx, ticks)
    end
    return step
end

RT.WD.restart = function(label)
    return actionStep("rtwd_restart_" .. label, function(ctx)
        if RT.abort then return nil end
        player():teleportTo(RT.WD.spot.x + 1, RT.WD.spot.y, 0)
        return ISActivateGenerator:new(player(), prGen(), true)
    end, function(ctx)
        R:check("RTWD.started_again_" .. label, function()
            return prGen():isActivated(), "running " .. tostring(prGen():isActivated())
        end)
    end)
end

-- Taken up while lit, with the world menu's Grab (ISWorldObjectContextMenu
-- .onGrabWItem, which queues ISGrabItemAction in single player), and put
-- down a tile away with the place action.
RT.WD.take = { name = "rtwd_take", timeout = 3000, fn = function(ctx, ticks)
    if RT.abort then return true end
    if not ctx.queued then
        local it = wdItem()
        ctx.hopper = TLG.Domain.Gas.Gasifier.status(wdState()).hopperKg
        ctx.lit = TLG.Integration.Gasifiers.lit(wdState())
        player():teleportTo(RT.WD.spot.x + 2, RT.WD.spot.y + 1, 0)
        ISWorldObjectContextMenu.onGrabWItem(nil, it:getWorldItem(), 0)
        ctx.queued = ticks
        return nil
    end
    if ticks - ctx.queued < 10 or not TLGH.Steps.actionsIdle(player()) then return nil end
    local it = wdItem()
    R:check("RTWD.taken_up_while_lit", function()
        return ctx.lit == true and it ~= nil and it:getWorldItem() == nil
            and player():getInventory():getItemWithIDRecursiv(RT.WD.itemId) ~= nil, string.format(
            "lit before %s; carried %s", tostring(ctx.lit), tostring(it ~= nil and it:getWorldItem() == nil))
    end)
    RT.WD.hopperBefore = ctx.hopper
    return true
end }

RT.WD.put = actionStep("rtwd_put", function(ctx)
    if RT.abort then return nil end
    local it = wdItem()
    if it == nil or it:getWorldItem() ~= nil then return nil end
    return ISDropWorldItemAction:new(player(), it, sq(RT.WD.spot.x + 2, RT.WD.spot.y + 1, 0), 0.5, 0.5, 0, 0, false)
end, function(ctx)
    local z = wdMenu("RTWD.status_moved", "ContextMenu_TLG_GasifierStatus")
    closeDialogs()
    local it = wdItem()
    R:check("RTWD.put_down_elsewhere_is_out", function()
        return it ~= nil and it:getWorldItem() ~= nil and z.ok == true and z.state == "Ready"
            and math.abs((z.hopperKg or 0) - (RT.WD.hopperBefore or -1)) < 0.05, string.format(
            "on the floor %s; Status ok=%s state %s hopper %s kg (was %s)", tostring(it and it:getWorldItem() ~= nil),
            tostring(z.ok), tostring(z.state), tostring(z.hopperKg), tostring(RT.WD.hopperBefore))
    end)
end)

-- Away: both chunks unload. A burns what it holds and stops; nothing draws
-- from the gasifier, which goes out after its hold.
RT.WD.trip = { name = "rtwd_trip", timeout = 40000, fn = function(ctx, ticks)
    local WD = RT.WD
    if RT.abort then return true end
    if not ctx.at then
        WD.state("leaving")
        player():teleportTo(WD.spot.x, WD.spot.y - RT.away, 0)
        ctx.at = ticks
        return nil
    end
    if not ctx.from then
        if ticks - ctx.at < 120 then return nil end
        ctx.from = hours()
        RT.speed(RT.waitSpeed)
        return nil
    end
    if ticks % 30 == 0 then RT.keepFit() end
    if not ctx.back then
        if sq(WD.spot.x, WD.spot.y, 0) == nil then ctx.unloaded = true end
        if hours() - ctx.from < WD.tripHours then return nil end
        RT.speed(1)
        player():teleportTo(WD.spot.x + 1, WD.spot.y + 1, 0)
        ctx.back = ticks
        return nil
    end
    if ticks - ctx.back < 180 then return nil end
    local g, st = prGen(), wdState()
    WD.state("back")
    R:check("RTWD.trip_A_off_and_gasifier_out", function()
        return ctx.unloaded == true and g ~= nil and not g:isActivated() and g:getFuel() <= 1e-6 and st ~= nil
            and st.state == "Ready" and TLG.Domain.Gas.Gasifier.status(st).hopperKg > 0, string.format(
            "unloaded %s; A running %s fuel %.7f; gasifier %s hopper %s", tostring(ctx.unloaded == true),
            tostring(g and g:isActivated()), g and g:getFuel() or -1, tostring(st and st.state),
            tostring(st and TLG.Domain.Gas.Gasifier.status(st).hopperKg))
    end)
    return true
end }

RT.WD.beforeSave = { name = "rtwd_before_save", fn = function()
    RT.speed(1)
    local g, it = prGen(), wdItem()
    if RT.abort or g == nil or it == nil then return true end
    local rec, st = prRecord(g), it:getModData().tlgGasifier
    TLGH.writeFile("TLG_harness_expect.txt", { "wd.x=" .. RT.WD.spot.x, "wd.y=" .. RT.WD.spot.y,
        "wd.item=" .. tostring(RT.WD.itemId), "wd.gid=" .. tostring(st and st.id), "wd.rid=" .. tostring(rec and rec.id),
        "wd.hopper=" .. string.format("%.6f", TLG.Domain.Gas.Gasifier.status(wdState()).hopperKg) })
    RT.WD.state("saving")
    return true
end }

RT.gasWoodSteps = { RT.waitWorld, RT.WD.setup, RT.WD.load, RT.WD.warm, RT.WD.start, RT.WD.run, RT.WD.status, RT.WD.refusals,
    RT.WD.putOut, wdLight("after_put_out"), RT.WD.restart("after_put_out"), RT.WD.take, RT.WD.put, wdLight("moved"),
    RT.WD.restart("moved"), RT.WD.trip, RT.WD.beforeSave, RT.saveAndExitAs("rtwd_save_and_exit", "sp-rtwdb") }

-- Phase B: the save continued.
RT.WD.reload = { name = "rtwdb_reload", timeout = 3000, fn = function(ctx, ticks)
    if not (player() and ticks > 180) then return nil end
    local e = TLGH.readKeyValues("TLG_harness_expect.txt")
    RT.WD.spot = { x = tonumber(e["wd.x"]), y = tonumber(e["wd.y"]) }
    RT.PR.spot, RT.WD.itemId = RT.WD.spot, tonumber(e["wd.item"])
    local p = player()
    p:setGodMod(true)
    p:setInvisible(true)
    captureDialogs(true)
    if not ctx.near then
        p:teleportTo(RT.WD.spot.x + 1, RT.WD.spot.y + 1, 0)
        ctx.near = ticks
        return nil
    end
    if ticks - ctx.near < 120 then return nil end
    local g, it = prGen(), wdItem()
    local rec, st = prRecord(g), it and it:getModData().tlgGasifier
    local G = TLG.Integration.Generators
    RT.WD.state("continued")
    -- Brought to now as the save's record was (out, nothing burns).
    local now = st and wdState()
    local hopper = now and TLG.Domain.Gas.Gasifier.status(now).hopperKg
    R:check("RTWDB.records_as_saved", function()
        return g ~= nil and it ~= nil and rec ~= nil and st ~= nil and tostring(rec.id) == e["wd.rid"]
            and tostring(st.id) == e["wd.gid"] and math.abs((hopper or -1) - tonumber(e["wd.hopper"])) < 1e-4
            and G.isGas(g) and G.gasSquares[RT.WD.spot.x .. "," .. RT.WD.spot.y .. ",0"] == true, string.format(
            "A %s record %s (saved %s); gasifier %s record %s (saved %s) hopper %s (saved %s); gas %s; watched %s",
            tostring(g ~= nil), tostring(rec and rec.id), tostring(e["wd.rid"]), tostring(it ~= nil), tostring(st and st.id),
            tostring(e["wd.gid"]), tostring(hopper), tostring(e["wd.hopper"]), tostring(g and G.isGas(g)),
            tostring(G.gasSquares[RT.WD.spot.x .. "," .. RT.WD.spot.y .. ",0"]))
    end)
    if g == nil or it == nil then RT.abort = "A or the gasifier is missing after the continue" end
    return true
end }

RT.WD.after = { name = "rtwdb_refills", timeout = 30000, fn = function(ctx, ticks)
    if RT.abort then return true end
    if not ctx.h then
        ctx.h, ctx.d = hours(), wdState().totals.delivered
        RT.speed(20)
        return nil
    end
    if ticks % 30 == 0 then RT.keepFit() end
    if hours() - ctx.h < 2.05 then return nil end
    RT.speed(1)
    local g, st = prGen(), wdState()
    RT.WD.state("after_refills")
    R:check("RTWDB.refills_go_on", function()
        return g:isActivated() and st.totals.delivered > ctx.d, string.format("running %s; delivered %.6f -> %.6f Nm3",
            tostring(g:isActivated()), ctx.d, st.totals.delivered)
    end)
    return true
end }

RT.gasWoodBSteps = { RT.WD.reload, wdLight("continued"), RT.WD.restart("continued"), RT.WD.after, RT.finish }

------------------------------------------------------------------------------
-- A player's own way to wood gas (request "sp-rtgy"; D-040). A vanilla
-- generator found holding petrol is converted through Workshop: convert
-- this generator: Start: Gas generator conversion, Hand over parts, Work on
-- it. The work stops where the tank must be empty ("Drain the fuel tank
-- first."); Fuel (The Last Gallon) > Drain the generator into this can
-- empties it, and Work on it goes on to Converted and commissioned. The Wood
-- Gas Handbook is read with the inventory menu's Read at Welding 5, the Wood
-- Gasifier crafted with the craft entry on the drum, put down two tiles from
-- the generator with the game's drop action, and loaded and lit from the
-- game's right-click menu on it (Gasifier (The Last Gallon) > Load the
-- hopper with wood, Light). It is photographed at zoom 1 and 0.5 with the
-- interface hidden and the fog held off. Its gas fills the generator, which
-- is started through the start gate and runs. No save. The crafting
-- window's own refusals are a server case: with -debug, which this harness
-- runs, the game's learned-recipe call answers true for a recipe not
-- learned (launch 308).
-- The mod's clock moves while the work action runs (CLOCK_PER_TICK), as in
-- the full run, so the records here end up ahead of the game's clock. Built
-- in a function of its own: with -debug the game's compiler takes at most
-- 200 locals from one function, block locals included (launch 368).
------------------------------------------------------------------------------
RT.GY = { hours = 3, wood = { ["Base.Log"] = 2, ["Base.Firewood"] = 6 },
    tools = { "Base.Screwdriver", "Base.Wrench", "Base.PipeWrench", "Base.Pliers" },
    parts = { ["Base.RubberHose"] = 2, ["Base.MetalPipe"] = 1, ["Base.SmallSheetMetal"] = 1, ["Base.Screws"] = 6,
        ["Base.ElectricWire"] = 1 },
    materials = { ["Base.MetalDrum"] = 1, ["Base.SheetMetal"] = 2, ["Base.MetalPipe"] = 3, ["Base.MetalBar"] = 2 } }

function RT.GY.build()
    local GY = RT.GY

    -- The crafted gasifier, on the floor near the generator or carried.
    local function gyItem()
        if GY.spot == nil or GY.itemId == nil then return nil end
        for dx = -3, 3 do
            for dy = -3, 3 do
                local s = sq(GY.spot.x + dx, GY.spot.y + dy, 0)
                local objs = s and s:getWorldObjects()
                for i = 0, (objs and objs:size() or 0) - 1 do
                    local it = objs:get(i):getItem()
                    if it and it:getID() == GY.itemId then return it end
                end
            end
        end
        return player():getInventory():getItemWithIDRecursiv(GY.itemId)
    end

    -- Gasifiers on the floor within three tiles of the generator.
    local function floorGasifiers()
        local out = {}
        for dx = -3, 3 do
            for dy = -3, 3 do
                local s = sq(GY.spot.x + dx, GY.spot.y + dy, 0)
                local objs = s and s:getWorldObjects()
                for i = 0, (objs and objs:size() or 0) - 1 do
                    local it = objs:get(i):getItem()
                    if it and it:getFullType() == "TLG.Gasifier" then out[#out + 1] = it end
                end
            end
        end
        return out
    end

    -- The gasifier's record brought to now, on a copy (what the menu reads).
    local function gyState()
        local it = gyItem()
        local GZ = TLG.Integration.Gasifiers
        local st = it and GZ.read(it, false)
        return st and GZ.advance(it, st, TLG.World.now()) or nil
    end

    function GY.state(label)
        local g, st = prGen(), gyState()
        local rec = prRecord(g)
        local cur = rec and g and TLG.Domain.GasFeed.current(rec, g:getFuel()) or {}
        local s = st and TLG.Domain.Gas.Gasifier.status(st) or {}
        R:line("OBS  RTGY.%s at %.4f h: generator fuel %.7f running %s profile %s; its wood gas %.6f Nm3; gasifier " ..
            "%s/%s hopper %.3f kg buffer %.4f Nm3 delivered %.6f Nm3", label, hours(), g and g:getFuel() or -1,
            tostring(g and g:isActivated()), tostring(g and TLG.Integration.Generators.profile(g)), cur.woodgas or 0,
            tostring(s.state), tostring(s.mode), s.hopperKg or -1, s.buffer or -1, st and st.totals.delivered or -1)
    end

    -- A light in hand when the square is too dark to read or craft (the
    -- game's IsoPlayer.tooDarkToRead), as a player switches a torch on.
    local function lightIfDark(label)
        local p = player()
        if not p:tooDarkToRead() then return end
        local here = p:getSquare()
        local torch = p:getInventory():AddItem("Base.HandTorch")
        torch:setActivated(true)
        p:setSecondaryHandItem(torch)
        R:line("OBS  RTGY.%s too dark (light %.2f at %.2f o'clock): a torch switched on in hand, dark now=%s", label,
            here and here:getLightLevel(0) or -1, getGameTime():getTimeOfDay(), tostring(p:tooDarkToRead()))
    end

    -- Work on it from the Workshop menu, until the work action has ended by
    -- itself (blocked or commissioned). The mod's clock moves while it runs.
    local function work(name, check)
        return { name = "rtgy_" .. name, timeout = 8000, fn = function(ctx, ticks)
            if RT.abort then return true end
            if not ctx.t0 then
                ctx.dialogs0 = #H.dialogs.texts
                workshopClick("RTGY." .. name, GEN_MENU, getText("ContextMenu_TLG_ConvJoin"))
                ctx.t0 = ticks
                return nil
            end
            local a = workAction()
            if a then
                H.clockOffset = H.clockOffset + CLOCK_PER_TICK
                -- Kept: its count goes on after it stops being current (launch
                -- 387 logged the count before the last report).
                ctx.action = a
            end
            if ticks - ctx.t0 < 30 then return nil end
            if (a or not TLGH.Steps.actionsIdle(player())) and ticks - ctx.t0 < 7000 then return nil end
            local p = projectOf(prGen(), "generator")
            local text = H.dialogs.texts[ctx.dialogs0 + 1]
            R:line("OBS  RTGY.%s: %s reports; project %s stage %s, %.4f h done; dialog \"%s\"", name,
                tostring(ctx.action and ctx.action.reports), tostring(p and p.state), tostring(p and p.stage),
                p and sumOf(p.credit) or -1, tostring(text))
            check(p, text)
            closeDialogs()
            return true
        end }
    end

    GY.setup = { name = "rtgy_setup", timeout = 1200, fn = function(ctx, ticks)
        if not ctx.t0 then
            local p = player()
            p:setGodMod(true)
            p:setInvisible(true)
            pcall(function() p:setUnlimitedCarry(true) end)
            captureDialogs(true)
            installClockOffset()
            instrumentWorkAction()
            RT.keepFit()
            ctx.t0 = ticks
            return nil
        end
        if ticks - ctx.t0 < 60 then return nil end
        if not ctx.placed then
            local spot
            for dy = 4, 16 do
                for dx = -12, 12 do
                    local x, y = START.x + dx, START.y + dy
                    if spot == nil and RT.MI.clear(x, y) and RT.MI.clear(x + 1, y) and RT.MI.clear(x + 2, y)
                        and RT.MI.clear(x + 1, y + 1) and RT.MI.clear(x + 2, y + 1) and RT.MI.clear(x + 1, y + 2) then
                        spot = { x = x, y = y }
                    end
                end
            end
            if spot == nil then
                RT.abort = "no clear squares for the generator and the gasifier"
                R:check("RTGY.placed", function() return false, "no clear squares near the start" end)
                return true
            end
            GY.spot, RT.PR.spot = spot, spot
            pcall(function() IsoGenerator.new(instanceItem("Base.Generator"), getCell(), sq(spot.x, spot.y, 0)) end)
            local g = prGen()
            if g then
                g:setConnected(true)
                -- Holding petrol, as a generator found on the map does.
                g:setFuel(2)
            end
            local p = player()
            p:setPerkLevelDebug(Perks.Mechanics, 3)
            p:setPerkLevelDebug(Perks.Electricity, 3)
            p:getKnownRecipes():add("Generator")
            for _, t in ipairs(GY.tools) do give(t, 1) end
            for t, n in pairs(GY.parts) do give(t, n) end
            GY.can = giveCan("Base.PetrolCan", {})
            p:teleportTo(spot.x + 1, spot.y + 1, 0)
            ctx.placed = ticks
            return nil
        end
        if ticks - ctx.placed < 60 then return nil end
        local g = prGen()
        local G = TLG.Integration.Generators
        R:line("OBS  RTGY.placed a generator at %d,%d holding %.4f L, profile %s; Mechanics %d, Electricity %d; game hour %.2f",
            GY.spot.x, GY.spot.y, g and g:getFuel() or -1, tostring(g and G.profile(g)), player():getPerkLevel(Perks.Mechanics),
            player():getPerkLevel(Perks.Electricity), getGameTime():getTimeOfDay())
        R:check("RTGY.placed", function()
            return g ~= nil and math.abs(g:getFuel() - 2) < 1e-4 and not G.isGas(g), string.format(
                "generator %s holding %s L, gas %s", tostring(g ~= nil), tostring(g and g:getFuel()), tostring(g and G.isGas(g)))
        end)
        if g == nil then RT.abort = "no generator" end
        return true
    end }

    -- The Workshop menu offers the gas conversion; it begins with petrol in
    -- the tank, and the parts are handed over.
    GY.begin = { name = "rtgy_begin", timeout = 600, fn = function(ctx, ticks)
        if RT.abort then return true end
        local menu = ISContextMenu.get(0, 100, 100)
        TLG.UI.WorkshopMenu.fill(0, menu, workshopDevices(), false)
        local root = menu:getOptionFromName(getText(GEN_MENU))
        local sub = root and root.subOption and menu:getSubMenu(root.subOption)
        local gas = sub and sub:getOptionFromName(startText("gas_generator"))
        menu:setVisible(false)
        R:check("RTGY.workshop_offers_the_gas_conversion", function()
            return gas ~= nil and not gas.notAvailable, string.format("Start gas %s", gas == nil and "missing"
                or (gas.notAvailable and "greyed" or "offered"))
        end)
        local b = workshopClick("RTGY.begin", GEN_MENU, startText("gas_generator"))
        local p = projectOf(prGen(), "generator")
        R:check("RTGY.begun_with_petrol_in_the_tank", function()
            return b.ok == true and p ~= nil and p.state == "InProgress" and prGen():getFuel() > 1, string.format(
                "reply ok=%s reason=%s; project %s stage %s; tank %.4f L", tostring(b.ok), tostring(b.reason),
                tostring(p and p.state), tostring(p and p.stage), prGen():getFuel())
        end)
        local d = workshopClick("RTGY.deliver", GEN_MENU, getText("ContextMenu_TLG_ConvDeliver"))
        local left = {}
        for t in pairs(GY.parts) do
            if countType(t) > 0 then left[#left + 1] = t .. "=" .. countType(t) end
        end
        R:check("RTGY.parts_handed_over", function()
            return d.ok == true and #left == 0, string.format("reply ok=%s reason=%s consumed %s; left [%s]", tostring(d.ok),
                tostring(d.reason), brief(d.consumed), table.concat(left, ","))
        end)
        if not (b.ok and p) then RT.abort = "the gas conversion did not begin" end
        return true
    end }

    -- The work stops where the tank must be empty, and says so.
    GY.workToTank = work("work_until_the_tank", function(p, text)
        R:check("RTGY.work_stops_where_the_tank_must_be_empty", function()
            return p ~= nil and p.state == "InProgress" and p.stage == "prepare"
                and has(text, getText("IGUI_TLG_ConvReason_tank_not_empty")) and prGen():getFuel() > 1,
                string.format("project %s stage %s; dialog \"%s\"; tank %.4f L", tostring(p and p.state),
                    tostring(p and p.stage), tostring(text), prGen():getFuel())
        end)
    end)

    -- Drained into the empty can from the can's Fuel menu.
    GY.drain = { name = "rtgy_drain", timeout = 3000, fn = function(ctx, ticks)
        if RT.abort then return true end
        local g = prGen()
        if not ctx.t0 then
            ctx.f0 = g:getFuel()
            local can = GY.can
            ctx.r = menuClick("RTGY.drain", function(c) TLG.UI.FuelMenu.fill(0, c, { can }) end,
                getText("ContextMenu_TLG_Fuel"), getText("ContextMenu_TLG_DrainGenerator"))
            ctx.t0 = ticks
            return nil
        end
        if ticks - ctx.t0 < 30 or (not TLGH.Steps.actionsIdle(player()) and ticks - ctx.t0 < 2500) then return nil end
        local litres = GY.can:getFluidContainer():getAmount()
        R:check("RTGY.drained_from_the_fuel_menu", function()
            return ctx.r.ok == true and g:getFuel() <= 0.05 and math.abs(litres - ctx.f0) < 0.06, string.format(
                "reply ok=%s reason=%s; tank %.4f -> %.4f L; can %.4f L", tostring(ctx.r.ok), tostring(ctx.r.reason), ctx.f0,
                g:getFuel(), litres)
        end)
        return true
    end }

    -- On to Converted and commissioned: a gas generator.
    GY.workToEnd = work("work_to_commissioned", function(p, text)
        local g, G = prGen(), TLG.Integration.Generators
        R:check("RTGY.gas_generator_commissioned_from_the_menu", function()
            return p ~= nil and p.state == "Commissioned" and math.abs(sumOf(p.credit) - 9) < 1e-6
                and G.profile(g) == "generator_gas" and G.isGas(g) and has(text, getText("IGUI_TLG_ConvState_Commissioned")),
                string.format("project %s, %.4f h of 9; profile %s gas %s; dialog \"%s\"", tostring(p and p.state),
                    p and sumOf(p.credit) or -1, tostring(G.profile(g)), tostring(G.isGas(g)), tostring(text))
        end)
        if not (p and p.state == "Commissioned") then RT.abort = "the gas conversion was not commissioned" end
    end)

    -- The Wood Gas Handbook read with the inventory menu's Read at Welding
    -- 5: the recipe is learned only then.
    GY.read = { name = "rtgy_read_handbook", timeout = 9000, fn = function(ctx, ticks)
        if RT.abort then return true end
        local p = player()
        if not ctx.t0 then
            ctx.r = RT.HB.recipe("TLG_MakeGasifier")
            p:setPerkLevelDebug(Perks.MetalWelding, 5)
            ctx.before = ctx.r ~= nil and p:isRecipeActuallyKnown(ctx.r) == true
            ctx.book = p:getInventory():AddItem("TLG.WoodGasHandbook")
            lightIfDark("read")
            ISInventoryPaneContextMenu.readItem(ctx.book, 0)
            RT.speed(3)
            ctx.t0 = ticks
            return nil
        end
        local queue = ISTimedActionQueue.getTimedActionQueue(p)
        local busy = queue and queue.queue and #queue.queue > 0
        if busy and ticks - ctx.t0 < 8000 then return nil end
        if ticks - ctx.t0 < 60 then return nil end
        RT.speed(1)
        local after = ctx.r ~= nil and p:isRecipeActuallyKnown(ctx.r) == true
        local recorded = p:getAlreadyReadBook():contains("TLG.WoodGasHandbook")
        R:check("RTGY.handbook_read_teaches_the_gasifier", function()
            return not busy and ctx.r ~= nil and not ctx.before and after and recorded, string.format(
                "recipe %s; known before %s, after %s; read to the end %s, recorded %s; Welding %d", tostring(ctx.r ~= nil),
                tostring(ctx.before), tostring(after), tostring(not busy), tostring(recorded), p:getPerkLevel(Perks.MetalWelding))
        end)
        return true
    end }

    -- Crafted with the inventory menu's craft entry on the drum. Without
    -- room in the inventory the game puts what is made at the character's
    -- feet (Actions.addOrDropItem, run 11), which is looked for too.
    GY.craft = { name = "rtgy_craft", timeout = 9000, fn = function(ctx, ticks)
        if RT.abort then return true end
        local p = player()
        if not ctx.t0 then
            for t, n in pairs(GY.materials) do give(t, n) end
            give("Base.WeldingMask", 1)
            ctx.torch = p:getInventory():AddItem("Base.BlowTorch")
            pcall(function() ctx.uses0 = ctx.torch:getCurrentUses() end)
            ctx.before, ctx.floor0 = countType("TLG.Gasifier"), #floorGasifiers()
            lightIfDark("craft")
            local recipe = RT.HB.recipe("TLG_MakeGasifier")
            local via = p:getInventory():getFirstTypeRecurse("Base.MetalDrum")
            if recipe and via then ISInventoryPaneContextMenu.OnNewCraft(via, recipe, 0, false) end
            ctx.queued = not TLGH.Steps.actionsIdle(p)
            if not ctx.queued and recipe and via then
                local containers = ISInventoryPaneContextMenu.getContainers(p)
                local logic = HandcraftLogic.new(p, nil, nil)
                logic:setContainers(containers)
                logic:setRecipeFromContextClick(recipe, via)
                local inputs, valid = "?", "?"
                pcall(function() inputs = tostring(logic:getRecipeData():areAllInputItemsSatisfied()) end)
                pcall(function() valid = tostring(CraftRecipeManager.isValidRecipeForCharacter(recipe, p, nil, containers)) end)
                R:line("OBS  RTGY.craft not queued: canPerform=%s valid=%s inputs=%s dark=%s",
                    tostring(logic:canPerformCurrentRecipe()), valid, inputs, tostring(p:tooDarkToRead()))
            end
            RT.speed(3)
            ctx.t0 = ticks
            return nil
        end
        if not TLGH.Steps.actionsIdle(p) and ticks - ctx.t0 < 8000 then return nil end
        if ticks - ctx.t0 < 60 then return nil end
        RT.speed(1)
        local carried = countType("TLG.Gasifier") - ctx.before
        local floor = floorGasifiers()
        local dropped = #floor - ctx.floor0
        local uses1
        pcall(function() uses1 = ctx.torch:getCurrentUses() end)
        local left = {}
        for t in pairs(GY.materials) do left[#left + 1] = t .. "=" .. countType(t) end
        R:check("RTGY.gasifier_crafted", function()
            return ctx.queued and carried + dropped == 1 and countType("Base.MetalDrum") == 0
                and countType("Base.SheetMetal") == 0 and countType("Base.MetalBar") == 0
                and countType("Base.MetalPipe") == 0 and countType("Base.WeldingMask") == 1, string.format(
                "queued %s; made %d carried, %d at the feet; left [%s]; mask %d; blowtorch uses %s -> %s", tostring(ctx.queued),
                carried, dropped, table.concat(left, ","), countType("Base.WeldingMask"), tostring(ctx.uses0), tostring(uses1))
        end)
        local it = p:getInventory():getFirstTypeRecurse("TLG.Gasifier") or (dropped == 1 and floor[#floor]) or nil
        GY.itemId = it and it:getID()
        if not it then RT.abort = "no gasifier was crafted" end
        return true
    end }

    -- Put down two tiles from the generator with the game's drop action (if
    -- the craft left it at the feet, it is where it fell).
    GY.place = { name = "rtgy_put_down", timeout = 3000, fn = function(ctx, ticks)
        if RT.abort then return true end
        local it = gyItem()
        if not ctx.t0 then
            ctx.carried = it ~= nil and it:getWorldItem() == nil
            if ctx.carried then
                player():teleportTo(GY.spot.x + 1, GY.spot.y + 1, 0)
                ISTimedActionQueue.add(ISDropWorldItemAction:new(player(), it, sq(GY.spot.x + 2, GY.spot.y, 0), 0.5, 0.5, 0,
                    0, false))
            end
            ctx.t0 = ticks
            return nil
        end
        if ticks - ctx.t0 < 10 or (not TLGH.Steps.actionsIdle(player()) and ticks - ctx.t0 < 2500) then return nil end
        local wi = it and it:getWorldItem()
        local s = wi and wi:getSquare()
        R:check("RTGY.put_down_beside_the_generator", function()
            return ctx.carried and s ~= nil and s:getX() == GY.spot.x + 2 and s:getY() == GY.spot.y, string.format(
                "carried before %s; on the floor %s at %s,%s", tostring(ctx.carried), tostring(s ~= nil),
                tostring(s and s:getX()), tostring(s and s:getY()))
        end)
        if s == nil then RT.abort = "the gasifier is not on the floor" end
        return true
    end }

    -- The game's right-click menu built for a click on the gasifier where it
    -- shows on screen, the cursor on it (as RT.CM does); its Gasifier entry,
    -- then `key`. Without the entry, the gasifier's inventory menu is used
    -- so the run goes on, and the check fails.
    local function onIt(label, key)
        local it = gyItem()
        local wi = it and it:getWorldItem()
        local tile = wi and wi:getSquare()
        local reply, seen = nil, "not on the floor"
        if tile then
            local x, y = wi:getScreenPosX(0), wi:getScreenPosY(0)
            local zoom = getCore():getZoom(0)
            local realX, realY = getMouseXScaled, getMouseYScaled
            getMouseXScaled, getMouseYScaled = function() return x * zoom end, function() return y * zoom end
            local ok, err = pcall(ISWorldObjectContextMenu.createMenu, 0, { tile:getFloor() }, x, y)
            getMouseXScaled, getMouseYScaled = realX, realY
            local menu = getPlayerContextMenu(0)
            local root = menu and menu:getOptionFromName(getText("ContextMenu_TLG_Gasifier"))
            local sub = root and root.subOption and menu:getSubMenu(root.subOption)
            local opt = sub and sub:getOptionFromName(getText(key))
            seen = string.format("click at %.0f,%.0f, zoom %.2f; builder ok=%s%s; Gasifier entry %s; %s %s", x, y, zoom,
                tostring(ok), ok and "" or (" " .. tostring(err)), tostring(root ~= nil), getText(key),
                opt == nil and "missing" or (opt.notAvailable and "greyed" or "offered"))
            if opt and not opt.notAvailable then reply = click(opt) or { ok = true, reason = "queued" } end
            pcall(function() menu:hideAndChildren() end)
        end
        R:line("OBS  RTGY.%s from the right-click menu: %s -> %s", label, seen, reply and brief(reply) or "not clicked")
        if reply == nil then
            reply = menuClick("RTGY." .. label .. "_inventory_menu", function(c) TLG.UI.GasifierMenu.fill(0, c, { it }) end,
                getText("ContextMenu_TLG_Gasifier"), getText(key))
            reply.fromFloor = false
        else
            reply.fromFloor = true
        end
        return reply, seen
    end

    GY.floor = { name = "rtgy_load_and_light", timeout = 1200, fn = function(ctx, ticks)
        if RT.abort then return true end
        if not ctx.t0 then
            for t, n in pairs(GY.wood) do give(t, n) end
            player():teleportTo(GY.spot.x + 1, GY.spot.y + 1, 0)
            ctx.t0 = ticks
            return nil
        end
        if ticks - ctx.t0 < 60 then return nil end
        local l, ls = onIt("load", "ContextMenu_TLG_GasifierLoad")
        local lit, lits = onIt("light", "ContextMenu_TLG_GasifierLight")
        closeDialogs()
        GY.state("lit")
        R:check("RTGY.loaded_from_the_right_click_menu", function()
            return l.fromFloor and l.ok == true and (l.loadedKg or 0) > 0 and countType("Base.Log") == 0
                and countType("Base.Firewood") == 0, string.format("%s; reply ok=%s loaded %s kg in %s pieces", ls,
                tostring(l.ok), tostring(l.loadedKg), tostring(l.items))
        end)
        R:check("RTGY.lit_from_the_right_click_menu", function()
            return lit.fromFloor and lit.ok == true and lit.state == "Processing", string.format("%s; reply ok=%s state %s mode %s",
                lits, tostring(lit.ok), tostring(lit.state), tostring(lit.mode))
        end)
        return true
    end }

    -- The model on the floor beside the generator, the interface hidden.
    local function shot(name)
        return { name = "rtgy_shot_" .. name, timeout = 600, fn = function(ctx, ticks)
            if RT.abort then return true end
            if ticks == 1 then
                player():teleportTo(GY.spot.x + 1, GY.spot.y + 2, 0)
                ISUIHandler.setVisibleAllUI(false)
            end
            if ticks == 90 then
                local file = "tlg_rtgy_" .. name .. ".png"
                local ok = pcall(function() getCore():TakeFullScreenshot(file) end)
                R:line("OBS  RTGY.screenshot %s ok=%s at zoom %.2f, game hour %.2f; the gasifier at %d,%d, the generator at %d,%d, " ..
                    "the character at %d,%d", file, tostring(ok), getCore():getZoom(0), getGameTime():getTimeOfDay(), GY.spot.x + 2,
                    GY.spot.y, GY.spot.x, GY.spot.y, GY.spot.x + 1, GY.spot.y + 2)
            end
            if ticks == 120 then ISUIHandler.setVisibleAllUI(true) end
            return ticks >= 150 or nil
        end }
    end

    -- Warmed up (half an hour): its gas fills the generator, still off, to
    -- one step and the margin.
    GY.warm = wdWait("rtgy_warm", 1.0, function(ctx)
        local g, G = prGen(), TLG.Integration.Generators
        GY.state("warmed")
        local cap = G.woodgasCap(g)
        R:check("RTGY.its_gas_fills_the_generator", function()
            return G.holdsGas(g) and math.abs(g:getFuel() - cap) < 1e-5, string.format("fuel %.7f against the cap %.7f",
                g:getFuel(), cap)
        end)
    end)

    GY.start = actionStep("rtgy_start", function(ctx)
        if RT.abort then return nil end
        player():teleportTo(GY.spot.x + 1, GY.spot.y, 0)
        return ISActivateGenerator:new(player(), prGen(), true)
    end, function(ctx)
        local g = prGen()
        local e = TLG.Integration.Generators.evaluate(g)
        R:check("RTGY.started_on_wood_gas", function()
            return g:isActivated() and e.compatible == true, string.format("running %s; compatible %s grade %s reasons %s",
                tostring(g:isActivated()), tostring(e.compatible), tostring(e.grade), table.concat(e.reasons or {}, ","))
        end)
    end)

    -- Hours at speed 20: it keeps running on the gasifier's gas.
    GY.run = { name = "rtgy_run", timeout = 60000, fn = function(ctx, ticks)
        local PR = RT.PR
        if RT.abort then return true end
        if not ctx.h0 then
            local st = gyState()
            ctx.h0, ctx.d0 = hours(), st and st.totals.delivered or 0
            PR.watch(true)
            RT.speed(20)
            return nil
        end
        if ticks % 30 == 0 then RT.keepFit() end
        if hours() - ctx.h0 < GY.hours then return nil end
        RT.speed(1)
        PR.watch(false)
        local g, st = prGen(), gyState()
        GY.state("after_hours")
        local given = st and st.totals.delivered - ctx.d0 or 0
        R:check("RTGY.ran_on_wood_gas", function()
            return g:isActivated() and PR.stops == 0 and given > 0, string.format("running %s, %d stops over %.3f game h; " ..
                "the gasifier gave %.7f Nm3", tostring(g:isActivated()), PR.stops, hours() - ctx.h0, given)
        end)
        return true
    end }

    -- The fog is held off for the photographs (RT.MM.clearSky): launch
    -- 387's fog washed the gasifier out.
    RT.gasPlayerSteps = { RT.waitWorld, GY.setup, GY.begin, GY.workToTank, GY.drain, GY.workToEnd, GY.read, GY.craft,
        GY.place, GY.floor, RT.MM.clearSky, RT.MI.zoomTo("rtgy_zoom_1", 1.0), shot("zoom_1"),
        RT.MI.zoomTo("rtgy_zoom_05", 0.5), shot("zoom_05"), RT.MI.zoomTo("rtgy_zoom_back", 1.0), GY.warm, GY.start, GY.run,
        RT.finish }
end

RT.GY.build()

------------------------------------------------------------------------------
-- Wood gas when things move (request "sp-rtgv"; D-040): what the domain
-- cases of test_gas_generators.lua say, played in game. Two vanilla
-- generators converted to gas (as in gas-wood), A and B, stand four tiles
-- apart with a Wood Gasifier between them, two tiles from each; it is
-- loaded and lit through its menu and both are started through the start
-- gate.
-- 1. Both run three hours on the one gasifier: no stop, each step drawn,
--    and all its gas accounted for (made = given + let out + held; the
--    wood burned makes what it made).
-- 2. B is taken up with the game's action (switched off and unplugged
--    first, as the game asks) and put down a tile from the gasifier: the
--    same gas record, its new square watched and its old one dropped, fed
--    there once it falls below its cap, which follows its load on the new
--    square. Taken up again and put down out of the gasifier's reach, it
--    runs on what it holds and stops.
-- 3. The lit gasifier is taken up with the world menu's Grab and put down
--    on another tile within A's reach, and nothing reads it: the
--    generator's minute pass, finding room after A's next step, is the
--    first to read it (the harness reads without writing), puts it out as
--    moved with its wood kept, and gives A nothing; A stops.
-- No save. Built in a function of its own for the -debug compiler.
------------------------------------------------------------------------------
RT.GV = { hours = 3, wood = { ["Base.Log"] = 4, ["Base.Firewood"] = 6 } }

function RT.GV.build()
    local GV = RT.GV
    local G, GZ = TLG.Integration.Generators, TLG.Integration.Gasifiers

    local function genAt(p)
        local s = p and sq(p.x, p.y, 0)
        return s and s:getGenerator() or nil
    end
    local function gen(which) return genAt(GV[which]) end
    local function keyOf(p) return p.x .. "," .. p.y .. ",0" end
    local function gasOf(g) return g and g:getModData()[G.GAS_KEY] or nil end
    local function at(dx, dy) return { x = GV.spot.x + dx, y = GV.spot.y + dy } end

    -- The gasifier, on the floor around the site or carried.
    local function gzItem()
        if GV.spot == nil or GV.itemId == nil then return nil end
        for dx = -1, 8 do
            for dy = -1, 2 do
                local s = sq(GV.spot.x + dx, GV.spot.y + dy, 0)
                local objs = s and s:getWorldObjects()
                for i = 0, (objs and objs:size() or 0) - 1 do
                    local it = objs:get(i):getItem()
                    if it and it:getID() == GV.itemId then return it end
                end
            end
        end
        return player():getInventory():getItemWithIDRecursiv(GV.itemId)
    end
    -- Its record as stored (what the minute pass will read), and a copy
    -- brought to now (what the menu reads). Neither writes.
    local function stored()
        local it = gzItem()
        local rec = it and it:getModData()[GZ.KEY]
        return type(rec) == "table" and rec or nil
    end
    local function gzNow()
        local it = gzItem()
        local st = it and GZ.read(it, false)
        return st and GZ.advance(it, st, TLG.World.now()) or nil
    end
    local function menu(label, key)
        return menuClick(label, function(c) TLG.UI.GasifierMenu.fill(0, c, { gzItem() }) end,
            getText("ContextMenu_TLG_Gasifier"), getText(key))
    end

    function GV.state(label)
        local parts = {}
        for _, which in ipairs({ "a", "b" }) do
            local g = gen(which)
            local rec = gasOf(g)
            parts[#parts + 1] = string.format("%s at %s fuel %.7f running %s load %.7f record %s", string.upper(which),
                GV[which] and keyOf(GV[which]) or "-", g and g:getFuel() or -1, tostring(g and g:isActivated()),
                g and RT.GM.power(g) or -1, tostring(rec and rec.id))
        end
        local st, raw = gzNow(), stored()
        local s = st and TLG.Domain.Gas.Gasifier.status(st) or {}
        R:line("OBS  RTGV.%s at %.4f h: %s; gasifier stored %s/%s, now %s/%s hopper %.3f kg buffer %.4f Nm3; totals " ..
            "fed %.4f kg produced %.6f delivered %.6f vented %.6f Nm3", label, hours(), table.concat(parts, "; "),
            tostring(raw and raw.state), tostring(raw and raw.pause), tostring(s.state), tostring(s.reason), s.hopperKg or -1,
            s.buffer or -1, st and st.totals.fed or -1, st and st.totals.produced or -1, st and st.totals.delivered or -1,
            st and st.totals.vented or -1)
    end

    -- Each tick, for A and B where they stand: the steps (a drop of the
    -- fuel), the refills (a rise) and the stops.
    function GV.watch(on)
        if on and not GV.hooked then
            GV.w = {}
            for _, which in ipairs({ "a", "b" }) do
                GV.w[which] = { steps = 0, burned = 0, rises = 0, risen = 0, stops = 0 }
            end
            GV.tick = function()
                for _, which in ipairs({ "a", "b" }) do
                    local g, w = gen(which), GV.w[which]
                    if g then
                        local f = g:getFuel()
                        if w.last and f < w.last - 1e-7 then w.steps, w.burned = w.steps + 1, w.burned + (w.last - f) end
                        if w.last and f > w.last + 1e-7 then w.rises, w.risen = w.rises + 1, w.risen + (f - w.last) end
                        if w.on and not g:isActivated() then w.stops = w.stops + 1 end
                        w.last, w.on = f, g:isActivated()
                    else
                        w.last, w.on = nil, nil
                    end
                end
            end
            Events.OnTick.Add(GV.tick)
            GV.hooked = true
        elseif not on and GV.hooked then
            Events.OnTick.Remove(GV.tick)
            GV.hooked = false
        end
    end
    local function watched(which)
        local w = GV.w and GV.w[which] or {}
        return string.format("%d steps (%.7f L), %d refills (%.7f L), %d stops", w.steps or -1, w.burned or -1, w.rises or -1,
            w.risen or -1, w.stops or -1)
    end

    GV.setup = { name = "rtgv_setup", timeout = 1200, fn = function(ctx, ticks)
        if not ctx.t0 then
            local p = player()
            p:setGodMod(true)
            p:setInvisible(true)
            pcall(function() p:setUnlimitedCarry(true) end)
            captureDialogs(true)
            RT.keepFit()
            ctx.t0 = ticks
            return nil
        end
        if ticks - ctx.t0 < 60 then return nil end
        if not ctx.placed then
            local spot
            for dy = 4, 20 do
                for dx = -15, 15 do
                    local x, y = START.x + dx, START.y + dy
                    local free = spot == nil
                    for cx = 0, 7 do
                        for cy = -1, 2 do
                            free = free and RT.MI.clear(x + cx, y + cy)
                        end
                    end
                    if free then spot = { x = x, y = y } end
                end
            end
            if spot == nil then
                RT.abort = "no clear ground for the two generators and the gasifier"
                R:check("RTGV.placed", function() return false, "no 8 by 4 clear squares near the start" end)
                return true
            end
            GV.spot = spot
            GV.a, GV.b, GV.g = at(0, 0), at(4, 0), at(2, 0)
            for _, which in ipairs({ "a", "b" }) do
                local p = GV[which]
                pcall(function() IsoGenerator.new(instanceItem("Base.Generator"), getCell(), sq(p.x, p.y, 0)) end)
                local g = gen(which)
                if g then
                    g:setConnected(true)
                    g:setFuel(0)
                    GV[which .. "Conv"] = RT.PR.commission(g)
                end
            end
            local it = instanceItem("TLG.Gasifier")
            sq(GV.g.x, GV.g.y, 0):AddWorldInventoryItem(it, 0.5, 0.5, 0, false)
            GV.itemId = it:getID()
            local inv = player():getInventory()
            for t, n in pairs(GV.wood) do
                for _ = 1, n do inv:AddItem(t) end
            end
            player():teleportTo(GV.g.x, GV.g.y + 1, 0)
            ctx.placed = ticks
            return nil
        end
        if ticks - ctx.placed < 60 then return nil end
        local a, b, it = gen("a"), gen("b"), gzItem()
        R:line("OBS  RTGV.placed A at %s, B at %s, the gasifier at %s: conversions %s, %s", keyOf(GV.a), keyOf(GV.b),
            keyOf(GV.g), tostring(GV.aConv), tostring(GV.bConv))
        R:check("RTGV.placed", function()
            return a ~= nil and b ~= nil and G.isGas(a) and G.isGas(b) and it ~= nil and it:getWorldItem() ~= nil,
                string.format("A %s gas %s; B %s gas %s; gasifier on the floor %s", tostring(a ~= nil), tostring(a and G.isGas(a)),
                    tostring(b ~= nil), tostring(b and G.isGas(b)), tostring(it ~= nil and it:getWorldItem() ~= nil))
        end)
        if not (a and b and it and G.isGas(a) and G.isGas(b)) then RT.abort = "the site is not as set up" end
        return true
    end }

    GV.light = { name = "rtgv_load_and_light", timeout = 600, fn = function(ctx, ticks)
        if RT.abort then return true end
        local l = menu("RTGV.load", "ContextMenu_TLG_GasifierLoad")
        local lit = menu("RTGV.light", "ContextMenu_TLG_GasifierLight")
        closeDialogs()
        GV.state("lit")
        R:check("RTGV.loaded_and_lit", function()
            return l.ok == true and (l.loadedKg or 0) > 0 and lit.ok == true and lit.state == "Processing", string.format(
                "load ok=%s %s kg; light ok=%s state %s", tostring(l.ok), tostring(l.loadedKg), tostring(lit.ok),
                tostring(lit.state))
        end)
        if lit.ok ~= true then RT.abort = "the gasifier was not lit" end
        return true
    end }

    -- Warmed up: its gas fills both, still off, to the margin.
    GV.warm = wdWait("rtgv_warm", 1.0, function(ctx)
        local a, b = gen("a"), gen("b")
        GV.state("warmed")
        R:check("RTGV.its_gas_fills_both", function()
            return G.holdsGas(a) and G.holdsGas(b) and math.abs(a:getFuel() - G.woodgasCap(a)) < 1e-5
                and math.abs(b:getFuel() - G.woodgasCap(b)) < 1e-5, string.format("A %.7f (cap %.7f), B %.7f (cap %.7f)",
                a:getFuel(), G.woodgasCap(a), b:getFuel(), G.woodgasCap(b))
        end)
        GV.bRec = gasOf(b) and gasOf(b).id
    end)

    -- Started through the start gate, standing beside it.
    local function start(name, which, standDx)
        return actionStep("rtgv_start_" .. name, function(ctx)
            if RT.abort or gen(which) == nil then return nil end
            local p = GV[which]
            player():teleportTo(p.x + standDx, p.y, 0)
            gen(which):setConnected(true)
            return ISActivateGenerator:new(player(), gen(which), true)
        end, function(ctx)
            local g = gen(which)
            R:check("RTGV.started_" .. name, function()
                return g ~= nil and g:isActivated(), string.upper(which) .. " running " .. tostring(g and g:isActivated())
            end)
        end)
    end

    -- Both on the one gasifier for three hours.
    GV.both = { name = "rtgv_both_run", timeout = 60000, fn = function(ctx, ticks)
        if RT.abort then return true end
        if not ctx.h0 then
            local st = gzNow()
            ctx.h0, ctx.fa, ctx.fb = hours(), gen("a"):getFuel(), gen("b"):getFuel()
            ctx.t0, ctx.buf0 = TLG.Tables.deepCopy(st.totals), st.buffer
            GV.watch(true)
            RT.speed(20)
            return nil
        end
        if ticks % 30 == 0 then RT.keepFit() end
        if hours() - ctx.h0 < GV.hours then return nil end
        RT.speed(1)
        GV.watch(false)
        local a, b, st = gen("a"), gen("b"), gzNow()
        local wa, wb = GV.w.a, GV.w.b
        GV.state("both_ran")
        local nm3 = TLG.Domain.GasFeed.nm3For("woodgas", 1)
        local d = {}
        for _, k in ipairs({ "fed", "produced", "delivered", "vented", "flared" }) do d[k] = (st.totals[k] or 0) - (ctx.t0[k] or 0) end
        local held = st.buffer - ctx.buf0
        local perKg = TLG.Domain.Gas.Gasifier.ratedOutput(st) / TLG.Registry.need("machine", st.machine).feedKgPerHour
        local bounds = math.floor(hours()) - math.floor(ctx.h0)
        local burnedA, burnedB = (ctx.fa - a:getFuel()) + wa.risen, (ctx.fb - b:getFuel()) + wb.risen
        R:line("OBS  RTGV.both over %.3f h, %d hour boundaries: A %s; B %s; the gasifier fed %.6f kg, made %.7f, gave " ..
            "%.7f, let out %.7f, flared %.7f, held %.7f more Nm3", hours() - ctx.h0, bounds, watched("a"), watched("b"), d.fed,
            d.produced, d.delivered, d.vented, d.flared, held)
        R:check("RTGV.one_gasifier_feeds_both", function()
            return a:isActivated() and b:isActivated() and wa.stops == 0 and wb.stops == 0 and wa.rises > 0 and wb.rises > 0,
                string.format("A running %s, %s; B running %s, %s", tostring(a:isActivated()), watched("a"),
                    tostring(b:isActivated()), watched("b"))
        end)
        R:check("RTGV.each_step_of_each_drawn", function()
            return math.abs(burnedA - bounds * RT.GM.power(a)) < 1e-4 and math.abs(burnedB - bounds * RT.GM.power(b)) < 1e-4,
                string.format("A burned %.7f L against %d steps of %.7f; B burned %.7f L against %d of %.7f", burnedA, bounds,
                    RT.GM.power(a), burnedB, bounds, RT.GM.power(b))
        end)
        R:check("RTGV.all_its_gas_accounted_for", function()
            return math.abs(d.delivered - (wa.risen + wb.risen) * nm3) < 1e-5
                and math.abs(d.produced - (d.delivered + d.vented + held)) < 1e-6 and math.abs(d.fed * perKg - d.produced) < 1e-6,
                string.format("gave %.7f Nm3 against the litres both took, %.7f; made %.7f against given + let out + held %.7f; " ..
                    "wood %.6f kg at %.4f Nm3/kg = %.7f", d.delivered, (wa.risen + wb.risen) * nm3, d.produced,
                    d.delivered + d.vented + held, d.fed, perKg, d.fed * perKg)
        end)
        return true
    end }

    -- B taken up with the game's action, switched off and unplugged first
    -- as the game asks (SRC ISTakeGenerator.isValid).
    local function takeB(name)
        return actionStep("rtgv_take_b_" .. name, function(ctx)
            if RT.abort or gen("b") == nil then return nil end
            local g = gen("b")
            ctx.rec, ctx.fuel, ctx.from = gasOf(g) and gasOf(g).id, g:getFuel(), GV.b
            g:setActivated(false)
            g:setConnected(false)
            player():setPrimaryHandItem(nil)
            player():setSecondaryHandItem(nil)
            player():teleportTo(GV.b.x - 1, GV.b.y, 0)
            return ISTakeGenerator:new(player(), g)
        end, function(ctx)
            local it = player():getPrimaryHandItem()
            local side = it and it:getModData().tlg
            local carried = side and side[G.GAS_KEY]
            GV.bItem, GV.bFrom = it, ctx.from
            R:check("RTGV.b_taken_up_" .. name .. "_with_its_record", function()
                return carried ~= nil and carried.id == GV.bRec and ctx.rec == GV.bRec and genAt(ctx.from) == nil
                    and math.abs((tonumber(it:getModData().fuel) or -1) - ctx.fuel) < 1e-4, string.format(
                    "item %s; its gas record %s (B's %s); item fuel %s (was %.7f); a generator left at %s %s",
                    tostring(it and it:getFullType()), tostring(carried and carried.id), tostring(GV.bRec),
                    tostring(it and it:getModData().fuel), ctx.fuel, keyOf(ctx.from), tostring(genAt(ctx.from) ~= nil))
            end)
            if not carried then RT.abort = "B was not taken up with its record" end
        end)
    end

    -- Put down with the game's drop action on `to`, standing beside it.
    local function putB(name, dx, dy)
        return actionStep("rtgv_put_b_" .. name, function(ctx)
            if RT.abort or GV.bItem == nil then return nil end
            ctx.to = at(dx, dy)
            player():teleportTo(ctx.to.x - 1, ctx.to.y, 0)
            return ISDropWorldItemAction:new(player(), GV.bItem, sq(ctx.to.x, ctx.to.y, 0), 0.5, 0.5, 0, 0, false)
        end, function(ctx)
            GV.b = ctx.to
            local g = gen("b")
            local rec = gasOf(g)
            R:check("RTGV.b_put_down_" .. name .. "_with_its_record", function()
                return g ~= nil and rec ~= nil and rec.id == GV.bRec and G.holdsGas(g) and G.gasSquares[keyOf(ctx.to)] == true,
                    string.format("B at %s %s; its gas record %s (was %s); holds gas %s; watched %s", keyOf(ctx.to),
                        tostring(g ~= nil), tostring(rec and rec.id), tostring(GV.bRec), tostring(g and G.holdsGas(g)),
                        tostring(G.gasSquares[keyOf(ctx.to)]))
            end)
            if g == nil then RT.abort = "B was not put down" end
        end)
    end

    -- B a tile from the gasifier: its old square dropped, fed there. It
    -- comes with what it held, and its load, so its cap, is the new
    -- square's (launch 396: 0.006 L held against a cap of 0.003 L there),
    -- so the window lasts until it has room and is refilled (at most 4 h).
    GV.bNear = { name = "rtgv_b_near", timeout = 80000, fn = function(ctx, ticks)
        if RT.abort then return true end
        if not ctx.h0 then
            local b = gen("b")
            ctx.h0, ctx.d0 = hours(), gzNow().totals.delivered
            R:line("OBS  RTGV.b_near from %.4f h: B holds %.7f L, its cap here %.7f L (load %.7f)", ctx.h0, b:getFuel(),
                G.woodgasCap(b), RT.GM.power(b))
            GV.watch(true)
            RT.speed(20)
            return nil
        end
        if ticks % 30 == 0 then RT.keepFit() end
        if not ctx.fedAt and GV.w.b.rises > 0 then ctx.fedAt = hours() end
        if hours() - ctx.h0 < 4 and not (ctx.fedAt and hours() - ctx.fedAt > 0.1) then return nil end
        RT.speed(1)
        GV.watch(false)
        local b = gen("b")
        local given = gzNow().totals.delivered - ctx.d0
        GV.state("b_near")
        R:check("RTGV.b_moved_is_fed_where_it_lands", function()
            return b ~= nil and b:isActivated() and GV.w.b.rises > 0 and GV.w.b.stops == 0 and given > 0
                and G.gasSquares[keyOf(GV.b)] == true and G.gasSquares[keyOf(GV.bFrom)] == nil, string.format(
                "B at %s running %s, %s, first refilled at %s h; the gasifier gave %.7f Nm3 meanwhile; watched there %s, " ..
                "at %s %s", keyOf(GV.b), tostring(b and b:isActivated()), watched("b"), tostring(ctx.fedAt), given,
                tostring(G.gasSquares[keyOf(GV.b)]), keyOf(GV.bFrom), tostring(G.gasSquares[keyOf(GV.bFrom)]))
        end)
        return true
    end }

    -- B out of the gasifier's reach: it runs on what it holds and stops.
    -- The window lasts until B has stopped and at least 1.5 h, so that A,
    -- still in reach, has an hourly refill in it (launch 396 ended at B's
    -- stop, 0.45 h in, before A's refill); it is judged 60 ticks after.
    GV.bAway = { name = "rtgv_b_away", timeout = 80000, fn = function(ctx, ticks)
        if RT.abort then return true end
        if not ctx.h0 then
            ctx.h0 = hours()
            GV.watch(true)
            RT.speed(20)
            return nil
        end
        if ticks % 30 == 0 then RT.keepFit() end
        local b = gen("b")
        if b and not b:isActivated() and not ctx.done then ctx.done = hours() end
        if not ctx.settle then
            if hours() - ctx.h0 < 3 and not (ctx.done and hours() - ctx.h0 >= 1.5) then return nil end
            ctx.settle = ticks
            return nil
        end
        if ticks - ctx.settle < 60 then return nil end
        RT.speed(1)
        GV.watch(false)
        local a = gen("a")
        GV.state("b_away")
        R:check("RTGV.b_out_of_reach_gets_nothing_and_stops", function()
            return b ~= nil and not b:isActivated() and GV.w.b.rises == 0 and GV.w.b.stops == 1, string.format(
                "B at %s, %s from the gasifier: running %s, %s; stopped at %s h", keyOf(GV.b),
                tostring(math.max(math.abs(GV.b.x - GV.g.x), math.abs(GV.b.y - GV.g.y))) .. " tiles", tostring(b and b:isActivated()),
                watched("b"), tostring(ctx.done))
        end)
        R:check("RTGV.a_fed_meanwhile", function()
            return a ~= nil and a:isActivated() and GV.w.a.stops == 0 and GV.w.a.rises > 0, string.format("A running %s, %s",
                tostring(a and a:isActivated()), watched("a"))
        end)
        return true
    end }

    -- The lit gasifier taken up with Grab and put down a tile off, within
    -- A's reach; nothing reads it.
    GV.move = { name = "rtgv_move_gasifier", timeout = 3000, fn = function(ctx, ticks)
        if RT.abort then return true end
        if not ctx.phase then
            ctx.before = TLG.Tables.deepCopy(stored())
            ctx.hopper = TLG.Domain.Gas.Gasifier.status(gzNow()).hopperKg
            player():teleportTo(GV.g.x, GV.g.y + 1, 0)
            ctx.phase, ctx.t0 = "grab", ticks
            return nil
        end
        if ctx.phase == "grab" then
            if ticks - ctx.t0 < 30 then return nil end
            ISWorldObjectContextMenu.onGrabWItem(nil, gzItem():getWorldItem(), 0)
            ctx.phase, ctx.t0 = "grabbing", ticks
            return nil
        end
        if ctx.phase == "grabbing" then
            if ticks - ctx.t0 < 10 or not TLGH.Steps.actionsIdle(player()) then return nil end
            local it = player():getInventory():getItemWithIDRecursiv(GV.itemId)
            if not it then
                R:check("RTGV.gasifier_moved_while_lit_unread", function() return false, "not taken up" end)
                RT.abort = "the gasifier was not taken up"
                return true
            end
            GV.to = at(1, 1)
            ISTimedActionQueue.add(ISDropWorldItemAction:new(player(), it, sq(GV.to.x, GV.to.y, 0), 0.5, 0.5, 0, 0, false))
            ctx.phase, ctx.t0 = "dropping", ticks
            return nil
        end
        if ticks - ctx.t0 < 10 or not TLGH.Steps.actionsIdle(player()) then return nil end
        local it = gzItem()
        local wi = it and it:getWorldItem()
        local s = wi and wi:getSquare()
        local rec = stored()
        GV.moved = { h = hours(), hopper = ctx.hopper, vented = rec and rec.totals.vented or -1 }
        GV.state("gasifier_moved")
        R:check("RTGV.gasifier_moved_while_lit_unread", function()
            return s ~= nil and s:getX() == GV.to.x and s:getY() == GV.to.y and rec ~= nil and GZ.lit(rec) and rec.site ~= nil
                and rec.site.x == GV.g.x and rec.site.y == GV.g.y, string.format("on the floor at " ..
                "%s,%s (put down on %s); its stored record %s/%s, site %s,%s, written at %s (before the move %s)",
                tostring(s and s:getX()), tostring(s and s:getY()), keyOf(GV.to), tostring(rec and rec.state),
                tostring(rec and rec.pause), tostring(rec and rec.site and rec.site.x), tostring(rec and rec.site and rec.site.y),
                tostring(rec and rec.t), tostring(ctx.before and ctx.before.t))
        end)
        return true
    end }

    -- Until the stored record is out and A has stopped (at most 2.5 h),
    -- judged 60 ticks after: launch 396 ended in the tick A stopped, before
    -- the watcher saw the stop.
    GV.afterMove = { name = "rtgv_after_move", timeout = 60000, fn = function(ctx, ticks)
        if RT.abort then return true end
        if not ctx.h0 then
            ctx.h0 = hours()
            GV.watch(true)
            RT.speed(20)
            return nil
        end
        if ticks % 30 == 0 then RT.keepFit() end
        local rec, a = stored(), gen("a")
        if rec and not GZ.lit(rec) and not ctx.outAt then
            ctx.outAt, ctx.minute, ctx.aFuel = hours(), (hours() % 1) * 60, a and a:getFuel()
        end
        if not ctx.settle then
            if hours() - ctx.h0 < 2.5 and not (ctx.outAt and a and not a:isActivated()) then return nil end
            ctx.settle = ticks
            return nil
        end
        if ticks - ctx.settle < 60 then return nil end
        RT.speed(1)
        GV.watch(false)
        GV.state("after_the_move")
        local st = rec and TLG.Domain.Gas.Gasifier.status(rec) or {}
        R:line("OBS  RTGV.after the move at %.4f h: the stored record went out at %s h (minute %s of its hour), A then " ..
            "holding %s L; A %s", GV.moved.h, tostring(ctx.outAt), tostring(ctx.minute), tostring(ctx.aFuel), watched("a"))
        R:check("RTGV.the_minute_pass_puts_out_the_moved_gasifier", function()
            return rec ~= nil and rec.state == "Ready" and rec.pause == "moved" and ctx.outAt ~= nil and (st.hopperKg or 0) > 0
                and st.hopperKg <= GV.moved.hopper + 1e-9 and rec.totals.vented > GV.moved.vented, string.format(
                "stored %s/%s; out at %s h; hopper %.4f kg (%.4f before the move); let out %.6f Nm3 (%.6f before)",
                tostring(rec and rec.state), tostring(rec and rec.pause), tostring(ctx.outAt), st.hopperKg or -1, GV.moved.hopper,
                rec and rec.totals.vented or -1, GV.moved.vented)
        end)
        R:check("RTGV.a_gets_nothing_from_it_and_stops", function()
            return a ~= nil and not a:isActivated() and GV.w.a.rises == 0 and GV.w.a.stops == 1, string.format(
                "A running %s, %s", tostring(a and a:isActivated()), watched("a"))
        end)
        return true
    end }

    RT.gasMovesSteps = { RT.waitWorld, GV.setup, GV.light, GV.warm, start("a", "a", 1), start("b", "b", -1), GV.both,
        takeB("near"), putB("near", 3, 1), start("b_near", "b", -1), GV.bNear,
        takeB("away"), putB("away", 7, 0), start("b_away", "b", -1), GV.bAway,
        GV.move, GV.afterMove, RT.finish }
end

RT.GV.build()

------------------------------------------------------------------------------
-- The performance mode's gas stages (D-040; docs/performance.md, "What the
-- gas work adds"). The gas generators' minute pass (Generators.gasMinute,
-- on EveryOneMinute beside the engines' minute) is timed as its handler
-- calls it. The stages go after every stage of launch 341 and before its
-- added budgets' check, so those stay as they were, on the road north of
-- the parked cars (rows 10798-10807), about 30 tiles from the stand:
-- - the minute pass with no gas generator;
-- - 8 vanilla generators converted to gas (the conversion service's steps,
--   as in gas-propane), a full propane tank connected to each through the
--   Gas menu, each started with the game's action. A refill moves whole
--   tank uses (0.0026 L each), so what it leaves below the cap is the rest
--   of the room, and a propane generator spends most minutes a part of a
--   use below its cap, at any load. The
--   minute pass is timed in that state (launch 398 found it the costly
--   one), within the tolerance of the cap, and with two steps out before
--   each call, so each call moves one use from each tank;
-- - 8 more converted, each with a Wood Gasifier on the tile beside it,
--   loaded with two logs and lit through its menu, warmed up (1.2 game
--   hours at speed 20) and started: the minute pass with the wood-gas ones
--   alone (the propane squares out of it meanwhile) at their caps, then
--   with a step out of each before each call, so each call draws a step
--   from each gasifier (Gasifiers.drawNear); then all 16 as they stand;
-- Each state is reached as the game reaches it: the fuel lowered as a burn
-- lowers it and the mod's own pass bringing it up, never raised by the
-- harness (a rise the mod did not give is not gas, GasFeed.current). Each
-- timing checks what it did: the tanks' uses, the gas given and the
-- records' times, before and after;
-- - a lit gasifier brought forward 1, 30 and 365 days (Gasifiers.advance,
--   what a read after that long away does), the Gasifier menu, the Gas menu
--   on each kind of generator, and the square-load handler on a gas
--   generator's square;
-- - 20 seconds of frames with all of it running.
-- A refill takes a little from a tank or a gasifier, so the refill timings
-- run fixed batches of 50 calls, every record and fuel put back together
-- before each batch, outside the timing (RT.PF.benchN, whose "first call"
-- is the first batch's mean); the steps taken out alone, which use nothing
-- up, are timed with RT.PF.bench, to subtract. Their budgets
-- (RT.PF.budgetsGas) are set from the first run that times them. Built in
-- a function of its own for the -debug compiler.
------------------------------------------------------------------------------
-- About three times launch 400's medians (docs/performance.md); launch 401
-- checked them first. The propane part-of-a-use budget is launch 404's,
-- after the pass's early return for a room below one use (0.337 ms before,
-- 0.129 ms after). "both_16" has none: its state depends on how many hours
-- the warm-up crossed.
RT.PF.budgetsGas = {
    ["gas_none/gas_minute"] = 0.005,
    ["propane_8/gas_minute_part_use"] = 0.39, ["propane_8/gas_minute_full"] = 0.27, ["propane_8/refill_one_use"] = 1.7,
    ["woodgas_8/gas_minute_full"] = 0.30, ["woodgas_8/refill_one_step"] = 4.8,
    ["gas_catch_up/gasifier_24_h"] = 0.41, ["gas_catch_up/gasifier_720_h"] = 0.41, ["gas_catch_up/gasifier_8760_h"] = 0.41,
    ["gas_catch_up/gasifier_menu"] = 1.0, ["gas_catch_up/gas_menu_propane"] = 0.42, ["gas_catch_up/gas_menu_woodgas"] = 0.46,
    ["gas_catch_up/load_square_gas_generator"] = 0.011,
}
RT.PF.checkBudgetsGas = RT.PF.budgetStep("rtpf_budgets_gas", function() return RT.PF.budgetsGas end)

-- `n` calls a batch, `reset` before each batch (not timed); the median
-- batch's ms per call.
function RT.PF.benchN(fn, n, reset)
    local PF, per, first = RT.PF, {}, nil
    for b = 1, PF.batches do
        if reset then reset() end
        local s = getTimestampMs()
        for _ = 1, n do fn() end
        local e = getTimestampMs() - s
        per[#per + 1] = e / n
        if b == 1 then first = e / n end
    end
    table.sort(per)
    return { first = first, med = per[math.floor((#per + 1) / 2)], lo = per[1], hi = per[#per], calls = n * PF.batches }
end

RT.PFG = { propaneRows = { 10798, 10801 }, woodRows = { 10804, 10807 }, cols = { 10587, 10590, 10593, 10596 },
    logs = 2, n = 50 }

function RT.PFG.build()
    local PF, PFG = RT.PF, RT.PFG
    local G, GZ = TLG.Integration.Generators, TLG.Integration.Gasifiers

    local function genAt(e) local s = sq(e.x, e.y, 0); return s and s:getGenerator() or nil end
    local function clearAt(x, y)
        local s = sq(x, y, 0)
        local objs = s and s:getWorldObjects()
        return PF.free(s) and (objs == nil or objs:size() == 0) and s:getGenerator() == nil
    end
    local function gasifierOf(e)
        local s = e.gid and sq(e.x + 1, e.y, 0)
        local objs = s and s:getWorldObjects()
        for i = 0, (objs and objs:size() or 0) - 1 do
            local it = objs:get(i):getItem()
            if it and it:getID() == e.gid then return it end
        end
        return nil
    end

    -- Slots on the rows: each column's own square, the square south of it
    -- free for the character, and with `east` the gasifier's beside it.
    local function slots(rows, east)
        local out = {}
        for _, y in ipairs(rows) do
            for _, x in ipairs(PFG.cols) do
                if clearAt(x, y) and clearAt(x, y + 1) and (not east or clearAt(x + 1, y)) then
                    out[#out + 1] = { x = x, y = y }
                else
                    R:line("OBS  RTPF.gas slot %d,%d not clear", x, y)
                end
            end
        end
        return out
    end

    -- Each entry in turn: the character moved beside it, then `act`, which
    -- returns true when it queued an action to wait for.
    local function eachOf(name, listFn, act)
        return { name = "rtpf_" .. name, timeout = 12000, fn = function(ctx, ticks)
            if not ctx.list then
                ctx.list, ctx.i = listFn() or {}, 0
                return nil
            end
            if ctx.phase == "wait" then
                if ticks - ctx.at < 10 or not TLGH.Steps.actionsIdle(player()) then return nil end
                ctx.phase = nil
            elseif ctx.phase == "go" then
                if ticks - ctx.at < 10 then return nil end
                ctx.phase, ctx.at = act(ctx.list[ctx.i]) and "wait" or nil, ticks
                return nil
            end
            ctx.i = ctx.i + 1
            local e = ctx.list[ctx.i]
            if e == nil then
                PF.toStand()
                return true
            end
            player():teleportTo(e.x, e.y + 1, 0)
            ctx.phase, ctx.at = "go", ticks
            return nil
        end }
    end

    local function convert(e)
        pcall(function() IsoGenerator.new(instanceItem("Base.Generator"), getCell(), sq(e.x, e.y, 0)) end)
        local g = genAt(e)
        if g then
            g:setConnected(true)
            g:setFuel(0)
            e.conv = RT.PR.commission(g)
        end
    end

    local function start(e)
        local g = genAt(e)
        if g == nil or g:isActivated() then return false end
        ISTimedActionQueue.add(ISActivateGenerator:new(player(), g, true))
        return true
    end

    PFG.gasNone = { name = "rtpf_gas_none", fn = function()
        PF.record("gas_none", "gas_minute", PF.bench(G.gasMinute))
        return true
    end }

    PFG.placePropane = eachOf("gas_propane_place", function()
        PFG.propane = slots(PFG.propaneRows, false)
        for _, e in ipairs(PFG.propane) do convert(e) end
        return PFG.propane
    end, function(e)
        local g = genAt(e)
        if g == nil then return false end
        player():getInventory():AddItem("Base.PropaneTank"):setUsedDelta(1.0)
        e.connect = menuClick("RTPF.gas_connect", function(c) TLG.UI.GasMenu.fill(0, c, { g }, false) end,
            getText("ContextMenu_TLG_Gas"), getText("ContextMenu_TLG_GasConnectTank"))
        return false
    end)
    PFG.startPropane = eachOf("gas_propane_start", function() return PFG.propane end, start)

    -- The menu's Load takes all the wood carried, so each gasifier's logs
    -- are handed over just before it is loaded.
    PFG.placeWood = eachOf("gas_wood_place", function()
        PFG.wood = slots(PFG.woodRows, true)
        for _, e in ipairs(PFG.wood) do
            convert(e)
            local it = instanceItem("TLG.Gasifier")
            sq(e.x + 1, e.y, 0):AddWorldInventoryItem(it, 0.5, 0.5, 0, false)
            e.gid = it:getID()
        end
        return PFG.wood
    end, function(e)
        local it = gasifierOf(e)
        if it == nil then return false end
        local inv = player():getInventory()
        for _ = 1, PFG.logs do inv:AddItem("Base.Log") end
        local function pick(key)
            return menuClick("RTPF.gasifier", function(c) TLG.UI.GasifierMenu.fill(0, c, { it }) end,
                getText("ContextMenu_TLG_Gasifier"), getText(key))
        end
        e.load = pick("ContextMenu_TLG_GasifierLoad")
        e.light = pick("ContextMenu_TLG_GasifierLight")
        closeDialogs()
        return false
    end)

    -- Warmed up, the gas in each wood-gas generator, still off.
    PFG.warm = { name = "rtpf_gas_warm", timeout = 40000, fn = function(ctx, ticks)
        if not ctx.h then
            ctx.h = hours()
            RT.speed(20)
            return nil
        end
        if ticks % 30 == 0 then RT.keepFit() end
        if hours() - ctx.h < 1.2 then return nil end
        RT.speed(1)
        return true
    end }
    PFG.startWood = eachOf("gas_wood_start", function() return PFG.wood end, start)

    -- What was placed, and whether all of it runs on gas.
    local function placedCheck(label, listFn, wood)
        return { name = "rtpf_gas_check_" .. label, fn = function()
            local list = listFn() or {}
            local running, holding, parts = 0, 0, {}
            for _, e in ipairs(list) do
                local g = genAt(e)
                local rec = g and g:getModData()[G.GAS_KEY]
                if g and g:isActivated() then running = running + 1 end
                if g and G.holdsGas(g) then holding = holding + 1 end
                parts[#parts + 1] = string.format("%d,%d %s fuel %.5f load %.4f %s", e.x, e.y, tostring(e.conv),
                    g and g:getFuel() or -1, g and RT.GM.power(g) or -1, wood and ("lit " .. tostring(e.light and e.light.ok))
                        or ("tank " .. tostring(rec and rec.tank and rec.tank.uses)))
            end
            R:line("OBS  RTPF.gas %s: %d placed, %d running, %d holding gas: %s", label, #list, running, holding,
                table.concat(parts, "; "))
            R:check("RTPF.gas_" .. label .. "_running", function()
                return #list == 8 and running == 8 and holding == 8, string.format("%d placed, %d running, %d holding gas",
                    #list, running, holding)
            end)
            return true
        end }
    end

    -- Every record and fuel of `list` as it is now, and a reset that puts
    -- them back (with the wood-gas scans' waits cleared).
    local function snapshot(list)
        local saved = {}
        for _, e in ipairs(list) do
            local g, it = genAt(e), gasifierOf(e)
            saved[#saved + 1] = { g = g, fuel = g and g:getFuel(), rec = g and TLG.Tables.deepCopy(g:getModData()[G.GAS_KEY]),
                it = it, st = it and TLG.Tables.deepCopy(it:getModData()[GZ.KEY]) }
        end
        return function()
            for _, s in ipairs(saved) do
                if s.g then
                    s.g:getModData()[G.GAS_KEY] = TLG.Tables.deepCopy(s.rec)
                    s.g:setFuel(s.fuel)
                end
                if s.it then s.it:getModData()[GZ.KEY] = TLG.Tables.deepCopy(s.st) end
            end
            for k in pairs(G.woodgasWait) do G.woodgasWait[k] = nil end
        end
    end
    -- What each generator of `list` holds against its cap, its tank's uses
    -- and its record's time, and its gasifier's gas given (stored record).
    local function stateOf(list)
        local out = {}
        for _, e in ipairs(list) do
            local g, it = genAt(e), gasifierOf(e)
            local rec = g and g:getModData()[G.GAS_KEY]
            local st = it and it:getModData()[GZ.KEY]
            local cap = g and ((rec and rec.tank) and G.gasCap(g) or G.woodgasCap(g))
            out[#out + 1] = { g = g, fuel = g and g:getFuel(), cap = cap, room = g and cap - g:getFuel(),
                uses = rec and rec.tank and rec.tank.uses, t = rec and rec.t, given = st and st.totals.delivered }
        end
        return out
    end
    local function stateText(s)
        local parts = {}
        for _, x in ipairs(s) do
            parts[#parts + 1] = string.format("room %.6f%s%s", x.room or -1, x.uses and (" uses " .. x.uses) or "",
                x.given and string.format(" given %.6f", x.given) or "")
        end
        return table.concat(parts, "; ")
    end
    -- The same moves (uses, gas given) and records' times before and after.
    local function unchanged(a, b)
        for i, x in ipairs(a) do
            local y = b[i]
            if x.uses ~= y.uses or x.t ~= y.t or x.given ~= y.given then return false end
        end
        return true
    end
    -- Fuel lowered as a burn lowers it, `by(x)` litres below what `s`
    -- held: never raised, since a rise the mod did not give is not gas
    -- (GasFeed.current).
    local function lower(s, by)
        return function()
            for _, x in ipairs(s) do x.g:setFuel(x.fuel - by(x)) end
        end
    end
    local function steps(n) return function(x) return n * RT.GM.power(x.g) end end
    local function withSquares(list, on)
        for _, e in ipairs(list or {}) do G.gasSquares[e.x .. "," .. e.y .. ",0"] = on or nil end
    end

    -- Propane alone. As found after the connect, each a part of a use below
    -- its cap (a use is 0.0026 L; a refill moves whole uses, so what it
    -- leaves below the cap is the rest of the room, almost never within
    -- the tolerance), so each minute's pass goes on past its tolerance test
    -- to a refill that moves nothing. Then one step burned and
    -- the mod's own pass moving a use, which leaves each within the
    -- tolerance of its cap: the early return. Then two steps out before
    -- each call, so each call moves one use.
    PFG.timePropane = { name = "rtpf_gas_timers_propane_8", timeout = 6000, fn = function(ctx, ticks)
        if ticks < 30 then return nil end
        local list, F = PFG.propane or {}, TLG.Domain.GasFeed
        PFG.useL = F.propaneLitres(TLG.Domain.Gas.usesToNm3(1))
        local s0 = stateOf(list)
        R:line("OBS  RTPF.gas propane_8 as found (a use is %.6f L): %s", PFG.useL, stateText(s0))
        PF.record("propane_8", "gas_minute_part_use", PF.bench(G.gasMinute))
        local s1 = stateOf(list)
        R:check("RTPF.gas_propane_part_use_moves_nothing", function()
            local ok = unchanged(s0, s1)
            for _, x in ipairs(s0) do ok = ok and x.room > F.TOLERANCE and x.room < PFG.useL end
            return ok, "before: " .. stateText(s0) .. " | after: " .. stateText(s1)
        end)
        lower(s1, steps(1))()
        G.gasMinute()
        local s2 = stateOf(list)
        R:line("OBS  RTPF.gas propane_8 a step burned and refilled: %s", stateText(s2))
        R:check("RTPF.gas_propane_refilled_within_tolerance", function()
            local ok = #s2 == 8
            for i, x in ipairs(s2) do ok = ok and x.room <= F.TOLERANCE and x.uses == s1[i].uses - 1 end
            return ok, stateText(s2)
        end)
        PF.record("propane_8", "gas_minute_full", PF.bench(G.gasMinute))
        local s3 = stateOf(list)
        R:check("RTPF.gas_propane_full_moves_nothing", function()
            return unchanged(s2, s3), "before: " .. stateText(s2) .. " | after: " .. stateText(s3)
        end)
        local reset, take = snapshot(list), lower(s3, steps(2))
        PF.record("propane_8", "two_steps_out_only", PF.bench(take))
        reset()
        PF.record("propane_8", "refill_one_use", PF.benchN(function() take(); G.gasMinute() end, PFG.n, reset))
        local s4 = stateOf(list)
        R:check("RTPF.gas_propane_each_call_moves_one_use", function()
            local ok = #s4 == 8
            for i, x in ipairs(s4) do ok = ok and x.uses == s3[i].uses - PFG.n end
            return ok, string.format("after the last batch of %d calls: %s (were %s)", PFG.n, stateText(s4), stateText(s3))
        end)
        reset()
        return true
    end }

    -- Wood gas alone (the propane generators' squares out of the minute
    -- pass meanwhile). Each brought to its cap by the mod's own pass (some
    -- were just started), then one step out before each call, so each call
    -- draws a step's gas from each gasifier.
    PFG.timeWood = { name = "rtpf_gas_timers_woodgas_8", timeout = 6000, fn = function(ctx, ticks)
        if ticks < 30 then return nil end
        local list, F = PFG.wood or {}, TLG.Domain.GasFeed
        withSquares(PFG.propane, false)
        for _ = 1, 3 do
            for k in pairs(G.woodgasWait) do G.woodgasWait[k] = nil end
            G.gasMinute()
        end
        local s0 = stateOf(list)
        R:line("OBS  RTPF.gas woodgas_8 at their caps: %s", stateText(s0))
        R:check("RTPF.gas_woodgas_at_their_caps", function()
            local ok = #s0 == 8
            for _, x in ipairs(s0) do ok = ok and x.room <= F.TOLERANCE and x.given ~= nil end
            return ok, stateText(s0)
        end)
        PF.record("woodgas_8", "gas_minute_full", PF.bench(G.gasMinute))
        local s1 = stateOf(list)
        R:check("RTPF.gas_woodgas_full_draws_nothing", function()
            return unchanged(s0, s1), "before: " .. stateText(s0) .. " | after: " .. stateText(s1)
        end)
        local reset, take = snapshot(list), lower(s1, steps(1))
        PF.record("woodgas_8", "one_step_out_only", PF.bench(take))
        reset()
        PF.record("woodgas_8", "refill_one_step", PF.benchN(function() take(); G.gasMinute() end, PFG.n, reset))
        local s2 = stateOf(list)
        -- Each call draws, for each generator, the step and the room it had
        -- (the game keeps the fuel as a float: 1e-4 Nm3 over the batch).
        -- A generator within two tiles of two gasifiers draws from the one
        -- with the lower id (Gasifiers.drawNear; launch 399 found two serving
        -- two each here, two none), so the gas given is judged in all.
        R:check("RTPF.gas_woodgas_each_call_draws_a_step", function()
            local ok, given, want = #s2 == 8, 0, 0
            for i, x in ipairs(s2) do
                given = given + (x.given - s1[i].given)
                want = want + PFG.n * F.nm3For("woodgas", RT.GM.power(x.g) + math.max(0, s1[i].room))
                ok = ok and x.room <= F.TOLERANCE
            end
            return ok and math.abs(given - want) < 1e-4, string.format("after the last batch of %d calls the gasifiers gave " ..
                "%.6f Nm3 in all against %.6f for every generator's step; %s (were %s)", PFG.n, given, want, stateText(s2),
                stateText(s1))
        end)
        reset()
        withSquares(PFG.propane, true)
        return true
    end }

    -- Both kinds together, as they stand after their timings.
    PFG.timeBoth = { name = "rtpf_gas_timers_both_16", timeout = 3000, fn = function(ctx, ticks)
        if ticks < 30 then return nil end
        R:line("OBS  RTPF.gas both_16: propane %s; wood gas %s", stateText(stateOf(PFG.propane or {})),
            stateText(stateOf(PFG.wood or {})))
        PF.record("both_16", "gas_minute_as_they_stand", PF.bench(G.gasMinute))
        return true
    end }

    -- A lit gasifier's catch-up, the menus, the square-load handler.
    function PFG.jobs()
        local e, p = PFG.wood and PFG.wood[1], PFG.propane and PFG.propane[1]
        local it = e and gasifierOf(e)
        local st = it and GZ.read(it, false)
        local now, jobs = TLG.World.now(), {}
        local function menu(fill)
            return function()
                local c = ISContextMenu.get(0, 100, 100)
                fill(c)
                c:setVisible(false)
            end
        end
        if st then
            for _, h in ipairs(PF.catchUp) do
                jobs[#jobs + 1] = { what = "gasifier_" .. h .. "_h", fn = function() GZ.advance(it, st, now + h) end }
            end
            jobs[#jobs + 1] = { what = "gasifier_menu", fn = menu(function(c) TLG.UI.GasifierMenu.fill(0, c, { it }) end) }
        end
        local pg, wg = p and genAt(p), e and genAt(e)
        if pg then
            jobs[#jobs + 1] = { what = "gas_menu_propane", fn = menu(function(c) TLG.UI.GasMenu.fill(0, c, { pg }, false) end) }
        end
        if wg then
            jobs[#jobs + 1] = { what = "gas_menu_woodgas", fn = menu(function(c) TLG.UI.GasMenu.fill(0, c, { wg }, false) end) }
            jobs[#jobs + 1] = { what = "load_square_gas_generator", fn = function() G.onLoadSquare(wg:getSquare()) end }
        end
        return jobs
    end

    -- Every reply dialog the menus opened is closed before the frames: the
    -- Gas and Gasifier menus show one after each action, and launches
    -- 399-400 sampled the gas frames with 24 and 8 of them on screen.
    local gasStages = { PFG.gasNone, PFG.placePropane, PFG.startPropane,
        placedCheck("propane_8", function() return PFG.propane end, false), PFG.timePropane,
        PFG.placeWood, PFG.warm, PFG.startWood,
        placedCheck("woodgas_8", function() return PFG.wood end, true), PFG.timeWood, PFG.timeBoth,
        PF.catchStep("gas_catch_up", PFG.jobs), RT.PF.closeAll, PF.frames("gas_running"), RT.PF.checkBudgetsGas }
    -- Before the added budgets' check, so every stage before stays as in
    -- launch 341.
    local at
    for i, s in ipairs(RT.perfSteps) do
        if s == RT.PF.checkBudgetsAdded then at = i end
    end
    if at then
        for k, s in ipairs(gasStages) do table.insert(RT.perfSteps, at + k - 1, s) end
    end
    -- The gas stages alone on the same road (request "sp-rtpfg"), to try
    -- them in a few minutes, with frames on the bare road first to compare
    -- the gas frames with; the record is the whole mode's.
    RT.perfGasSteps = { RT.waitWorld, RT.PF.setup, PF.frames("gas_baseline") }
    for _, s in ipairs(gasStages) do RT.perfGasSteps[#RT.perfGasSteps + 1] = s end
    RT.perfGasSteps[#RT.perfGasSteps + 1] = RT.PF.cleanup
    RT.perfGasSteps[#RT.perfGasSteps + 1] = RT.finish
end

RT.PFG.build()

------------------------------------------------------------------------------
-- Diesel vehicles (request "sp-rtdv", D-036). A new world, so its record
-- says diesel chassis exist. Three vehicles at a time are spawned beside
-- the start (the squares phase A parks on), repaired and given 10 L with
-- no record, as a vehicle of the map is found: the passenger van, the
-- radio van and a pickup truck, read and removed; then the ambulance, the
-- fire department's pickup van and a trade van, kept. The diesel chassis
-- must have the diesel profile and read their litres as diesel, the
-- others petrol. The ambulance must start on its diesel and take 5 L of
-- biodiesel; the pickup van must refuse 5 L of petrol poured without
-- confirmation; the trade van must start on its petrol.
------------------------------------------------------------------------------
RT.DV = { cars = {},
    batches = { { { "Base.VanSeats", true }, { "Base.VanRadio", true }, { "Base.PickUpTruck", false } },
        { { "Base.VanAmbulance", true }, { "Base.PickUpVanLightsFire", true }, { "Base.Van", false } } } }

function RT.DV.batch(n)
    return { name = "rtdv_batch_" .. n, timeout = 1200, fn = function(ctx, ticks)
        local V, DV = TLG.Integration.Vehicles, RT.DV
        if ticks < 30 then return nil end
        if not ctx.spawned then
            if n == 1 then
                local world = TLG.World.get()
                R:check("RTDV.new_world_has_diesel_chassis", function()
                    return world.dieselVehicles == true, string.format("dieselVehicles=%s createdAsNewGame=%s policy=%s modVersion=%s",
                        tostring(world.dieselVehicles), tostring(world.createdAsNewGame), tostring(world.policy), tostring(world.modVersion))
                end)
            end
            for i, spec in ipairs(DV.batches[n]) do
                local v = addVehicleDebug(spec[1], IsoDirections.N, nil, sq(START.x + 5 * i - 2, START.y + 3, 0))
                if v then pcall(function() v:repair() end) end
                DV.cars[i] = v
            end
            ctx.spawned = ticks
            return nil
        end
        if ticks - ctx.spawned < 60 then return nil end
        if not ctx.filled then
            for i = 1, 3 do
                local tank = DV.cars[i] and DV.cars[i]:getPartById("GasTank")
                if tank then
                    tank:setContainerContentAmount(10)
                    tank:getModData().tlg = nil
                end
            end
            ctx.filled = ticks
            return nil
        end
        if ticks - ctx.filled < 10 then return nil end
        for i, spec in ipairs(DV.batches[n]) do
            local v = DV.cars[i]
            local name = string.gsub(spec[1], "^Base%.", "")
            R:check("RTDV.profile_" .. name, function()
                if v == nil then return false, "not spawned" end
                local rec, status = V.read(v, false)
                local e = V.evaluate(v)
                local wantProfile, wantFuel = spec[2] and "engine_ci_stock" or "engine_si_stock", spec[2] and "diesel" or "gasoline"
                return V.isDieselChassis(v:getScriptName()) == spec[2] and V.baseProfile(v) == wantProfile and V.profile(v) == wantProfile
                    and rec ~= nil and (rec.q[wantFuel] or 0) > 9.9 and e ~= nil and e.compatible == true,
                    string.format("script %s; profile %s; record %s; %s", tostring(v:getScriptName()), tostring(V.profile(v)),
                        viewText(rec, status), evaluationText(e))
            end)
        end
        if n == 1 then
            for i = 1, 3 do
                if DV.cars[i] then pcall(function() DV.cars[i]:permanentlyRemove() end) end
                DV.cars[i] = nil
            end
        end
        return true
    end }
end

RT.dieselVehicleSteps = { RT.waitWorld, RT.BD.photoSetup, RT.DV.batch(1), RT.DV.batch(2),
    vehicleGateStep("RTDV.ambulance_starts_on_diesel", function() return RT.DV.cars[1] end, false, true),
    vehiclePourStep("RTDV.ambulance_takes_biodiesel", { { Fluid.Get("TLG_Biodiesel"), 5.0 } }, false, true,
        function() return RT.DV.cars[1] end),
    vehiclePourStep("RTDV.pickup_van_refuses_petrol", { { Fluid.Petrol, 5.0 } }, false, false, function() return RT.DV.cars[2] end),
    vehicleGateStep("RTDV.trade_van_starts_on_petrol", function() return RT.DV.cars[3] end, false, true),
    RT.MI.zoomTo("rtdv_zoom", 1.0), RT.MI.shot("rtdv_vehicles", true), RT.finish }

------------------------------------------------------------------------------
-- Diesel at some pumps (request "sp-rtdp", D-036). A new world. The
-- station's pumps are found and what each would give by the world's own
-- draw is listed. Two untouched pumps then get their first record with
-- the draw's share held at 1 and at 0 (a fixture: the world's own draw may
-- give this station no diesel pump): one diesel, one petrol. The pump
-- menu's entry must say what each gives. From the diesel pump a can is
-- filled with vanilla's ISTakeFuel and an ambulance's empty tank with
-- vanilla's ISRefuelFromGasPump: both must hold diesel, litre for litre,
-- the can's fluids included, and the ambulance must start. From the petrol
-- pump a pickup van's empty tank is filled the same way: it must hold
-- petrol and its start must be refused.
------------------------------------------------------------------------------
RT.DP = { pumps = {}, cars = {} }

RT.DP.find = { name = "rtdp_find", timeout = 1200, fn = function(ctx, ticks)
    local DP, S, W = RT.DP, TLG.Integration.Stations, TLG.Domain.WorldInit
    if ticks < 60 then return nil end
    if not ctx.done then
        captureDialogs(true)
        local world = TLG.World.get()
        R:check("RTDP.new_world_has_diesel", function()
            return world.dieselVehicles == true, "dieselVehicles=" .. tostring(world.dieselVehicles)
        end)
        local drawn, diesel = {}, 0
        for x = STATION.x0, STATION.x1 do
            for y = STATION.y0, STATION.y1 do
                local s = sq(x, y, 0)
                local objs = s and s:getObjects()
                for i = 0, (objs and objs:size() or 0) - 1 do
                    local o = objs:get(i)
                    if o:getPipedFuelAmount() > 0 and S.isPump(o) then
                        local p = S.product(o)
                        if p == "diesel" then diesel = diesel + 1 end
                        drawn[#drawn + 1] = string.format("%d,%d=%s", x, y, p)
                        DP.pumps[#DP.pumps + 1] = { obj = o, x = x, y = y, drawn = p, untouched = o:getModData().tlg == nil }
                    end
                end
            end
        end
        R:line("OBS  RTDP.drawn %d pumps, %d diesel by this world's draw (share %.2f): %s", #DP.pumps, diesel,
            W.STATION_DIESEL_SHARE, table.concat(drawn, " "))
        if #DP.pumps < 2 then
            RT.abort = "fewer than two pumps at the station"
            return true
        end
        local share = W.STATION_DIESEL_SHARE
        DP.diesel, DP.petrol = DP.pumps[1], DP.pumps[2]
        for _, t in ipairs({ { DP.diesel, 1 }, { DP.petrol, 0 } }) do
            W.STATION_DIESEL_SHARE = t[2]
            local rec = S.read(t[1].obj, true)
            S.writeSidecar(t[1].obj, rec)
        end
        W.STATION_DIESEL_SHARE = share
        local d, p = tlgView("pump", DP.diesel.obj), tlgView("pump", DP.petrol.obj)
        R:check("RTDP.one_pump_diesel_one_petrol", function()
            return d ~= nil and p ~= nil and (d.q.diesel or 0) > 1 and (d.q.gasoline or 0) == 0 and (p.q.gasoline or 0) > 1
                and (p.q.diesel or 0) == 0 and S.product(DP.diesel.obj) == "diesel" and S.product(DP.petrol.obj) == "gasoline",
                string.format("pump %d,%d %s | pump %d,%d %s", DP.diesel.x, DP.diesel.y, viewText(d, "-"), DP.petrol.x, DP.petrol.y,
                    viewText(p, "-"))
        end)
        for i, spec in ipairs({ "Base.VanAmbulance", "Base.PickUpVan" }) do
            local v = addVehicleDebug(spec, IsoDirections.N, nil, sq(START.x + 5 * i - 2, START.y + 3, 0))
            if v then pcall(function() v:repair() end) end
            DP.cars[i] = v
        end
        ctx.done = ticks
        return nil
    end
    if ticks - ctx.done < 60 then return nil end
    for i = 1, 2 do
        local tank = DP.cars[i] and DP.cars[i]:getPartById("GasTank")
        if tank then
            tank:setContainerContentAmount(0)
            tank:getModData().tlg = nil
        end
    end
    return true
end }

-- The pump menu's entry, clicked beside the pump: the dialog the player reads.
function RT.DP.label(name, getPump, fuel)
    return { name = name, timeout = 600, fn = function(ctx, ticks)
        if RT.skip(name) then return true end
        local pump = getPump()
        if ticks == 1 then player():teleportTo(pump.x + 1, pump.y, 0) end
        if ticks < 40 then return nil end
        local context = ISContextMenu.get(0, 100, 100)
        TLG.UI.FuelMenu.fillWorld(0, context, { pump.obj }, false)
        local opt = context:getOptionFromName(getText("ContextMenu_TLG_PumpProduct"))
        context:setVisible(false)
        local before = #H.dialogs.texts
        local reply = opt and click(opt) or nil
        local text = H.dialogs.texts[before + 1]
        closeDialogs()
        R:check("RTDP." .. name, function()
            return opt ~= nil and reply ~= nil and reply.ok == true and reply.primary == fuel
                and text == getText("IGUI_TLG_PumpGives", getText("IGUI_TLG_Fuel_" .. fuel)) and not has(text, "IGUI_TLG"),
                string.format("entry=%s reply ok=%s primary=%s reason=%s dialog=%s", tostring(opt ~= nil), tostring(reply and reply.ok),
                    tostring(reply and reply.primary), tostring(reply and reply.reason), tostring(text))
        end)
        return true
    end }
end

RT.DP.can = actionStep("rtdp_pump_to_can", function(ctx)
    if RT.skip("rtdp_pump_to_can") then return nil end
    local pump = RT.DP.diesel
    local can, fc = giveCan("Base.JerryCan")
    player():setPrimaryHandItem(can)
    player():teleportTo(pump.x + 1, pump.y, 0)
    ctx.can, ctx.fc, ctx.units = can, fc, pump.obj:getPipedFuelAmount()
    hopBegin(ctx, "RTDP.diesel_pump_to_can", "pump", pump.obj, pumpAmount(pump.obj), "item", can, canAmount(fc))
    return ISTakeFuel:new(player(), pump.obj, can)
end, function(ctx)
    local moved = hopEnd(ctx, true)
    local comp, foreign = TLG.Integration.Native.readComposition(ctx.fc)
    local units = RT.DP.diesel.obj:getPipedFuelAmount()
    R:check("RTDP.can_holds_diesel", function()
        return (comp.diesel or 0) > 1 and (comp.gasoline or 0) == 0 and foreign == 0 and not ctx.fc:contains(Fluid.Petrol)
            and math.abs((ctx.units - units) - moved) < 1.01, string.format("fluids %s; pump units %d -> %d for %.4f L",
            TLGH.fluidSummary(ctx.fc), ctx.units, units, moved)
    end)
    player():setPrimaryHandItem(nil)
end)

-- A vehicle's empty tank filled at a pump with vanilla's action.
function RT.DP.refuel(name, getPump, getCar, fuel)
    return { name = name, timeout = 7000, fn = function(ctx, ticks)
        if not ctx.queued and RT.skip(name) then return true end
        local pump, v = getPump(), getCar()
        local part = v and v:getPartById("GasTank")
        if not part then R:line("SKIP %s: no vehicle", name); return true end
        if not ctx.queued then
            ctx.try = ctx.try or 0
            if ctx.placedAt == nil then
                ctx.try = ctx.try + 1
                local o = AREA_OFFSETS[ctx.try]
                if o == nil then R:line("SKIP %s: never in the fuel-cap area", name); return true end
                local c = v:getAreaCenter(part:getArea())
                ctx.target = { x = c:getX() + o[1], y = c:getY() + o[2] }
                player():teleportTo(math.floor(ctx.target.x), math.floor(ctx.target.y), 0)
                ctx.placedAt = ticks
                return nil
            end
            if ticks - ctx.placedAt == 5 then player():setPosition(ctx.target.x, ctx.target.y, 0) end
            if ticks - ctx.placedAt < 20 then return nil end
            if not v:isInArea(part:getArea(), player()) then ctx.placedAt = nil; return nil end
            hopBegin(ctx, "RTDP." .. name, "pump", pump.obj, pumpAmount(pump.obj), "vehicle", v, tankAmount(part))
            ISTimedActionQueue.add(ISRefuelFromGasPump:new(player(), part, pump.obj))
            ctx.queued, ctx.t1 = true, ticks
            return nil
        end
        if ticks - ctx.t1 < 10 or not TLGH.Steps.actionsIdle(player()) then return nil end
        local _, dv = hopEnd(ctx, true)
        local other = fuel == "diesel" and "gasoline" or "diesel"
        R:check("RTDP." .. name .. ".tank_holds_" .. fuel, function()
            return dv ~= nil and (dv.q[fuel] or 0) > 1 and (dv.q[other] or 0) == 0,
                viewText(dv, "-") .. "; " .. evaluationText(TLG.Integration.Vehicles.evaluate(v))
        end)
        return true
    end }
end

RT.dieselPumpSteps = { RT.waitWorld, RT.BD.photoSetup, RT.DP.find,
    RT.DP.label("label_diesel", function() return RT.DP.diesel end, "diesel"),
    RT.DP.label("label_petrol", function() return RT.DP.petrol end, "gasoline"),
    RT.DP.can,
    RT.DP.refuel("ambulance_at_the_diesel_pump", function() return RT.DP.diesel end, function() return RT.DP.cars[1] end, "diesel"),
    vehicleGateStep("RTDP.ambulance_starts", function() return RT.DP.cars[1] end, false, true),
    RT.DP.refuel("pickup_van_at_the_petrol_pump", function() return RT.DP.petrol end, function() return RT.DP.cars[2] end, "gasoline"),
    -- Petrol in a diesel lowers the start factor to 0.25 (D-037): refused
    -- with the roll held above it.
    RT.rollStep("rtdp_roll_held", 0.999),
    vehicleGateStep("RTDP.pickup_van_refused", function() return RT.DP.cars[2] end, true),
    RT.rollStep("rtdp_roll_free", nil),
    RT.finish }

RT.biodieselSteps = { RT.waitWorld, RT.setup, RT.MM.clearSky, RT.BD.row,
    RT.BD.stand("rtbd_stand_row", 0), RT.MI.zoomTo("rtbd_zoom", 0.5), RT.MI.shot("rtbd_row", true),
    RT.MI.zoomTo("rtbd_zoom_close", 0.25),
    RT.BD.stand("rtbd_stand_left", -3), RT.MI.shot("rtbd_vessel_retort_barrel", true),
    RT.BD.stand("rtbd_stand_middle", 0), RT.MI.shot("rtbd_barrel_leacher", true),
    RT.BD.stand("rtbd_stand_right", 3), RT.MI.shot("rtbd_leacher_reactor_tank", true),
    RT.MI.zoomTo("rtbd_zoom_back", 1.0), RT.BD.stand("rtbd_stand_back", 0),
    RT.BD.setup, RT.BD.static, RT.BD.run, RT.finish }

------------------------------------------------------------------------------
-- Wrong fuel damages engines (request "sp-rtwf"; D-037). A new world, so the
-- ambulance and the fire department's pickup van are diesel. A petrol car, the
-- two diesels, a petrol generator and a Diesel Generator are given tanks of
-- known blends (written as the mod's record and the game's litres), and each
-- mechanism is seen once: the verdict for every band; a start refused by
-- diesel in the petrol car, which must cost engine condition and battery
-- charge and tell the driver; engine and exhaust wear by the litre on a
-- petrol car that runs on a fifth diesel; a pour of petrol into the
-- ambulance refused until confirmed; the ambulance running on a third petrol
-- and wearing; the pickup van failing on pure petrol when the draw says so;
-- the cure the player guide gives (the tank siphoned, diesel poured, a clean
-- start); the same for the generators, with the mod's drain as the cure; and
-- the sandbox option off. Every roll is held. Litres "burned" are taken out
-- of the tank by the step while the engine runs: the mod sees the drop at
-- its next minute, as it sees the game's own burn.
------------------------------------------------------------------------------
RT.WF = { cars = {}, gens = {}, scripts = { "Base.CarNormal", "Base.VanAmbulance", "Base.PickUpVanLightsFire" } }

function RT.WF.fresh(q)
    local total, deg, copy = 0, {}, {}
    for id, x in pairs(q) do total, deg[id], copy[id] = total + x, 0, x end
    return copy, deg, total
end

-- A tank holding exactly `q` (litres by fuel id), fresh.
function RT.WF.setTank(v, q)
    local V = TLG.Integration.Vehicles
    local tank = v:getPartById("GasTank")
    local qq, deg, total = RT.WF.fresh(q)
    tank:setContainerContentAmount(total)
    tank:getModData().tlg = nil
    local rec = V.read(v, true)
    rec.q, rec.deg, rec.rev = qq, deg, (rec.rev or 0) + 1
    V.writeSidecar(v, rec)
    V.lastTank[v:getId()] = nil
end

function RT.WF.setGen(g, q)
    local G = TLG.Integration.Generators
    local qq, deg, total = RT.WF.fresh(q)
    g:setFuel(total)
    g:getModData().tlg = nil
    local rec = G.read(g, true)
    rec.q, rec.deg, rec.rev = qq, deg, (rec.rev or 0) + 1
    G.writeSidecar(g, rec)
end

function RT.WF.charge(v)
    local item = v:getPartById("Battery") and v:getPartById("Battery"):getInventoryItem()
    return item and item:getCurrentUsesFloat() or -1
end

-- A part's condition; nil for an exhaust that is not fitted (the engine is
-- a part without an item).
function RT.WF.partCondition(v, id)
    local p = v:getPartById(id)
    if p == nil or (id ~= "Engine" and p:getInventoryItem() == nil) then return nil end
    return p:getCondition()
end

-- The rolls held: starts always pass the roll, nothing fails unless a step
-- says so.
function RT.WF.hold()
    local V, G, WF = TLG.Integration.Vehicles, TLG.Integration.Generators, RT.WF
    WF.saved = WF.saved or { V.startRoll, V.failRoll, G.startRoll, G.failRoll, V.stallRoll }
    V.startRoll, G.startRoll = function() return 0 end, function() return 0 end
    V.failRoll, G.failRoll = function() return 0.999 end, function() return 0.999 end
    -- Nor does a running engine stall on its poor start factor: launch 280's
    -- petrol car, on a fifth diesel, had stopped before its litres were taken.
    V.stallRoll = function() return 0.999 end
end

function RT.WF.release()
    local V, G, WF = TLG.Integration.Vehicles, TLG.Integration.Generators, RT.WF
    if WF.saved then
        V.startRoll, V.failRoll, G.startRoll, G.failRoll, V.stallRoll = WF.saved[1], WF.saved[2], WF.saved[3], WF.saved[4], WF.saved[5]
    end
    WF.saved = nil
end

RT.WF.spawn = { name = "rtwf_spawn", timeout = 1200, fn = function(ctx, ticks)
    local WF = RT.WF
    if ticks < 30 then return nil end
    if not ctx.spawned then
        captureDialogs(true)
        WF.hold()
        local world = TLG.World.get()
        R:check("RTWF.new_world_with_diesel_and_damage_on", function()
            return world.dieselVehicles == true and TLG.Integration.Vehicles.wrongFuelDamageEnabled() == true,
                string.format("dieselVehicles=%s; SandboxVars.TheLastGallon.WrongFuelDamage=%s; the mod loaded is %s",
                    tostring(world.dieselVehicles), tostring(SandboxVars.TheLastGallon and SandboxVars.TheLastGallon.WrongFuelDamage),
                    tostring(TLG.VERSION))
        end)
        -- The generators north of the start, the vehicles south of it.
        local spots = {}
        for _, dx in ipairs({ -2, -4, -6, 2, 4, 6, -8, 8 }) do
            for _, dy in ipairs({ -3, -5, -2, -4 }) do
                if #spots < 2 and RT.MI.clear(START.x + dx, START.y + dy) and RT.MI.clear(START.x + dx + 1, START.y + dy) then
                    local taken = false
                    for _, s in ipairs(spots) do if s:getX() == START.x + dx then taken = true end end
                    if not taken then spots[#spots + 1] = sq(START.x + dx, START.y + dy, 0) end
                end
            end
        end
        for i, t in ipairs({ "Base.Generator", "TLG.DieselGenerator" }) do
            if spots[i] then
                local ok, g = pcall(function() return IsoGenerator.new(instanceItem(t), getCell(), spots[i]) end)
                if ok and g then WF.gens[i] = g else R:line("OBS  RTWF.generator %s not put down: %s", t, tostring(g)) end
            end
        end
        for i, script in ipairs(WF.scripts) do
            local v = addVehicleDebug(script, IsoDirections.N, nil, sq(START.x + 5 * i - 2, START.y + 3, 0))
            if v then pcall(function() v:repair() end) end
            WF.cars[i] = v
        end
        ctx.spawned = ticks
        return nil
    end
    if ticks - ctx.spawned < 60 then return nil end
    local V, G = TLG.Integration.Vehicles, TLG.Integration.Generators
    local parts = {}
    for i = 1, 3 do
        local v = WF.cars[i]
        parts[#parts + 1] = v and string.format("%s %s engine %s exhaust %s battery %.3f", tostring(v:getScriptName()), tostring(V.profile(v)),
            tostring(WF.partCondition(v, "Engine")), tostring(WF.partCondition(v, "Muffler")), WF.charge(v)) or "none"
    end
    for i = 1, 2 do
        local g = WF.gens[i]
        parts[#parts + 1] = g and string.format("%s %s condition %s", tostring(g:getModData().generatorFullType), tostring(G.profile(g)),
            tostring(g:getCondition())) or "none"
    end
    R:check("RTWF.engines_ready", function()
        return WF.cars[1] ~= nil and WF.cars[2] ~= nil and WF.cars[3] ~= nil and WF.gens[1] ~= nil and WF.gens[2] ~= nil
            and V.profile(WF.cars[1]) == "engine_si_stock" and V.profile(WF.cars[2]) == "engine_ci_stock"
            and V.profile(WF.cars[3]) == "engine_ci_stock" and G.profile(WF.gens[1]) == "generator_si_stock"
            and G.profile(WF.gens[2]) == "generator_ci_bio", table.concat(parts, "; ")
    end)
    if not (WF.cars[1] and WF.cars[2] and WF.cars[3] and WF.gens[1] and WF.gens[2]) then RT.abort = "an engine is missing" end
    return true
end }

-- The verdict for each band, on the game's own vehicles.
RT.WF.verdicts = { name = "rtwf_verdicts", timeout = 600, fn = function()
    local WF, V, Fmt = RT.WF, TLG.Integration.Vehicles, TLG.UI.Format
    if RT.abort then return true end
    local cases = {
        { 1, "petrol_car_5pc_diesel", { gasoline = 9.5, diesel = 0.5 }, true, 1, "diesel" },
        { 1, "petrol_car_20pc_diesel", { gasoline = 8, diesel = 2 }, true, 2, "diesel" },
        { 1, "petrol_car_40pc_diesel", { gasoline = 6, diesel = 4 }, false, 4, "diesel" },
        { 1, "petrol_car_20pc_biodiesel", { gasoline = 8, biodiesel = 2 }, true, 2, "biodiesel" },
        { 1, "petrol_car_40pc_ethanol", { gasoline = 6, ethanol = 4 }, true, 2, "ethanol" },
        { 1, "petrol_car_pure_ethanol", { ethanol = 10 }, true, 3, "ethanol" },
        { 2, "ambulance_10pc_petrol", { diesel = 9, gasoline = 1 }, true, 1, "gasoline" },
        { 2, "ambulance_30pc_petrol", { diesel = 7, gasoline = 3 }, true, 2, "gasoline" },
        { 2, "ambulance_pure_petrol", { gasoline = 10 }, true, 3, "gasoline" },
        { 2, "ambulance_5pc_ethanol", { diesel = 9.5, ethanol = 0.5 }, true, 2, "ethanol" },
        { 2, "ambulance_20pc_ethanol", { diesel = 8, ethanol = 2 }, true, 3, "ethanol" },
        { 2, "ambulance_40pc_ethanol", { diesel = 6, ethanol = 4 }, false, 4, "ethanol" },
        { 2, "ambulance_pure_diesel", { diesel = 10 }, true, nil, nil },
        { 1, "petrol_car_pure_petrol", { gasoline = 10 }, true, nil, nil },
    }
    for _, c in ipairs(cases) do
        local v = WF.cars[c[1]]
        WF.setTank(v, c[3])
        local e = V.evaluate(v)
        local text = Fmt.evaluation(e)
        R:check("RTWF.verdict_" .. c[2], function()
            local line = (not c[4]) and getText("IGUI_TLG_NotCompatible") or (c[5] and getText("IGUI_TLG_Harmful"))
                or getText("IGUI_TLG_Compatible")
            return e ~= nil and e.compatible == c[4] and e.wrongLevel == c[5] and e.wrongFuel == c[6]
                and (e.harmful == true) == (c[5] ~= nil) and has(text, line),
                string.format("%s; wear %.2f power %.2f failure %s exhaust %s attempt %s; text: %s", evaluationText(e), e.wearFactor,
                    e.powerFactor, tostring(e.failureChance), tostring(e.exhaustWear), brief(e.attemptDamage), tostring(text))
        end)
    end
    return true
end }

-- Sets a blend before a step and notes what the engine, exhaust and battery
-- stand at.
function RT.WF.prepare(name, i, q)
    return { name = name, timeout = 60, fn = function()
        local WF = RT.WF
        if RT.abort then return true end
        local v = WF.cars[i]
        WF.setTank(v, q)
        TLG.Notify.last = nil
        WF.before = { engine = WF.partCondition(v, "Engine"), muffler = WF.partCondition(v, "Muffler"), charge = WF.charge(v),
            tank = v:getPartById("GasTank"):getContainerContentAmount() }
        return true
    end }
end

RT.WF.afterRefused = { name = "rtwf_after_refused", timeout = 60, fn = function()
    local WF = RT.WF
    if RT.abort then return true end
    local v, b = WF.cars[1], WF.before
    local taken, used = b.engine - WF.partCondition(v, "Engine"), b.charge - WF.charge(v)
    local note = TLG.Notify.last
    R:check("RTWF.refused_start_costs_engine_and_battery", function()
        return (taken == 1 or taken == 2) and used > TLG.Integration.Vehicles.ATTEMPT_BATTERY - 1e-4 and used < 0.05,
            string.format("engine %s -> %s (%d taken); battery charge %.4f -> %.4f (%.4f used)", tostring(b.engine),
                tostring(WF.partCondition(v, "Engine")), taken, b.charge, WF.charge(v), used)
    end)
    R:check("RTWF.refused_start_tells_the_driver", function()
        return note ~= nil and note.key == "IGUI_TLG_Note_StartDamage" and note.fuel == "diesel"
            and has(note.text, getText("IGUI_TLG_Fuel_diesel")), note and tostring(note.text) or "no note"
    end)
    return true
end }

-- The engine started and kept running while `litres` leave the tank; `done`
-- judges what the mod took for them. `fail` holds the failure draw at 0 for
-- those litres.
function RT.WF.burn(name, i, litres, fail, done)
    return { name = name, timeout = 9000, fn = function(ctx, ticks)
        local WF, V = RT.WF, TLG.Integration.Vehicles
        if RT.abort then return true end
        local v = WF.cars[i]
        if not ctx.phase then
            pcall(function() v:setHotwired(true) end)
            v:enter(0, player())
            ctx.phase, ctx.tick, ctx.tries = "start", ticks, 0
            return nil
        end
        if ctx.phase == "start" then
            if v:isEngineRunning() then
                -- The line a start on harmful fuel shows the driver.
                local note, e0 = TLG.Notify.last, V.evaluate(v)
                R:check(name .. ".start_names_the_wrong_fuel", function()
                    return e0.harmful == true and note ~= nil and note.key == "IGUI_TLG_Note_WrongFuel" and note.fuel == e0.wrongFuel
                        and has(note.text, getText("IGUI_TLG_Fuel_" .. tostring(e0.wrongFuel))),
                        note and tostring(note.text) or "no line shown"
                end)
                ctx.phase, ctx.h = "settle", hours()
                return nil
            end
            if (ticks - ctx.tick) % 240 == 30 and ctx.tries < 6 then
                ctx.tries = ctx.tries + 1
                ISTimedActionQueue.add(ISStartVehicleEngine:new(player()))
            end
            if ticks - ctx.tick > 1800 then
                R:check(name .. ".engine_started", function()
                    return false, string.format("not running after %d tries (state %s; %s)", ctx.tries, tostring(v:getEngineState()),
                        evaluationText(V.evaluate(v)))
                end)
                pcall(function() v:exit(player()) end)
                return true
            end
            return nil
        end
        if ctx.phase == "settle" then
            -- A minute's pass of the mod with the engine running, so that it
            -- knows the tank; then the litres go.
            if hours() - ctx.h < 2.5 / 60 then return nil end
            local tank, engine = v:getPartById("GasTank"), v:getPartById("Engine")
            ctx.e = V.evaluate(v)
            ctx.tank0 = tank:getContainerContentAmount()
            ctx.engine0, ctx.muffler0 = engine:getCondition(), WF.partCondition(v, "Muffler")
            ctx.carry0 = engine:getModData()[V.WEAR_KEY] or 0
            local muffler = v:getPartById("Muffler")
            ctx.mcarry0 = muffler and muffler:getModData()[V.WEAR_KEY] or 0
            if fail then V.failRoll = function() return 0 end end
            TLG.Notify.last = nil
            tank:setContainerContentAmount(ctx.tank0 - litres)
            ctx.phase, ctx.h = "burn", hours()
            return nil
        end
        if hours() - ctx.h < 2.5 / 60 then return nil end
        local tank, engine = v:getPartById("GasTank"), v:getPartById("Engine")
        local burned = ctx.tank0 - tank:getContainerContentAmount()
        local perLitre = TLG.Domain.EngineEffects.vehicleWearPerLitre(SandboxVars and SandboxVars.CarGasConsumption)
        local r = { v = v, e = ctx.e, burned = burned, running = v:isEngineRunning(),
            taken = ctx.engine0 - engine:getCondition(), carry = engine:getModData()[V.WEAR_KEY] or 0, carry0 = ctx.carry0,
            due = ctx.carry0 + burned * (ctx.e.wearFactor - 1) * perLitre, perLitre = perLitre,
            muffler0 = ctx.muffler0, muffler = WF.partCondition(v, "Muffler"), mcarry0 = ctx.mcarry0,
            mcarry = v:getPartById("Muffler") and v:getPartById("Muffler"):getModData()[V.WEAR_KEY] or 0, note = TLG.Notify.last }
        R:line("OBS  %s %s; ran on it: %.4f L gone (%.2f taken by the step); engine %s -> %s, carry %.4f -> %.4f; exhaust %s -> %s; running=%s",
            name, evaluationText(ctx.e), burned, litres, tostring(ctx.engine0), tostring(engine:getCondition()), ctx.carry0, r.carry,
            tostring(ctx.muffler0), tostring(r.muffler), tostring(r.running))
        done(r)
        V.failRoll = function() return 0.999 end
        pcall(function() v:shutOff() end)
        pcall(function() v:engineDoShuttingDown() end)
        pcall(function() v:exit(player()) end)
        return true
    end }
end

-- A vanilla siphon of the tank into a new empty can, standing at the fuel cap.
function RT.WF.siphon(name, i)
    return { name = name, timeout = 4000, fn = function(ctx, ticks)
        local WF = RT.WF
        if RT.abort then return true end
        local v = WF.cars[i]
        local part = v:getPartById("GasTank")
        if not ctx.placedAt then
            local c = v:getAreaCenter(part:getArea())
            ctx.target = { x = c:getX(), y = c:getY() }
            player():teleportTo(math.floor(ctx.target.x), math.floor(ctx.target.y), 0)
            ctx.placedAt = ticks
            return nil
        end
        if ticks - ctx.placedAt == 5 then player():setPosition(ctx.target.x, ctx.target.y, 0) end
        if ticks - ctx.placedAt < 20 then return nil end
        if not ctx.queued then
            if part:getContainerContentAmount() < 0.05 then return true end
            ctx.can, ctx.fc = giveCan("Base.PetrolCan")
            player():setPrimaryHandItem(ctx.can)
            ctx.t0 = part:getContainerContentAmount()
            ISTimedActionQueue.add(ISTakeGasolineFromVehicle:new(player(), part, ctx.can, nil))
            ctx.queued, ctx.t1 = true, ticks
            return nil
        end
        if ticks - ctx.t1 < 10 or not TLGH.Steps.actionsIdle(player()) then return nil end
        local cv, status = tlgView("item", ctx.can)
        WF.siphoned = WF.siphoned or {}
        WF.siphoned[#WF.siphoned + 1] = ctx.can
        R:line("OBS  %s tank %.4f -> %.4f L; the can: %s", name, ctx.t0, part:getContainerContentAmount(), viewText(cv, status))
        R:check(name .. ".can_holds_the_tanks_blend", function()
            local moved = ctx.t0 - part:getContainerContentAmount()
            return cv ~= nil and moved > 0.5 and math.abs(TLG.Domain.Supply.total(cv) - moved) <= 2e-3 and (cv.q.gasoline or 0) > 0
                and (cv.q.diesel or 0) > 0, string.format("%.4f L moved; %s", moved, viewText(cv, status))
        end)
        player():setPrimaryHandItem(nil)
        return true
    end }
end

RT.WF.generators = { name = "rtwf_generators", timeout = 3000, fn = function(ctx, ticks)
    local WF, G, E = RT.WF, TLG.Integration.Generators, TLG.Domain.EngineEffects
    if RT.abort then return true end
    local g1, g2 = WF.gens[1], WF.gens[2]
    if not ctx.phase then
        -- The Diesel Generator, which started on pure petrol in the step
        -- before: a litre gone at 15 times the wear factor, then one that
        -- fails it.
        local e = G.evaluate(g2)
        local note = TLG.Notify.last
        R:check("RTWF.generator_start_names_the_wrong_fuel", function()
            return note ~= nil and note.key == "IGUI_TLG_Note_WrongFuel" and note.fuel == "gasoline",
                note and tostring(note.text) or "no line shown"
        end)
        local perLitre = E.generatorWearPerLitre(G.lowerChanceOneIn(g2), SandboxVars and SandboxVars.GeneratorFuelConsumption)
        -- Running, so that the failure has something to switch off.
        g2:setConnected(true)
        pcall(function() g2:setActivated(true) end)
        ctx.on0 = g2:isActivated()
        G.chargeWear(g2)
        local w = g2:getModData()[G.WEAR_KEY] or {}
        local carry0, cond0 = w.c or 0, g2:getCondition()
        g2:setFuel(g2:getFuel() - 1)
        local whole = G.chargeWear(g2)
        R:check("RTWF.diesel_generator_wears_on_petrol", function()
            local want = math.floor(carry0 + 1 * (e.wearFactor - 1) * perLitre + 1e-9)
            return e.wrongLevel == 3 and whole == want and want >= 4 and g2:getCondition() == cond0 - want and g2:isActivated(),
                string.format("%s; 1 L (%.1f h at the reference load, GeneratorFuelConsumption %s) at wear factor %.2f, %.4f a litre at factor 2: %d points due, %d taken; condition %d -> %d; still on=%s",
                    evaluationText(e), 1 / (E.GENERATOR_REFERENCE_LPH * (SandboxVars.GeneratorFuelConsumption or 1)),
                    tostring(SandboxVars.GeneratorFuelConsumption), e.wearFactor, perLitre, want, whole, cond0, g2:getCondition(),
                    tostring(g2:isActivated()))
        end)
        G.failRoll = function() return 0 end
        g2:setFuel(g2:getFuel() - 1)
        G.chargeWear(g2)
        G.failRoll = function() return 0.999 end
        player():teleportTo(g2:getSquare():getX() + 1, g2:getSquare():getY(), 0)
        ctx.phase, ctx.tick = "dead", ticks
        return nil
    end
    if ctx.phase == "dead" then
        if ticks - ctx.tick < 60 then return nil end
        local valid = "?"
        pcall(function() valid = tostring(ISActivateGenerator:new(player(), g2, true):isValid()) end)
        R:check("RTWF.diesel_generator_fails_on_petrol", function()
            return ctx.on0 == true and g2:getCondition() == 0 and not g2:isActivated() and valid == "false",
                string.format("running before=%s; condition %d after the draw fell; running=%s; the game's switch-on valid=%s",
                    tostring(ctx.on0), g2:getCondition(), tostring(g2:isActivated()), valid)
        end)
        g2:setConnected(false)
        -- The cure for the petrol generator, refused on 40 % diesel: the
        -- mod's drain into a can, then petrol.
        player():teleportTo(g1:getSquare():getX() + 1, g1:getSquare():getY(), 0)
        ctx.phase, ctx.tick = "drain", ticks
        return nil
    end
    if ticks - ctx.tick < 30 then return nil end
    local can, fc = giveCan("Base.PetrolCan")
    local f0 = g1:getFuel()
    local r = ask("RTWF.drain_the_generator", "transfer", { source = TLG.Authority.Resolver.refForObject(g1, "generator"),
        destination = { kind = "item", id = can:getID() }, amount = fc:getFreeCapacity() })
    local cv, cstatus = tlgView("item", can)
    R:check("RTWF.drain_empties_the_generator_into_a_can", function()
        return r.ok == true and g1:getFuel() < 0.01 and cv ~= nil and math.abs(TLG.Domain.Supply.total(cv) - f0) <= 2e-3
            and (cv.q.diesel or 0) > 1.9 and (cv.q.gasoline or 0) > 2.9, string.format(
            "transfer ok=%s; generator %.4f -> %.4f L; the can: %s", tostring(r.ok), f0, g1:getFuel(), viewText(cv, cstatus))
    end)
    local petrol = giveCan("Base.PetrolCan", { { Fluid.Petrol, 3.0 } })
    local r2 = ask("RTWF.petrol_into_the_drained_generator", "transfer", { source = { kind = "item", id = petrol:getID() },
        destination = TLG.Authority.Resolver.refForObject(g1, "generator"), amount = 3 })
    local e = G.evaluate(g1)
    R:check("RTWF.drained_generator_takes_petrol_again", function()
        return r2.ok == true and e.compatible == true and e.harmful ~= true and g1:getFuel() > 2.9,
            string.format("transfer ok=%s reason=%s; %s; fuel %.4f L", tostring(r2.ok), tostring(r2.reason), evaluationText(e), g1:getFuel())
    end)
    return true
end }

RT.WF.genBefore = { name = "rtwf_generators_fuelled", timeout = 60, fn = function()
    local WF = RT.WF
    if RT.abort then return true end
    WF.setGen(WF.gens[1], { gasoline = 3, diesel = 2 })
    WF.setGen(WF.gens[2], { gasoline = 5 })
    WF.genCond0 = WF.gens[1]:getCondition()
    TLG.Notify.last = nil
    return true
end }

RT.WF.genRefused = { name = "rtwf_generator_refused", timeout = 60, fn = function()
    local WF = RT.WF
    if RT.abort then return true end
    local taken, note = WF.genCond0 - WF.gens[1]:getCondition(), TLG.Notify.last
    R:check("RTWF.generator_refused_start_costs_condition", function()
        return (taken == 1 or taken == 2) and note ~= nil and note.key == "IGUI_TLG_Note_StartDamage" and note.fuel == "diesel",
            string.format("condition %d -> %d; note: %s", WF.genCond0, WF.gens[1]:getCondition(), note and tostring(note.text) or "none")
    end)
    return true
end }

-- The sandbox option off: wrong fuel blocks the start and costs nothing.
RT.WF.off = { name = "rtwf_option_off", timeout = 60, fn = function()
    local WF, V, G = RT.WF, TLG.Integration.Vehicles, TLG.Integration.Generators
    if RT.abort then return true end
    local v = WF.cars[2]
    WF.setTank(v, { gasoline = 10 })
    WF.setGen(WF.gens[1], { gasoline = 3, diesel = 2 })
    local on, gon = V.evaluate(v), G.evaluate(WF.gens[1])
    SandboxVars.TheLastGallon.WrongFuelDamage = false
    local off, goff = V.evaluate(v), G.evaluate(WF.gens[1])
    local cond0 = v:getPartById("Engine"):getCondition()
    local taken = V.attemptDamage(v, off, player())
    SandboxVars.TheLastGallon.WrongFuelDamage = true
    R:check("RTWF.option_off_blocks_without_damage", function()
        return on.compatible == true and on.harmful == true and gon.attemptDamage ~= nil and off.compatible == false
            and off.harmful ~= true and off.wearFactor == 1 and goff.compatible == false and goff.attemptDamage == nil
            and taken == 0 and v:getPartById("Engine"):getCondition() == cond0 and V.wrongFuelDamageEnabled() == true,
            string.format("on: %s | off: %s | generator off: %s | points taken by a refused start: %d", evaluationText(on),
                evaluationText(off), evaluationText(goff), taken)
    end)
    WF.release()
    return true
end }

RT.wrongFuelSteps = { RT.waitWorld, RT.BD.photoSetup, RT.WF.spawn, RT.WF.verdicts,
    -- The petrol car: no start on 40 % diesel; wear on 20 %.
    RT.WF.prepare("rtwf_car_40pc_diesel", 1, { gasoline = 6, diesel = 4 }),
    vehicleGateStep("RTWF.petrol_car_on_40pc_diesel", function() return RT.WF.cars[1] end, true), RT.WF.afterRefused,
    RT.WF.prepare("rtwf_car_20pc_diesel", 1, { gasoline = 8, diesel = 2 }),
    RT.WF.burn("RTWF.petrol_car_runs_on_20pc_diesel", 1, 4, false, function(r)
        R:check("RTWF.diesel_wears_a_petrol_engine_and_its_exhaust", function()
            local exhaustDue = r.mcarry0 + r.burned * (r.e.exhaustWear or 0)
            return r.running and r.e.wrongLevel == 2 and r.taken >= 3 and math.abs(r.taken + r.carry - r.due) <= 0.06
                and r.muffler0 ~= nil and math.abs((r.muffler0 - r.muffler) + r.mcarry - exhaustDue) <= 0.06
                and r.muffler0 - r.muffler >= 2, string.format(
                "%.4f L at wear factor %.2f: engine %d taken + %.4f carried, %.4f due; exhaust %s -> %s + %.4f carried, %.4f due",
                r.burned, r.e.wearFactor, r.taken, r.carry, r.due, tostring(r.muffler0), tostring(r.muffler), r.mcarry, exhaustDue)
        end)
    end),
    -- The ambulance: petrol refused by the mod's pour, then confirmed.
    RT.WF.prepare("rtwf_ambulance_diesel", 2, { diesel = 10 }),
    vehiclePourStep("RTWF.petrol_into_the_ambulance_unconfirmed", { { Fluid.Petrol, 5.0 } }, false, false,
        function() return RT.WF.cars[2] end),
    vehiclePourStep("RTWF.petrol_into_the_ambulance_confirmed", { { Fluid.Petrol, 5.0 } }, true, true,
        function() return RT.WF.cars[2] end),
    RT.WF.burn("RTWF.ambulance_runs_on_a_third_petrol", 2, 2, false, function(r)
        R:check("RTWF.petrol_wears_a_diesel_engine", function()
            return r.running and r.e.wrongLevel == 2 and r.e.wrongFuel == "gasoline" and r.taken >= 2
                and math.abs(r.taken + r.carry - r.due) <= 0.06, string.format(
                "%.4f L at wear factor %.2f: %d taken + %.4f carried, %.4f due; still running=%s", r.burned, r.e.wearFactor, r.taken,
                r.carry, r.due, tostring(r.running))
        end)
    end),
    -- The pickup van on pure petrol: it starts, and the draw fails it.
    RT.WF.prepare("rtwf_pickup_pure_petrol", 3, { gasoline = 10 }),
    RT.WF.burn("RTWF.pickup_van_runs_on_pure_petrol", 3, 1, true, function(r)
        local cond = r.v:getPartById("Engine"):getCondition()
        R:check("RTWF.diesel_on_petrol_fails_when_the_draw_falls", function()
            return r.e.wrongLevel == 3 and r.e.failureChance == 0.02 and cond == 0 and not r.running and r.note ~= nil
                and r.note.key == "IGUI_TLG_Note_EngineFailed" and r.note.fuel == "gasoline",
                string.format("failure chance %s a litre; engine condition %d; running=%s; note: %s", tostring(r.e.failureChance), cond,
                    tostring(r.running), r.note and tostring(r.note.text) or "none")
        end)
    end),
    { name = "rtwf_dead_engine", timeout = 1200, fn = function(ctx, ticks)
        if RT.abort then return true end
        local v = RT.WF.cars[3]
        if not ctx.t0 then
            pcall(function() v:setHotwired(true) end)
            v:enter(0, player())
            ctx.t0 = ticks
            return nil
        end
        if ticks - ctx.t0 == 30 then ISTimedActionQueue.add(ISStartVehicleEngine:new(player())) end
        if ticks - ctx.t0 < 330 then return nil end
        R:check("RTWF.failed_engine_does_not_start_again", function()
            return not v:isEngineRunning() and v:getPartById("Engine"):getCondition() == 0,
                string.format("state %s, running=%s, engine condition %d", tostring(v:getEngineState()), tostring(v:isEngineRunning()),
                    v:getPartById("Engine"):getCondition())
        end)
        pcall(function() v:exit(player()) end)
        return true
    end },
    -- The cure: siphon the ambulance, pour diesel, start.
    RT.WF.siphon("RTWF.siphon_the_ambulance_1", 2), RT.WF.siphon("RTWF.siphon_the_ambulance_2", 2),
    vehiclePourStep("RTWF.diesel_into_the_siphoned_ambulance", { { Fluid.Get("TLG_Diesel"), 10.0 } }, false, true,
        function() return RT.WF.cars[2] end),
    { name = "rtwf_ambulance_cured", timeout = 60, fn = function()
        if RT.abort then return true end
        local e = TLG.Integration.Vehicles.evaluate(RT.WF.cars[2])
        R:check("RTWF.siphoned_and_refilled_ambulance_is_clean", function()
            return e.compatible == true and e.harmful ~= true and e.wearFactor == 1, evaluationText(e)
        end)
        return true
    end },
    vehicleGateStep("RTWF.cured_ambulance_starts", function() return RT.WF.cars[2] end, false, true),
    -- The generators.
    RT.WF.genBefore,
    generatorGateStep("RTWF.petrol_generator_on_40pc_diesel", function() return RT.WF.gens[1] end, true), RT.WF.genRefused,
    generatorGateStep("RTWF.diesel_generator_on_pure_petrol", function() return RT.WF.gens[2] end, false),
    RT.WF.generators, RT.WF.off, RT.finish }

------------------------------------------------------------------------------
-- Driving on diesel, biodiesel and wrong fuel (request "sp-rtfd"; D-036,
-- D-037), on the driving mode's cleared road with its crash guards. A new
-- world, so the ambulance is diesel. Each leg's tank is written as the mod's
-- record and the game's litres (a fixture; the pours are other modes'), the
-- engine is started past the gate and the car driven on the cruise control.
-- Nothing is held: the mod's draws for a stall and for a failure are passed
-- through and written down minute by minute (RT.FD.watch), with the litres
-- the mod saw burned and the exhaust points it charged. Each leg is then
-- judged against docs/balance.md's table: the verdict's factors, the power
-- while running, the engine's wear for the litres burned, the exhaust's
-- points, and that the engine stopped in the minute a draw said so and in no
-- other. A leg whose engine stops ends where the car comes to rest.
--   diesel            an ambulance on diesel: nothing lowered, nothing worn
--   biodiesel         an ambulance on biodiesel alone: start x 0.6, power
--                     x 0.85, wear x 1.5 (a stock diesel takes a fifth freely)
--   diesel_in_petrol  a petrol car on a fifth diesel: start x 0.4, power
--                     x 0.6, wear x 6, exhaust 0.5 a litre
--   petrol_in_diesel  an ambulance on 30 % petrol: start x 0.5, power x 0.7,
--                     wear x 8
--   petrol_alone      an ambulance on petrol alone: start x 0.25, power x 0.5,
--                     wear x 15, failure 2 % a litre
--   stall_on_a_fifth_diesel  the petrol car again, and the one draw held: the
--                     stall draw is 0 from 80 tiles on, so it must stall on
--                     the move and coast to a stop (the driving mode's stall
--                     is on a blend the engine cannot take at all)
------------------------------------------------------------------------------
RT.FD = {}

function RT.FD.unwatch()
    local V, K = TLG.Integration.Vehicles, RT.FD.K
    if K and K.orig then
        V.applyEffects, V.stallRoll, V.failRoll, V.applyExhaust = K.orig[1], K.orig[2], K.orig[3], K.orig[4]
        K.orig = nil
    end
end

-- The sandbox's fuel consumption multiplier as the mod reads it.
function RT.FD.consumption()
    local c = SandboxVars and SandboxVars.CarGasConsumption
    if type(c) == "number" and c > 0 then return c end
    return 1
end

-- Passes the mod's minute for `v` through and writes down what went in and
-- what came out: the draws, the litres gone since the minute before, the
-- exhaust points charged.
function RT.FD.watch(v)
    local V, EE, FD = TLG.Integration.Vehicles, TLG.Domain.EngineEffects, RT.FD
    FD.unwatch()
    local K = { v = v, minutes = {}, litres = 0, accrual = 0, exhaustPoints = 0, exhaustWhole = 0, exhaustDue = 0,
        orig = { V.applyEffects, V.stallRoll, V.failRoll, V.applyExhaust } }
    FD.K = K
    V.stallRoll = function()
        local x = K.orig[2]()
        -- K.hold: the one leg that holds a draw (a stall on the move).
        if K.cur and K.hold then x, K.held = 0, (K.held or 0) + 1 end
        if K.cur then K.cur.stall = x end
        return x
    end
    V.failRoll = function()
        local x = K.orig[3]()
        if K.cur then K.cur.fail = x end
        return x
    end
    V.applyExhaust = function(vehicle, points)
        local whole = K.orig[4](vehicle, points)
        if vehicle == K.v then
            K.exhaustPoints, K.exhaustWhole = K.exhaustPoints + points, K.exhaustWhole + whole
        end
        return whole
    end
    V.applyEffects = function(vehicle, rng)
        if vehicle ~= K.v then return K.orig[1](vehicle, rng) end
        local tank = V.tank(vehicle)
        local m = { h = hours(), running = vehicle:isEngineRunning(), last = V.lastTank[vehicle:getId()],
            now = tank and tank:getContainerContentAmount() }
        if m.running then m.e = V.evaluate(vehicle) end
        K.cur = m
        local ok, err = pcall(K.orig[1], vehicle, rng)
        K.cur = nil
        if not ok then m.err = tostring(err) end
        local e = m.e
        if e and e.grade ~= "empty" then
            m.stallOdds = (not e.compatible) and 1 or V.STALL_CHANCE_PER_MINUTE * (1 - e.startFactor)
            if m.last and m.now and m.now < m.last then
                local c = FD.consumption()
                m.burned = m.last - m.now
                m.ref = m.burned / c
                K.litres = K.litres + m.burned
                K.accrual = K.accrual + m.burned * math.max(0, e.wearFactor - 1) * 0.15 / c
                K.exhaustDue = K.exhaustDue + m.ref * (e.exhaustWear or 0)
                if e.failureChance then m.odds = EE.failureOdds(e.failureChance, m.ref) end
            end
        end
        K.minutes[#K.minutes + 1] = m
    end
    return K
end

RT.FD.world = { name = "rtfd_world", timeout = 60, fn = function()
    local world, V = TLG.World.get(), TLG.Integration.Vehicles
    R:check("RTFD.new_world_with_diesel_damage_and_stalls_on", function()
        return world.dieselVehicles == true and V.wrongFuelDamageEnabled() == true and V.stallsEnabled() == true,
            string.format("dieselVehicles=%s WrongFuelDamage=%s VehicleStalls=%s CarGasConsumption=%s; the mod loaded is %s; air %s C",
                tostring(world.dieselVehicles), tostring(SandboxVars.TheLastGallon and SandboxVars.TheLastGallon.WrongFuelDamage),
                tostring(SandboxVars.TheLastGallon and SandboxVars.TheLastGallon.VehicleStalls), tostring(SandboxVars.CarGasConsumption),
                tostring(TLG.VERSION), tostring(RT.temp()))
    end)
    return true
end }

-- The leg's tank: exactly `q` (litres by fuel id), fresh.
function RT.FD.tank(leg, q)
    return { name = "rtfd_tank_" .. leg, timeout = 60, fn = function()
        local v = RT.D.car
        if not v then R:line("SKIP rtfd_tank_%s: no car", leg); return true end
        RT.WF.setTank(v, q)
        R:line("OBS  RTFD.%s.tank %s", leg, viewText(tlgView("vehicle", v)))
        return true
    end }
end

-- `want`: what docs/balance.md gives for the leg's blend in its engine.
function RT.FD.leg(want)
    local FD = RT.FD
    local o = { judge = true, prefix = "RTFD.", alsoWears = { "Engine" }, maxTiles = want.tiles }
    function o.beforeStart(ctx, v, name)
        local V = TLG.Integration.Vehicles
        local engine = v:getPartById("Engine")
        R:check(name .. ".engine_profile", function()
            return V.profile(v) == want.profile, string.format("%s is %s", tostring(v:getScriptName()), tostring(V.profile(v)))
        end)
        ctx.cond0, ctx.carry0 = engine:getCondition(), engine:getModData()[V.WEAR_KEY] or 0
        ctx.muffler0 = RT.WF.partCondition(v, "Muffler")
        FD.watch(v)
    end
    function o.onStart(ctx, v, name)
        local V, EE = TLG.Integration.Vehicles, TLG.Domain.EngineEffects
        local e = ctx.e
        R:check(name .. ".verdict_as_the_table_gives", function()
            local ok = e ~= nil and e.compatible == true and (e.harmful == true) == (want.level ~= nil)
                and e.wrongLevel == want.level and e.wrongFuel == want.wrong and math.abs(e.startFactor - want.start) < 1e-9
                and math.abs(e.powerFactor - want.power) < 1e-9 and math.abs(e.wearFactor - want.wear) < 1e-9
                and e.failureChance == want.failure and e.exhaustWear == want.exhaust
            return ok, string.format("%s; power %s wear %s failure %s exhaust %s level %s of %s; air %s C", evaluationText(e),
                tostring(e and e.powerFactor), tostring(e and e.wearFactor), tostring(e and e.failureChance),
                tostring(e and e.exhaustWear), tostring(e and e.wrongLevel), tostring(e and e.wrongFuel), tostring(RT.temp()))
        end)
        local engine = v:getPartById("Engine")
        local st = engine and engine:getModData()[V.POWER_KEY]
        local base = (st and st.base) or v:getEnginePower()
        ctx.pw = { base = base, target = EE.targetPower(base, want.power), q = v:getEngineQuality(), l = v:getEngineLoudness(),
            h0 = hours(), ran = 0 }
        R:line("OBS  %s.power base %d quality %d loudness %d, at x %s: %d", name, base, ctx.pw.q, ctx.pw.l, tostring(want.power),
            ctx.pw.target)
    end
    function o.onTick(ctx, v, speed, gameMin, progress)
        if want.stallAt and progress >= want.stallAt and FD.K then FD.K.hold = true end
        local pw = ctx.pw
        if not pw or not v:isEngineRunning() then return end
        local p = v:getEnginePower()
        pw.ran = (hours() - pw.h0) * 60
        if v:getEngineQuality() ~= pw.q or v:getEngineLoudness() ~= pw.l then
            pw.features = pw.features or string.format("quality %d loudness %d at %.2f game min", v:getEngineQuality(),
                v:getEngineLoudness(), pw.ran)
        end
        if not pw.reachedAt and p == pw.target then pw.reachedAt = pw.ran end
        if pw.reachedAt and p ~= pw.target and not ctx.braking then
            pw.strayed = pw.strayed or string.format("%d at %.2f game min", p, pw.ran)
        end
    end
    function o.onStopped(ctx, v, name, parts1, runningAtEnd)
        local V = TLG.Integration.Vehicles
        local K = FD.K
        FD.unwatch()
        local engine, tank = v:getPartById("Engine"), v:getPartById("GasTank")
        local cond1, carry1 = engine:getCondition(), engine:getModData()[V.WEAR_KEY] or 0
        local burn = ctx.tank0 - tank:getContainerContentAmount()
        local c = FD.consumption()
        -- The first minute whose draw stops the engine.
        local stop, ran, stalls, fails, errs = nil, 0, {}, {}, {}
        for i, m in ipairs(K.minutes) do
            if m.err then errs[#errs + 1] = m.err end
            if m.running then
                ran = ran + 1
                if m.fail ~= nil then fails[#fails + 1] = string.format("%.4f/%.4f", m.fail, m.odds or -1) end
                if m.stall ~= nil then stalls[#stalls + 1] = string.format("%.4f", m.stall) end
                if not stop then
                    if m.fail ~= nil and m.odds ~= nil and m.fail < m.odds then
                        stop = { kind = "failure", minute = i, h = m.h, draw = m.fail, odds = m.odds }
                    elseif m.stall ~= nil and m.stallOdds ~= nil and m.stall < m.stallOdds then
                        stop = { kind = "stall", minute = i, h = m.h, draw = m.stall, odds = m.stallOdds }
                    end
                end
            end
        end
        local stallOdds
        for _, m in ipairs(K.minutes) do stallOdds = stallOdds or m.stallOdds end
        R:line("OBS  %s.minutes %d with the engine running; stall odds a minute %s; stall draws %s%s; failure draws/odds %s",
            name, ran, tostring(stallOdds), table.concat(stalls, " "),
            K.held and string.format(" (%d held at 0 by the test)", K.held) or "", table.concat(fails, " "))
        R:line("OBS  %s.charged %.6f L of %.6f L burned; engine %d -> %d, carry %.6f -> %.6f, %.6f points due; exhaust %s -> %s, %.6f points charged (%d whole), %.6f due",
            name, K.litres, burn, ctx.cond0, cond1, ctx.carry0, carry1, K.accrual, tostring(ctx.muffler0),
            tostring(RT.WF.partCondition(v, "Muffler")), K.exhaustPoints, K.exhaustWhole, K.exhaustDue)
        R:check(name .. ".the_minutes_ran_clean", function()
            return #errs == 0 and ran >= 1, #errs == 0 and string.format("%d minutes, no error", #K.minutes) or errs[1]
        end)
        R:check(name .. ".the_engine_stops_when_a_draw_says_so_and_only_then", function()
            local s = ctx.stallAt
            if stop == nil then
                return s == nil and runningAtEnd and cond1 > 0, string.format(
                    "no draw below its odds in %d minutes; the engine %s", ran, s and "stopped" or "ran throughout")
            end
            local after = s and (s.h - stop.h) * 60 or nil
            return s ~= nil and after > -0.2 and after < 1.5 and (stop.kind == "failure") == (cond1 == 0), string.format(
                "minute %d: %s draw %.4f below %.4f; the engine %s, condition %d", stop.minute, stop.kind, stop.draw, stop.odds,
                s and string.format("stopped %.2f game min later at %.1f km/h", after, s.speed) or "did not stop", cond1)
        end)
        if stop and stop.kind == "failure" then
            R:line("OBS  %s.wear not judged: the engine failed, its condition is 0", name)
        else
            R:check(name .. ".engine_worn_by_the_litres_burned", function()
                local taken = ctx.cond0 - cond1
                local due = K.litres * (want.wear - 1) * 0.15 / c
                return math.abs((taken + carry1) - (ctx.carry0 + K.accrual)) <= 1e-6 and math.abs(K.accrual - due) <= 1e-6
                    and (want.wear > 1 or (taken == 0 and carry1 == ctx.carry0)), string.format(
                    "%d points taken + %.6f carried = %.6f; %.6f L at wear x %s, 0.15 a litre at x 2, consumption %s: %.6f due",
                    taken, carry1, taken + carry1, K.litres, tostring(want.wear), tostring(c), ctx.carry0 + due)
            end)
        end
        R:check(name .. ".litres_charged_are_the_litres_burned", function()
            local perMinute = burn / math.max(1, ran)
            return K.litres <= burn + 1e-6 and K.litres >= burn - 3 * perMinute - 1e-6 and (ran < 3 or K.litres > 0),
                string.format("%.6f L charged over %d minutes, %.6f L left the tank", K.litres, ran, burn)
        end)
        R:check(name .. ".exhaust_charged_by_the_litre", function()
            local m0, m1 = ctx.muffler0, RT.WF.partCondition(v, "Muffler")
            if want.exhaust == nil then return K.exhaustPoints == 0, string.format("%.6f points", K.exhaustPoints) end
            local due = K.litres / c * want.exhaust
            return math.abs(K.exhaustPoints - due) <= 1e-6 and (ran < 3 or K.exhaustPoints > 0) and m0 ~= nil
                and (m0 - m1) >= K.exhaustWhole, string.format(
                "%.6f points charged, %.6f due for %.6f L at %s a litre; %d whole points taken by the mod, the part %s -> %s",
                K.exhaustPoints, due, K.litres, tostring(want.exhaust), K.exhaustWhole, tostring(m0), tostring(m1))
        end)
        local pw = ctx.pw
        if pw and pw.ran >= 2.0 then
            R:check(name .. ".power_as_the_fuel_allows_while_running", function()
                return pw.reachedAt ~= nil and pw.reachedAt <= 2.0 and pw.strayed == nil and pw.features == nil, string.format(
                    "%d -> %d after %s game min%s; %s", pw.base, pw.target, pw.reachedAt and string.format("%.2f", pw.reachedAt) or "never",
                    pw.strayed and (", then " .. pw.strayed) or ", held",
                    pw.features or string.format("quality %d loudness %d kept", pw.q, pw.l))
            end)
            RT.E.lastPower = { v = v, base = pw.base, q = pw.q, l = pw.l, h = hours(), name = name }
        else
            R:line("OBS  %s.power not judged: the engine ran %.2f game min", name, pw and pw.ran or -1)
        end
        local progress = (v:getY() - ctx.y0) * RT.D.route.dy
        if stop == nil then
            R:check(name .. ".drove", function()
                return progress >= 60 and ctx.maxSpeed >= 15, string.format("%.1f tiles, top %.1f km/h, stopped for %s", progress,
                    ctx.maxSpeed, tostring(ctx.why))
            end)
        else
            R:line("OBS  %s.drove %.1f tiles, top %.1f km/h, before the %s", name, progress, ctx.maxSpeed, stop.kind)
        end
        if want.stallAt then
            R:check(name .. ".stalled_on_the_move_and_coasted", function()
                local s = ctx.stallAt
                return K.held ~= nil and s ~= nil and s.speed >= 10 and s.progress >= want.stallAt and ctx.why == "coasted to a stop"
                    and cond1 > 0, string.format("the stall draw held at 0 from %d tiles: %s; %s, engine condition %d",
                    want.stallAt, s and string.format("stopped at %.1f km/h after %.1f tiles", s.speed, s.progress) or "no stop",
                    tostring(ctx.why), cond1)
            end)
        end
    end
    return o
end

RT.FD.cleanup = { name = "rtfd_cleanup", fn = function()
    RT.FD.unwatch()
    RT.D.releaseEffects()
    RT.D.hookRemove()
    return true
end }

